/**
 * Parses an ISO-8601 period string into a {@link java.time.Period} instance.
 * The parsing rules follow the ISO-8601 period date format.
 * 
 * @param text the period string to parse
 * @return the parsed period
 * @throws DateTimeParseException if the parsing fails
 */
public class IsoPeriod {
    /**
     * The sign of the parsed period, -1 if the period string starts with a minus sign.
     */
    private static final int NEGATIVE_SIGN = -1;

    /**
     * Parses the period string, extracting the sign, and then the period itself.
     * 
     * @param text the period string to parse
     * @return the parsed period
     */
    public static Period parsePeriod(String text) {
        // Determine the sign of the period
        int sign = getSign(text);

        // Remove any non-digit characters except for 'Y', 'M', 'D', and 'W'
        String periodString = extractPeriod(text, sign);

        // Parse the period string into a Period instance
        Period period = Period.parse(periodString);

        // Negate the period if necessary
        return Period.of(period.getYears() * sign,
                period.getMonths() * sign,
                period.getDays() * sign);
    }

    /**
     * Extracts the sign from the period string, or 1 if no sign is present.
     * 
     * @param text the period string to extract the sign from
     * @return the sign of the period, -1 if the period string starts with a minus sign
     */
    private static int getSign(String text) {
        if (text.startsWith("-")) {
            return NEGATIVE_SIGN;
        }
        if (text.startsWith("+")) {
            return 1;
        }
        return 1;
    }

    /**
     * Extracts the period string from the full period string, without the sign.
     * 
     * @param text the full period string
     * @param sign the sign of the period
     * @return the period string, excluding any sign or whitespace
     */
    private static String extractPeriod(String text, int sign) {
        StringBuilder builder = new StringBuilder();
        for (char c : text.toCharArray()) {
            if (Character.isDigit(c)) {
                builder.append(c);
            } else if ("YMDW".contains(String.valueOf(c))
                    || Character.toLowerCase(c) == 'p') {
                builder.append(c);
            }
        }
        return builder.toString();
    }

    public static void main(String[] args) {
        String testCase = "P2Y";
        Period period = parsePeriod(testCase);
        System.out.println(period.getYears());
    }
}

