vector<int> bfs(int start, const vector<vector<int>>& graph, const vector<vector<int>>& reverse_graph, int N) {
    vector<int> dist(N, -1);
    vector<int> parent(N, -1);
    queue<int> q;
    dist[start] = 0;
    q.push(start);

    while (!q.empty()) {
        int current = q.front();
        q.pop();
        for (int neighbor : graph[current]) {
            if (dist[neighbor] == -1) {
                dist[neighbor] = dist[current] + 1;
                parent[neighbor] = current;
                q.push(neighbor);
            }
        }
    }

    P best = {INF, -1};
    for (int target : reverse_graph[start]) {
        if (dist[target] != -1 && dist[target] < best.first) {
            best = {dist[target], target};
        }
    }

    if (best.second == -1) return {};

    vector<int> path;
    for (int at = best.second; at != -1; at = parent[at]) {
        path.push_back(at);
    }
    reverse(path.begin(), path.end());
    return path;
}

int main() {
    int N, M;
    cin >> N >> M;

    vector<vector<int>> graph(N);
    vector<vector<int>> reverse_graph(N);

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        graph[a].push_back(b);
        reverse_graph[b].push_back(a);
    }

    int min_path_length = INF;
    vector<int> best_path;

    for (int i = 0; i < N; ++i) {
        vector<int> path = bfs(i, graph, reverse_graph, N);
        if (path.size() < min_path_length) {
            min_path_length = path.size();
            best_path = path;
        }
    }

    if (min_path_length == INF) {
        cout << -1 << endl;
    } else {
        cout << best_path.size() << endl;
        for (int node : best_path) {
            cout << node + 1 << endl;
        }
    }

    return 0;
}

