public class HistoryRecordManager {

    private final ConcurrentHashMap<String, HistoryRecord> records = new ConcurrentHashMap<>();

    private final ReadWriteLock lock = new ReentrantReadWriteLock();


    public void addRecord(HistoryRecord record) {

        lock.writeLock().lock();

        try {

            records.put(record.getUri(), record);

        } finally {

            lock.writeLock().unlock();

        }

    }


    public List<HistoryRecord> getCongruentRecords(String uri) {

        lock.readLock().lock();

        try {

            return records.values().stream()

                    .filter(record -> record.getUri().equals(uri))

                    .collect(Collectors.toList());

        } finally {

            lock.readLock().unlock();

        }

    }


    public void updateVisibility(String title, Visibility newVisibility) {

        lock.writeLock().lock();

        try {

            HistoryRecord record = records.entrySet().stream()

                    .filter(entry -> entry.getKey().equals(title))

                    .findFirst()

                    .orElseThrow(() -> new IllegalArgumentException("Record not found"));

            record.setVisibility(newVisibility);

        } finally {

            lock.writeLock().unlock();

        }

    }


    public List<HistoryRecord> searchRecordsByKeyword(String keyword) {

        lock.readLock().lock();

        try {

            return records.values().stream()

                    .filter(record -> record.getKeywords().contains(keyword))

                    .collect(Collectors.toList());

        } finally {

            lock.readLock().unlock();

        }

    }


