def logger(ip = None, checkip = True, request = None):
    if ip == None:
        if request is None:
            raise ValueError("IP is not transmitted through a web gateway.")


        headers = request.headers
        xforwardedfor = headers.get('X-Forwarded-For')

        if xforwardedfor:
            ip = xforwardedfor.split(',')[0].strip()
        else:
            ip = request.mechanism.ip

    if checkip:
        ipaddress = ip.split('.')
        if len(ipaddress) != 4:
            raise ValueError("IP address expects x.x.x.x format")

        for segment in ipaddress:
            if int(segment) > 256:
                raise ValueError('IP address value {} does not meet the requirement'.format(segment))
            if not int(segment) >= 1:
                raise ValueError('IP address value {} does not meet the requirement'.format(segment))

        uint32address  = '{0:d}'.format(int(''.join(ipaddress)))
        return uint32address

    return ip

