public class MetricsCollection
{
    private List<Metric> Metrics;

    public MetricsCollection()
    {
        Metrics = new List<Metric>();
    }

    /// <summary>
    /// Adds a new metric to the collection.
    /// </summary>
    /// <param name="metricName">The name of the metric.</param>
    /// <param name="metricValueDistribution">The distribution of metric values.</param>
    public void AddMetric(string metricName, double[] metricValueDistribution)
    {
        if (string.IsNullOrEmpty(metricName))
        {
            throw new ArgumentException("Metric name cannot be null or empty.", nameof(metricName));
        }

        if (metricValueDistribution == null || metricValueDistribution.Length == 0)
        {
            throw new ArgumentException("Metric value distribution cannot be null or empty.", nameof(metricValueDistribution));
        }

        Metrics.Add(new Metric
        {
            MetricName = metricName,
            MetricValueDistribution = metricValueDistribution
        });
    }
}

