public class NearbyHostileEntitiesSensor extends Sensor<MobEntity> {
    public NearbyHostileEntitiesSensor() {
        super(40); // Poll interval in ticks
    }

    @Override
    public Set<MemoryModuleType<?>> getUsedMemories() {
        return ImmutableSet.of(MemoryModuleType.NEARBY_HOSTILE_PLAYER, MemoryModuleType.NEARBY_HOSTILE_CREATURES); // Example memory modules
    }

    @Override
    protected void update(ServerWorld world, MobEntity entity) {
        Brain<?> brain = entity.getBrain();
        List<LivingEntity> nearbyEntities = world.getNearbyEntities(LivingEntity.class, entity.getBoundingBox().grow(16.0D, 4.0D, 16.0D), entity::canEntityBeSeen);

        List<LivingEntity> hostilePlayers = nearbyEntities.stream()
                .filter(LivingEntity::isPlayer)
                .filter(entity::canAttack)
                .collect(Collectors.toList());

        List<LivingEntity> hostileCreatures = nearbyEntities.stream()
                .filter(LivingEntity::isCreatureType)
                .filter(entity::canAttack)
                .collect(Collectors.toList());

        brain.setMemory(MemoryModuleType.NEARBY_HOSTILE_PLAYER, hostilePlayers);
        brain.setMemory(MemoryModuleType.NEARBY_HOSTILE_CREATURES, hostileCreatures);
    }
}

