    public class DirectoryService : IDirectoryService
    {
        private List<Issuer> _issuers = new List<Issuer>();
        private List<Participant> _participants = new List<Participant>();
        private static readonly object Lock = new object();

        public DirectoryResponse GetIssuers()
        {
            var response = new DirectoryResponse();
            response.Issuers = _issuers;
            response.Participants = _participants;
            return response;
        }

        public async Task<DirectoryResponse> GetIssuersAsync()
        {
            return GetIssuers();
        }

        public Issuer CreateIssuer(string issuerName)
        {
            var issuer = new Issuer();
            issuer.IssuerName = issuerName;
            return issuer;
        }

        public string SaveIssuer(Issuer issuer)
        {
            lock (Lock)
            {
                if (!_issuers.Contains(issuer))
                {
                    _issuers.Add(issuer);
                }
                return $"Issuer {issuer.IssuerName} saved successfully";
            }
        }

        public async Task<string> SaveIssuerAsync(Issuer issuer)
        {
            return await Task.Run(() => SaveIssuer(issuer));
        }

        public Issuer LoadIssuer(string issuerName)
        {
            var foundIssuer = _issuers.Find(i => i.IssuerName == issuerName);
            if (foundIssuer == null)
            {
                foundIssuer = CreateIssuer(issuerName);
                return foundIssuer;
            }
            return foundIssuer;
        }

        public async Task<Issuer> LoadIssuerAsync(string issuerName)
        {
            return LoadIssuer(issuerName);
        }
    }
}

void second_tree_traversal(GumboNode* node, GumboStats* stats) {
    if (node == NULL) return;

    // Collect detailed stats for the current node
    // Example: Increment the count of nodes of a specific type
    if (node->type == GUMBO_NODE_ELEMENT) {
        stats->element_count++;
    } else if (node->type == GUMBO_NODE_TEXT) {
        stats->text_count++;
    }

    // Recurse over child nodes
    GumboVector* children = &node->v.element.children;
    for (unsigned int i = 0; i < children->length; i++) {
        second_tree_traversal(children->data[i], stats);
    }
}

