    {
        #region App State Setup

        // Lets components receive change notifications
        // Could have whatever granularity you want (more events, hierarchy...)
        public event Action OnChange;

        private void NotifyStateChanged() => OnChange?.Invoke();

        // Receive 'http' instance from DI
        private readonly HttpClient _httpClient;
        // Browser session storage instance from DI (data stored per tab not shared, no persisted)
        private readonly SessionStorage _sessionStorage;
        // Browser local storage instance from DI (data stored per url, shared between tabs, is persisted)
        private readonly LocalStorage _localStorage;
        // Authentication State
        private readonly Task<AuthenticationState> _authenticationStateTask;

        // Constructor
        public AppState(HttpClient httpClient, LocalStorage localStorage, SessionStorage sessionStorage, Task<AuthenticationState> authenticationStateTask)
        {
            _httpClient = httpClient;
            _localStorage = localStorage;
            _sessionStorage = sessionStorage;
            _authenticationStateTask = authenticationStateTask;
        }

        #endregion

        #region User Authentication

        public async Task<User> GetCurrentUserAsync()
        {
            var user = await _authenticationStateTask;
            if (user?.User?.Identity?.IsAuthenticated == true)
            {
                return new User
                {
                    Id = user.User.FindFirst("id").Value,
                    UserName = user.User.FindFirst("username").Value,
                    Email = user.User.FindFirst("email").Value
                };
            }
            return null;
        }

        public async Task<bool> IsUserAuthenticatedAsync()
        {
            var user = await _authenticationStateTask;
            return user?.User?.Identity?.IsAuthenticated == true;
        }

        public async Task LogoutAsync()
        {
            await _localStorage.DeleteItemAsync("authToken");
            await _sessionStorage.DeleteItemAsync("authToken");
            NotifyStateChanged();
        }

        #endregion

        #region Data Management

        public async Task<T> GetFromLocalStorage<T>(string key)
        {
            return await _localStorage.GetItemAsync<T>(key);
        }

        public async Task SaveToLocalStorage<T>(string key, T value)
        {
            await _localStorage.SetItemAsync(key, value);
            NotifyStateChanged();
        }

        public async Task<T> GetFromSessionStorage<T>(string key)
        {
            return await _sessionStorage.GetItemAsync<T>(key);
        }

        public async Task SaveToSessionStorage<T>(string key, T value)
        {
            await _sessionStorage.SetItemAsync(key, value);
            NotifyStateChanged();
        }

        public async Task<HttpResponseMessage> GetAsync(string requestUri)
        {
            return await _httpClient.GetAsync(requestUri);
        }

        public async Task<HttpResponseMessage> PostAsync<T>(string requestUri, T content)
        {
            return await _httpClient.PostAsJsonAsync(requestUri, content);
        }

        public async Task<HttpResponseMessage> PutAsync<T>(string requestUri, T content)
        {
            return await _httpClient.PutAsJsonAsync(requestUri, content);
        }

        public async Task<HttpResponseMessage> DeleteAsync(string requestUri)
        {
            return await _httpClient.DeleteAsync(requestUri);
        }

        #endregion
    }
}

#include <stdint.h>

#define SHA1_HASH_SIZE 20

typedef struct {
    uint8_t salted[SHA1_HASH_SIZE];
} sha_t;

extern int crypt_sha1(const char *str, const sha_t *salt, char *out, uint32_t size);

/**
 * hash_sha1 -- calculates hash by running SHA1(str,len,out). The only way to access a SHA-1
 *               function or a piece of hashing functionality is via the 'crypt_sha1' routine 
 *               above, but to calculate the actual hash I'm hashing to the "salted-password"
 *               field, as defined by the SHA2 routine found in the above structure, and giving
 *               "str" as the password and ":" appended as salt.
 *
 * @str      -- is the data you want to hash
 * @len      -- the length of the data you want to hash.
 * @hash     -- the target where the function stores the hash. The length of the
 *              array should be SHA1_HASH_SIZE.
 *
 * Return code:
 * 0 -- success
 * -1 -- failure if hash is not of the required length
 */
int hash_sha1(const char *str, size_t len, uint8_t *hash) {
    if (len > SIZE_MAX / 2) {
        return -1;
    }

    sha_t salt;
    snprintf(salt.salted, sizeof(salt.salted), "%s:", str);

    char out[SHA1_HASH_SIZE];
    int result = crypt_sha1(str, &salt, out, sizeof(out));

    if (result != 0) {
        return -1;
    }

    memcpy(hash, out, sizeof(hash));

    return 0;
}

