func hexToByteArray(hexString string) ([]byte, error) {
	hexBytes := []byte(hexString)
	if len(hexBytes)%2 != 0 {
		return nil, fmt.Errorf("hex string must be of even length")
	}
	byteArray := make([]byte, len(hexBytes)/2)
	for i := 0; i < len(hexBytes)/2; i++ {
		hexPair := fmt.Sprintf("%x%x", hexBytes[2*i], hexBytes[2*i+1])
		value, err := strconv.ParseInt(hexPair, 16, 64)
		if err != nil {
			return nil, err
		}
		byteArray[i] = byte(value)
	}
	return byteArray, nil
}

