public class TupleDescriptorImpl {
    // Impl
    private List<Slot> slots;
    private StructType type;

    public TupleDescriptorImpl(StructType type, List<Slot> slots) {
        // Assign slots and type in the constructor
        this.type = type;
        this.slots = new ArrayList<Slot>(slots);
    }
    // Operator to return permissions that are included in a tuple descriptor
    public Set<ColumnPermission> getIncludedPermissions() {
        // This should return a set of permissions that are included in the slots of this tuple descriptor
        return slots;
    }

    public void addSlot(Slot slot) {
        slots.add(slot);
    }

    public boolean isNamed(Slot slot) {
        return slot.getName() != null;
    }

    public List<Slot> getAdditionalSlots() {
        List<Slot> additionalSlots = new ArrayList<Slot>();
        for (int i = 0; i < type.getFieldCount(); i++) {
            String name = type.getFieldName(i);
            for (Slot slot : slots) {
                if (slot.getName().equals(name)) {
                    additionalSlots.add(slot);
                }
            }
        }
        return additionalSlots;
    }

    public boolean hasPermission(ColumnPermission p) {
        for (int i = 0; i < type.getFieldCount(); i++) {
            if (type.getFieldName(i).equals(p.getTableName())) return true;
        }
        return false;
    }
}

