public class PackageClassFilter implements ClassFilter {
    private List<String> acceptedPackages = new ArrayList<>();
    private ClassFilter wrappedFilter;

    public PackageClassFilter(ClassFilter wrappedFilter) {
        this.wrappedFilter = wrappedFilter;
    }

    @Override
    public boolean accept(String classname) {
        String packageName = classname.substring(0, classname.lastIndexOf('.'));
        if (acceptedPackages.contains(packageName)) {
            return true;
        }
        return wrappedFilter.accept(classname);
    }

    public void acceptPackage(String packageName) {
        acceptedPackages.add(packageName);
    }

    public ClassFilter setWrappedFilter(ClassFilter wrappedFilter) {
        this.wrappedFilter = wrappedFilter;
        return this;
    }
}

