class Solution {
    public int[] circularGameLosers(int n, int k) {
        int[] count = new int[n];
        int cur = 0;
        for (int i = 1; (cur = (cur + i * k) % n)!= 0 && count[cur] < 2; i++) {
            count[cur]++;
        }
        List<Integer> losers = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (count[i] == 0) losers.add(i + 1);
        }
        return losers.stream().mapToInt(Integer::intValue).toArray();
    }
}

public class GraphAlgorithms {
    private final Map<Character, List<Character>> adjList;

    public GraphAlgorithms(Map<Character, List<Character>> adjList) {
        this.adjList = adjList;
    }

    /**
     * For each word, create edge from ith char to (i+1)th char, if they are different.
     * For pair for words, create edge between first different chars
     * Using modified DFS, print topological order
     */
    public void printTopOrder(String[] words) {
        for (int i = 1; i < words.length; i++) {
            String word1 = words[i - 1];
            String word2 = words[i];
            for (int j = 0; j < Math.min(word1.length(), word2.length()); j++) {
                char c1 = word1.charAt(j);
                char c2 = word2.charAt(j);
                if (c1 != c2) {
                    adjList.get(c1).add(c2);
                    break;
                }
            }
        }
        Set<Character> visited = new HashSet<>();
        Stack<Character> stack = new Stack<>();
        for (char c : adjList.keySet()) {
            if (!visited.contains(c)) {
                dfs(c, visited, stack);
            }
        }
        while (!stack.isEmpty()) {
            System.out.println(stack.pop());
        }
    }

    private void dfs(char c, Set<Character> visited, Stack<Character> stack) {
        visited.add(c);
        for (char neighbor : adjList.get(c)) {
            if (!visited.contains(neighbor)) {
                dfs(neighbor, visited, stack);
            }
        }
        stack.push(c);
    }
}

