public ResponseEntity<byte[]> downloadFile(@PathVariable Long tasksId, HttpServletRequest request) {
    CompletableFuture<File> completableFuture = findById(tasksId);

    ResponseEntity<byte[]> responseEntity;

    try {
        File file = completableFuture.get();
        byte[] bytes = Files.readAllBytes(file.getPath());

        responseEntity = ResponseEntity.ok()
                .contentType(getMediaType(file))
                .body(bytes);
    } catch (InterruptedException | ExecutionException e) {
        throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR, "An error has occurred while processing the request.");
    }

    Files.delete(file.toPath()); // Assuming delete operation is successful

    return responseEntity;
}

private MediaType getMediaType(File file) {
    String fileName = file.getName();

    if(fileName.endsWith(Variants.JSON.getValue())) {
        return MediaType.APPLICATION_JSON;
    } else if(fileName.endsWith(Variants.XML.getValue())) {
        return MediaType.APPLICATION_XML;
    } else if(fileName.endsWith(Variants.GEOPKG.getValue())) {
        return MediaType.valueOf("application/x-gpkg");
    }

    return MediaType.APPLICATION_OCTET_STREAM;
}

