int Make_Time_Samp(MPD_Node *node) {
    struct timeval *child_mtime = &node->content->file_time;
    struct timeval *parent_mtime = &node->content->mtime;

    if (gettimeofday(child_mtime, NULL) && parent_mtime->tv_sec < child_mtime->tv_sec) {
        *parent_mtime = *child_mtime;
    }

    return 0;
}

