public static Mono<?> showWarningIfUnrecognized(
    TurnContext turnContext,
    ObjectNode fromEntities,
    ObjectNode toEntities){

    return Mono.just(turnContext)
        .flatMap(context -> {
            boolean unrecognizedFrom = !AirportsApi.isValidAirport(fromEntities.get("Airport").asText()) 
                && fromEntities.get("Airport").asText().length() > 0;
            boolean unrecognizedTo = !AirportsApi.isValidAirport(toEntities.get("Airport").asText()) 
                && toEntities.get("Airport").asText().length() > 0;

            if(unrecognizedFrom || unrecognizedTo){
                StringBuilder warningMsg = new StringBuilder("Warning: ");
                warningMsg.append(unrecognizedFrom ? "The 'from' location is not recognized. " : "");
                warningMsg.append(unrecognizedTo ? "The 'to' location is not recognized. " : "");

                return context.sendActivity(warningMsg.toString());
            }

            return Mono.empty();
        });
}

