public string ToTypeScriptEnumCode()
{
    var enumCode = new StringBuilder();

    // Start of enum declaration
    enumCode.AppendLine("export enum " + Name + " {");

    // Loop through enum values
    foreach (var value in Values)
    {
        // Convert property name to PascalCase
        var propertyName = new StringBuilder();
        foreach (var word in value.Key.Split('_'))
        {
            propertyName.Append(word.Substring(0, 1).ToUpper() + word.Substring(1).ToLower());
        }

        // Add enum value to code
        enumCode.AppendLine("\t" + propertyName + " = '" + value.Value + "',");
    }

    // End of enum declaration
    enumCode.AppendLine("}");

    return enumCode.ToString();
}

