class TwoBodyPotential(Potential):
    def __init__(self, name, a, b):
        super().__init__(name)
        self.a = a
        self.b = b

    def calculate(self, r):
        raise NotImplementedError("Subclasses should implement this method")

class LennardJonesPotential(TwoBodyPotential):
    def calculate(self, r):
        return 4 * self.a * ((self.b / r) ** 12 - (self.b / r) ** 6)

class BuckinghamPotential(TwoBodyPotential):
    def calculate(self, r):
        return self.a * exp(-self.b * r) - self.c * r ** 6

class MorsePotential(TwoBodyPotential):
    def calculate(self, r):
        return self.a * (1 - exp(-self.b * (r - self.r0))) ** 2

class CoulombPotential(TwoBodyPotential):
    def calculate(self, r):
        return self.a / r

class HarmonicPotential(TwoBodyPotential):
    def calculate(self, r):
        return 0.5 * self.a * (r - self.r0) ** 2

class GaussianPotential(TwoBodyPotential):
    def calculate(self, r):
        return self.a * exp(-self.b * (r - self.r0) ** 2)

def choose_seconds(seconds):
    """Prettify the data."""
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    days, hours = divmod(hours, 24)
    weeks, days = divmod(days, 7)

    parts = []
    if weeks:
        parts.append(f"{weeks} week{'s' if weeks > 1 else ''}")
    if days:
        parts.append(f"{days} day{'s' if days > 1 else ''}")
    if hours:
        parts.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes:
        parts.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if seconds:
        parts.append(f"{seconds} second{'s' if seconds > 1 else ''}")

    if len(parts) > 1:
        parts[-1] = "and " + parts[-1]
    if len(parts) > 2:
        return ", ".join(parts[:-1]) + " " + parts[-1]
    else:
        return parts[0]

