public class Main {
    /**
     * Calculates a sub-score for a value.
     *
     * @param value A number of stars.
     * @param threshold If the value is greater than the threshold,
     *                  then the max score value is returned.
     * @throws IllegalArgumentException If the value is negative.
     */
    public static double calculateSubScore(int value, int threshold) {
        assert threshold >= 0 : "Threshold is expected to be non-negative.";
        assert value >= 0 : "Value is expected to be non-negative.";
        assert threshold >= value : "Threshold should be greater than or equal to the value.";
        if (value < 0) {
            throw new IllegalArgumentException("negative value");
        } else if (value > threshold) {
            return 1.0; // max score value
        } else {
            return ((double)value) / threshold; // sub-score
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(calculateSubScore(5, 10));
            System.out.println(calculateSubScore(11, 10));
            System.out.println(calculateSubScore(-1, 10));
            System.out.println(calculateSubScore(10, 10));
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}

