#include <unordered_map>
#include <string>

class Solution {
public:
    bool checkInclusion(const std::string& s1, const std::string& s2) {
        if (s1.size() > s2.size()) return false;

        std::unordered_map<char, int> charCount;
        for (char c : s1) {
            charCount[c]++;
        }

        int required = charCount.size();
        int formed = 0;

        int left = 0, right = 0;
        std::unordered_map<char, int> windowCounts;

        while (right < s2.size()) {
            char c = s2[right];
            windowCounts[c]++;

            if (charCount.find(c) != charCount.end() && windowCounts[c] == charCount[c]) {
                formed++;
            }

            while (right - left + 1 >= s1.size()) {
                if (formed == required) {
                    return true;
                }

                char c = s2[left];
                windowCounts[c]--;
                if (charCount.find(c) != charCount.end() && windowCounts[c] < charCount[c]) {
                    formed--;
                }

                left++;
            }

            right++;
        }

        return false;
    }
};

