// Assuming that RenderableComponent is the component that holds the renderables
// and that clone() is a method that clones the renderables
void cloneRenderables(const Ndk::EntityHandle& e, unsigned renderOrder)
{
    // Check if the entity is valid
    if (!e)
    {
        return;
    }

    // Get the RenderableComponent from the entity
    auto renderableComponent = e->GetComponent<Ndk::RenderableComponent>();

    // Check if the entity has a RenderableComponent
    if (!renderableComponent)
    {
        return;
    }

    // Clone the renderables
    auto clonedRenderables = renderableComponent->clone();

    // Set the render order for the cloned renderables
    for (auto& renderable : clonedRenderables)
    {
        renderable.setRenderOrder(renderOrder);
    }

    // Assuming that addRenderable is a method that adds a renderable to the entity
    for (auto& renderable : clonedRenderables)
    {
        e->addRenderable(renderable);
    }
}

