import android.view.View;
import android.view.ViewGroup;
import android.animation.ObjectAnimator;
import android.animation.Animator;
import android.animation.AnimatorListenerAdapter;
import android.util.SparseArray;
import android.os.Bundle;

public class RtlTransition {

    private ViewGroup container;
    private SparseArray<Bundle> viewStates;

    public RtlTransition(ViewGroup container) {
        this.container = container;
        this.viewStates = new SparseArray<>();
    }

    public void startTransition() {
        for (int i = 0; i < container.getChildCount(); i++) {
            View view = container.getChildAt(i);
            saveViewState(view);

            ObjectAnimator animator = ObjectAnimator.ofFloat(view, "translationX", 0, -container.getWidth());
            animator.setDuration(300);
            animator.addListener(new AnimatorListenerAdapter() {
                @Override
                public void onAnimationEnd(Animator animation) {
                    view.setVisibility(View.INVISIBLE);
                }
            });
            animator.start();
        }

        // Restore views after all animations are complete
        container.postDelayed(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < container.getChildCount(); i++) {
                    View view = container.getChildAt(i);
                    view.setVisibility(View.VISIBLE);
                    restoreViewState(view);

                    ObjectAnimator animator = ObjectAnimator.ofFloat(view, "translationX", -container.getWidth(), 0);
                    animator.setDuration(300);
                    animator.start();
                }
            }
        }, 300);
    }

    private void saveViewState(View view) {
        Bundle state = new Bundle();
        view.saveHierarchyState(state);
        viewStates.put(view.getId(), state);
    }

    private void restoreViewState(View view) {
        Bundle state = viewStates.get(view.getId());
        if (state != null) {
            view.restoreHierarchyState(state);
        }
    }
}

