    public abstract class DataProcessingPipelineBase : IDataProcessingPipeline
    {
        private readonly IItemSerializerService _serializerService;
        private readonly IEncryptionService _encryptionService;
        private readonly ICompressionService _compressionService;

        protected DataProcessingPipelineBase(IItemSerializerService serializerService, IEncryptionService encryptionService, ICompressionService compressionService)
        {
            _serializerService = serializerService?? throw new ArgumentNullException(nameof(serializerService));
            _encryptionService = encryptionService?? throw new ArgumentNullException(nameof(encryptionService));
            _compressionService = compressionService?? throw new ArgumentNullException(nameof(compressionService));
        }

        public DataProcessingInformations GetInformations()
        {
            return new DataProcessingInformations(_serializerService, _encryptionService, _compressionService);
        }

        public ReadOnlySpan<byte> Input(object obj)
        {
            var bytes = _serializerService.Serialize(obj);
            var encryptedBytes = _encryptionService.Encrypt(bytes);
            return _compressionService.Compress(encryptedBytes);
        }

        public object Output(ReadOnlySpan<byte> bytes)
        {
            var decompressedBytes = _compressionService.Decompress(bytes);
            var decryptedBytes = _encryptionService.Decrypt(decompressedBytes);
            return _serializerService.Deserialize(decryptedBytes);
        }
    }
}

import java.util.NoSuchElementException;

public class LargestLessThanOrEqual {

  // node class
  public static class TreeNode {
    public int val;
    public TreeNode left;
    public TreeNode right;

    public TreeNode(int value) {
      val = value;
    }
  }

  public static int largestLessThanOrEqual(TreeNode root, int value) throws NoSuchElementException, IllegalArgumentException {
    if (value == null) throw new IllegalArgumentException("value cannot be null");
    if (root == null) throw new NoSuchElementException("tree cannot be empty");

    while (root != null) {
      if (root.val <= value) {
        // update result and search right subtree for larger values
        result = root.val;
        root = root.right;
      } else {
        // search left subtree for smaller values
        root = root.left;
      }
    }

    return result;
  }
}

public List<string> WordSearch(string word, int maxDistance, Func<string, char, char, int> distanceFunction, int branch, int branchOffset, List<string> results, int[,] column)
{
    if (maxDistance < 0)
    {
        throw new ArgumentException("maxDistance must be greater than or equal to 0");
    }

    if (branchOffset == word.Length)
    {
        return results;
    }
    else
    {
        for (int nextChar = 0; nextChar <= branch; nextChar++)
        {
            if (branchOffset < word.Length)
            {
                int editDistance = distanceFunction(word, branchOffset, nextChar);
                if (editDistance <= maxDistance)
                {
                    results.Add(string.Concat(word.Take(branchOffset + 1), nextChar.ToString()));
                }
            }
        }
        for (int nextChar = 0; nextChar <= branch; nextChar++)
        {
            if (nextChar != 0)
            {
                results = WordSearch(word, maxDistance, distanceFunction, branch, branchOffset - 1, results, column);
            }
        }
        return results;
    }
}

