@Override
public Void visit(Path<?> path, Void context) {
    final PathType pathType = path.getMetadata().getPathType();
    final Path<?> parent = path.getMetadata().getParent();
    final String property = path.getMetadata().getName();
    final Class<?> parentType = parent.getType();

    try {
        switch (pathType) {
            case PROPERTY:
                handlePropertyAccess(parent, property, parentType);
                break;
            case DELEGATE:
                handleDelegateAccess(path, parent);
                break;
            default:
                handleDefaultAccess(path, parent, property);
                break;
        }
    } catch (Exception e) {
        throw new QueryException(e);
    }

    return null;
}

private void handlePropertyAccess(Path<?> parent, String property, Class<?> parentType) {
    Method method = getAccessor(parentType, property);
    if (method != null && Modifier.isPublic(method.getModifiers())) {
        handle(parent);
        append(".").append(method.getName()).append("()");
    } else {
        Field field = getField(parentType, property);
