            handle(parent);
            append(".").append(property);
        } else {
            append(CollQueryFunctions.class.getName()).append(".<");
            append(parent.getType().getName()).append(">get(");
            handle(parent);
            append(", \"").append(property).append("\")");
        }
    }
}

