from typing import List, Dict, Any, Set


def distribute_workers_efficiently(n_workers: int, bases: List[Base], num_to_assign: int, priority_tasks: Set[Base]) -> Dict[str, List[Worker]]:

    from queue import PriorityQueue

    pq = PriorityQueue()

    assignments: Dict[str, List[Worker]] = {base.id: [] for base in bases}


    # Heuristic function for enqueueing bases into the priority queue

    def enqueue(base: Base):

        priority = (len(base.load), base.capacity)

        pq.put((-priority[0], priority[1], id(base)))


    for base in priority_tasks:

        enqueue(base)

    for base in bases:

        if base not in priority_tasks:

            enqueue(base)


    while n_workers > 0 and not pq.empty():

        _, _, base_id = pq.get()

        base = bases[base_id]

        if base.capacity - base.load > 0 and n_workers > 0:

            assignments[base_id].append(Worker())

            n_workers -= 1

            base.load += 1


    return assignments

