string evaluate(string instruction, int num1, int num2) {
    // Check for valid instructions and return "Unknown operation"
    if (instruction == "Add")
        return to_string(num1 + num2);
    else if (instruction == "Subtract")
        return to_string(num1 - num2);
    else if (instruction == "Multiply")
        return to_string(num1 * num2);
    else if (instruction == "Divide")
        return to_string(num1 / num2);
    else if (instruction == "Power")
        return to_string(std::pow(num1, num2));
    else if (instruction == "Root")
        return to_string(std::pow(num1, 1.0 / num2));
    else if (instruction == "Modulus")
        return to_string(num1 % num2);

    // If operation is unknown, return "Unknown operation"
    return "Unknown operation";
}

