from api.models import Childs, Parents, ParentsChilds, Relationship
from..serializers import ChildsSaveSerializer

@api_view(['POST'])
@authentication_classes([JSONWebTokenAuthentication])
@permission_classes([IsAuthenticated])
def registration_child_view(request):
    """
    Register a new child with their parents.
    """
    data = request.data
    child_data = data[0]['child']
    parents_data = data[0]['parents']

    # Validate child's document is not already registered as a parent
    try:
        if Parents.objects.filter(document=child_data['document']).exists():
            return Response({'error': ['El documento del menor ingresado se encuentra registrado como un responsable.']}, status=400)
    except Parents.DoesNotExist:
        pass

    # Validate child data
    child_serializer = ChildsSaveSerializer(data=child_data, context={'request': request})
    if not child_serializer.is_valid():
        return Response(child_serializer.errors, status=400)

    try:
        with transaction.atomic():
            child = child_serializer.save()
            if parents_data:
                for parent_data in parents_data:
                    parent = Parents.objects.get(document=parent_data['document'])
                    relationship = Relationship.objects.get(name=parent_data['relationship'])
                    parents_childs = ParentsChilds(
                        child=child,
                        parent=parent,
                        relationship=relationship
                    )
                    parents_childs.save()
    except ValueError as e:
        transaction.rollback()
        return Response({'error': str(e)}, status=400)
    except Exception as e:
        transaction.rollback()
        return Response({'error': 'Se ha presentado error con el registro'}, status=400)

    return Response('', status=200)

