def count_max_co(i):
    """Count the maximum consecutive elements to the left and right of the given index."""
    left = right = 0
    level = l[i]
    for li in l[:i][::-1]:
        if li <= level:
            level = li
            left += 1
        else:
            break
    for lp in l[i+1:]:
        if lp <= level:
            level = lp
            right += 1
        else:
            break
    return left + right + 1

