public class PolygonGenerator
{
    /// <summary>
    /// Get a rectangular polygon from two points
    /// The given two points should be on XY plane of the matrix
    /// </summary>
    /// <param name="matrix">New rectangle will be created on XY plane of matrix</param>
    /// <param name="center">Center of circle</param>
    /// <param name="pointOnCircle">Point on circle</param>
    /// <returns>Rectangle prepared from two points</returns>
    public Rectangle GetRectangle(IMatrix matrix, Point center, Point pointOnCircle)
    {
        double radius = Math.Sqrt(Math.Pow(pointOnCircle.X - center.X, 2) + Math.Pow(pointOnCircle.Y - center.Y, 2));

        double minX = center.X - radius;
        double maxX = center.X + radius;
        double minY = center.Y - radius;
        double maxY = center.Y + radius;

        return new Rectangle((int)Math.Min(minX, maxX), (int)Math.Min(minY, maxY), (int)Math.Abs(maxX - minX), (int)Math.Abs(maxY - minY));
    }
}

