public class PolygonExtractor
{
    public List<List<List<int>>> ExtractPolygons(int[,] volume, int foregroundId, int maxNestingLevel, bool enableVerboseOutput)
    {
        var polygons = new List<List<List<int>>>();
        var visited = new HashSet<(int, int)>();

        for (var y = 0; y < volume.GetLength(1); y++)
        {
            for (var x = 0; x < volume.GetLength(0); x++)
            {
                if (volume[x, y] == foregroundId && !visited.Contains((x, y)))
                {
                    var polygon = new List<List<int>>();
                    ExtractPolygon(volume, x, y, foregroundId, maxNestingLevel, 0, polygon, visited);
                    polygons.Add(polygon);
                }
            }
        }

        if (enableVerboseOutput)
        {
            var stopwatch = Stopwatch.StartNew();
            var polygonCount = polygons.Sum(p => p.Sum(p2 => p2.Count));
            var vertexCount = polygons.Sum(p => p.Sum(p2 => p2.Sum(v => 1)));
            stopwatch.Stop();
            Trace.TraceInformation($"Extracted {polygonCount} polygons with {vertexCount} vertices in {stopwatch.ElapsedMilliseconds}ms.");
        }

        return polygons;
    }

    private void ExtractPolygon(int[,] volume, int x, int y, int foregroundId, int maxNestingLevel, int nestingLevel, List<List<int>> polygon, HashSet<(int, int)> visited)
    {
        if (nestingLevel > maxNestingLevel) return;

        var points = new List<int[]>();

        if (x > 0 && volume[x - 1, y] == foregroundId && !visited.Contains((x - 1, y)))
        {
            points.Add(new int[] { x - 1, y });
            visited.Add((x - 1, y));
        }

        if (y > 0 && volume[x, y - 1] == foregroundId && !visited.Contains((x, y - 1)))
        {
            points.Add(new int[] { x, y - 1 });
            visited.Add((x, y - 1));
        }

        if (x < volume.GetLength(0) - 1 && volume[x + 1, y] == foregroundId && !visited.Contains((x + 1, y)))
        {
            points.Add(new int[] { x + 1, y });
            visited.Add((x + 1, y));
        }

        if (y < volume.GetLength(1) - 1 && volume[x, y + 1] == foregroundId && !visited.Contains((x, y + 1)))
        {
            points.Add(new int[] { x, y + 1 });
            visited.Add((x, y + 1));
        }

        if (points.Count == 0) return;

        polygon.Add(points);
        ExtractPolygon(volume, x, y, foregroundId, maxNestingLevel, nestingLevel + 1, polygon, visited);
    }
}

