        System.out.println(Arrays.toString(productArray(new int[]{2,5,10,3,5,6,2}))); //You should print -> [180, 600, 360, 300, 900, 600, 180]
    }
    static Integer[] productArray(int[] A) {
        if(A == null || A.length == 0){
            return new Integer[0];
        }
        Integer[] result = new Integer[A.length];
        result[0] = 1;
        for(int i = 1; i < A.length; i++){
            result[i] = result[i - 1] * A[i - 1];
        }
        int rightProduct = 1;
        for(int i = A.length - 1; i >= 0; i--){
            result[i] *= rightProduct;
            rightProduct *= A[i];
        }
        return result;
    }
}

