class Solution:
    def repeatedStringMatch(self, A: str, B: str) -> int:
        # If B is directly in A, we can return 1
        if B in A:
            return 1

        # Check up to 3 times the length of B
        for i in range(2):
            candidate = A * (i + 2)
            if B in candidate:
                return (len(candidate) // len(A))

        # If B is not found, return -1
        return -1

