Matrix Matrix::rowEchelonForm() const
{
    // Create a copy of the current matrix to work with
    Matrix result = Matrix(*this);

    // Get the dimensions of the matrix
    int rowCount = result.rowCount();
    int columnCount = result.columnCount();

    // Variables to track the pivot position
    int pivotRow = 0;
    int pivotColumn = 0;

    // Process each row and column
    while (pivotRow < rowCount && pivotColumn < columnCount)
    {
        // Find the first non-zero element in the current column
        bool rowFound = false;
        for (int row = pivotRow; row < rowCount; ++row)
        {
            if (result.value(row, pivotColumn) != 0)
            {
                // Swap the current pivot row with the row found
                if (row != pivotRow)
                {
                    result.swapRows(pivotRow, row);
                }
                rowFound = true;
                break;
            }
        }

        if (rowFound)
        {
            // Normalize the pivot row
            double pivotValue = result.value(pivotRow, pivotColumn);
            result.scaleRow(pivotRow, 1.0 / pivotValue);

            // Eliminate the elements below the pivot
            for (int row = pivotRow + 1; row < rowCount; ++row)
            {
                if (result.value(row, pivotColumn) != 0)
                {
                    double factor = -result.value(row, pivotColumn);
                    result.pivot(pivotColumn, pivotRow, factor);
                }
            }
            pivotRow++;
        }
        pivotColumn++;
    }

    return result;
}

