import org.apache.commons.lang3.time.StopWatch;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.Signature;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Component
@Aspect
public class LoggableAspect {

    private static final Logger LOGGER = LoggerFactory.getLogger(LoggableAspect.class);

    /**
     * Log method entry and exit times.
     *
     * @param proceedingJoinPoint the proceeding join point
     * @param loggable the loggable annotation
     * @return the result of the method execution
     * @throws Throwable if an exception occurs
     */
    @Around("@annotation(loggable)")
    public Object log(ProceedingJoinPoint proceedingJoinPoint, Loggable loggable) throws Throwable {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        Signature signature = proceedingJoinPoint.getSignature();
        String methodName = signature.getName();
        String className = proceedingJoinPoint.getTarget().getClass().getSimpleName();

        Object[] args = proceedingJoinPoint.getArgs();
        if (LOGGER.isDebugEnabled()) {
            LOGGER.debug("ENTERED_METHOD = {}.{} | METHOD_PARAMS = {}", className, methodName, args);
        } else {
            LOGGER.info("ENTERED_METHOD = {}.{}", className, methodName);
        }

        Object result;
        try {
            result = proceedingJoinPoint.proceed();
        } catch (Exception exception) {
            stopWatch.stop();
            LOGGER.info("EXITED_METHOD = {}.{} | TIME = {} | EXCEPTION_MESSAGE = {}", 
                className, methodName, stopWatch.getTime(), exception.getMessage());
            throw exception;
        }

        stopWatch.stop();
        LOGGER.info("EXITED_METHOD = {}.{} | TIME = {}", className, methodName, stopWatch.getTime());

        return result;
    }
}

