public class MessageBinding<T>
{
    private IMessageProducer<T> producer;
    private IMessageListener<T> listener;
    private bool isBound;

    public MessageBinding(IMessageProducer<T> producer, IMessageListener<T> listener)
    {
        this.producer = producer;
        this.listener = listener;
        isBound = true;
    }

    public void Bind()
    {
        if (!isBound)
        {
            // Perform binding logic here
            Console.WriteLine("Binding completed.");
        }
        else
        {
            Console.WriteLine("Already bound.");
        }
    }

    public void Unbind()
    {
        if (isBound)
        {
            // Perform unbinding logic here
            Console.WriteLine("Unbinding completed.");
            isBound = false;
        }
        else
        {
