#define SUCCESS 0
#define INVALID_ROW 1
#define ROW_ALREADY_SET 2

typedef struct {
    int numRows;
    int numCols;
    double **localRows; // Array of pointers to local rows
    int *isRowSet;      // Array to track if a row is already set
} Matrix;

int MatrixSetRow(Matrix *matrix, int globalRow, double *rowData) {
    int localRow;

    // Convert global row to local row index
    // Assuming simple mapping for demonstration: local row = global row
    localRow = globalRow;

    // Check if the row is within the valid range of local rows
    if (localRow < 0 || localRow >= matrix->numRows) {
        return INVALID_ROW;
    }

    // Check if the row is already set
    if (matrix->isRowSet[localRow]) {
        return ROW_ALREADY_SET;
    }

    // Allocate memory for the row data and copy the data
    matrix->localRows[localRow] = (double *)malloc(matrix->numCols * sizeof(double));
    if (matrix->localRows[localRow] == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < matrix->numCols; i++) {
        matrix->localRows[localRow][i] = rowData[i];
    }

    // Mark the row as set
    matrix->isRowSet[localRow] = 1;

    return SUCCESS;
}

