import java.util.*;
import java.util.concurrent.*;

public class Broker extends Thread {
    private final int numThreads;
    private final ExecutorService executor;
    private final CompletionService completionService;
    private final Map<Subscriber, Mailbox> mailboxes;
    private final List<Subscriber> subscribers;
    private boolean noMoreMessages;
    private boolean silenced;

    public Broker(int numThreads) {
        this.numThreads = numThreads;
        this.executor = Executors.newFixedThreadPool(numThreads);
        this.completionService = new ExecutorCompletionService<>(executor);
        this.mailboxes = new ConcurrentHashMap<>();
        this.subscribers = new CopyOnWriteArrayList<>();
    }

    @Override
    public void run() {
        while (!noMoreMessages) {
            try {
                Future<?> future = completionService.take();
                try {
                    SubscriberResponse response = (SubscriberResponse) future.get();
                    if (response.shouldRetry()) {
                        send(response.getSubscriber(), response.getMessages());
                    } else {
                        send(response.getSubscriber(), drainQueue(response.getSubscriber()));
                    }
                } catch (InterruptedException | ExecutionException e) {
                    Thread.currentThread().interrupt();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        executor.shutdown();
    }

    private List<Message> drainQueue(Subscriber subscriber) {
        Mailbox mailbox = mailboxes.get(subscriber);
        synchronized (mailbox) {
            List<Message> messages = new ArrayList<>();
            while (!mailbox.q.isEmpty()) {
                messages.add(mailbox.q.poll());
            }
            mailbox.sending = false;
            return messages;
        }
    }

    public void publish(Message message) {
        for (Subscriber subscriber : subscribers) {
            Mailbox mailbox = mailboxes.get(subscriber);
            synchronized (mailbox) {
                if (!mailbox.sending) {
                    mailbox.sending = true;
                    send(subscriber, Collections.singletonList(message));
                } else {
                    mailbox.q.add(message);
                }
            }
        }
    }

    private void send(Subscriber subscriber, List<Message> messages) {
        completionService.submit(() -> subscriber.send(messages));
    }

    public void removeSubscriber(Subscriber subscriber) {
        subscribers.remove(subscriber);
        mailboxes.remove(subscriber);
    }

    public void addSubscriber(Subscriber subscriber) {
        subscribers.add(subscriber);
        mailboxes.put(subscriber, new Mailbox());
    }

    public void unsilenceAll() {
        silenced = false;
    }

    public void silenceAll() {
        silenced = true;
    }

    public void noMoreMessages() {
        noMoreMessages = true;
    }

    public static class Mailbox {
        private final Queue<Message> queue;
        private boolean sending;

        public Mailbox() {
            queue = new ConcurrentLinkedQueue<>();
        }

        public synchronized boolean isEmpty() {
            return queue.isEmpty();
        }

        public synchronized void add(Message message) {
            queue.add(message);
        }

        public synchronized Message poll() {
            return queue.poll();
        }

        public synchronized void clear() {
            queue.clear();
        }

        public synchronized boolean isSending() {
            return sending;
        }

        public synchronized void setSending(boolean sending) {
            this.sending = sending;
        }
    }
}

