// Equal gets whether two Objects are equal.
// It don't cares about underlying type.
// If first argument is compliant with `Equalizer` interface
// then it will use `Equal(interface) bool` on type to compare.
// Otherwise it try to compare using `DeepEqual` and same types.
func Equal(a, b interface{}) bool {
	switch a := a.(type) {
	case Equalizer:
		return a.Equal(b)
	default:
		if reflect.TypeOf(a) != reflect.TypeOf(b) {
			return false
		}
		return reflect.DeepEqual(a, b)
	}
}

type Equalizer interface {
	Equal(interface{}) bool
}

public Dictionary<object, object> Deserialize(Dictionary<object, object> o, Type itemType, object storage)
{
    if (o == null)
    {
        o = new Dictionary<object, object>();
    }

    if (storage == null)
    {
        return o;
    }

    foreach (var item in storage)
    {
        if (itemType.IsAssignableFrom(item.Key.GetType()))
        {
            o[item.Key] = item.Value;
        }
    }

    return o;
}

