import java.util.TreeMap;
import java.util.HashSet;
import java.util.Map;

public class StockPrice {
    private TreeMap<Integer, Integer> ts; // Timestamp to price mapping
    private TreeMap<Integer, HashSet<Integer>> prices; // Price to set of timestamps mapping

    public StockPrice() {
        ts = new TreeMap<>();
        prices = new TreeMap<>();
    }

    public void update(int timestamp, int price) {
        if (ts.containsKey(timestamp)) {
            int old = ts.get(timestamp);
            prices.get(old).remove(timestamp);
            if (prices.get(old).size() == 0) {
                prices.remove(old);
            }
        }
        ts.put(timestamp, price);
        if (!prices.containsKey(price)) {
            prices.put(price, new HashSet<>());
        }
        prices.get(price).add(timestamp);
    }

    public int current() {
        return ts.lastEntry().getValue();
    }

    public int maximum() {
        return prices.lastEntry().getKey();
    }

    public int minimum() {
        return prices.firstEntry().getKey();
    }
}

