static long GetMemoryInfo() {
    long totalMemory = 0L;
    PerformanceCounter[] counters = GetCounters();

    foreach (PerformanceCounter counter in counters)
    {
        counter.NextValue();
        totalMemory += counter.RawValue;
    }

    return totalMemory;
}

static PerformanceCounter[] GetCounters() {
    PerformanceCounter[] counters = new PerformanceCounter[] {
        new PerformanceCounter("Memory", "Available MBytes", true),
        new PerformanceCounter("Memory", "Free MBytes", true),
        new PerformanceCounter("Memory", "Total MBytes", true),
    };

    return counters;
}

