import java.nio.ByteBuffer;

public class FixedSizeVector {
    private final ByteBuffer buffer;
    private final int size;

    public FixedSizeVector(float x1, float y1, float x2, float y2) {
        this.buffer = ByteBuffer.allocateDirect(16).putFloat(x1).putFloat(y1).putFloat(x2).putFloat(y2);
        this.size = 4;
    }

    public float getX1() {
        return this.buffer.getFloat(0);
    }

    public float getY1() {
        return this.buffer.getFloat(4);
    }

    public float getX2() {
        return this.buffer.getFloat(8);
    }

    public float getY2() {
        return this.buffer.getFloat(12);
    }

    public byte get(int index) {
        if (index >= size || index < 0) {
            throw new IndexOutOfBoundsException("Index out of bounds in FixedSizeVector");
        }
        return this.buffer.getFloat(index * 4);
    }
}

