int separate_path_and_file(const char* fullpath, char* pathp, size_t pathp_size, char* namep, size_t namep_size) {
    if (fullpath == NULL || pathp == NULL || namep == NULL) return -1;

    // Calculate the directory path
    ssize_t dir_offset = strrchr(fullpath, '/') + 1;
    if (dir_offset > PATH_MAX - 1) {
        return -1; // Path too long
    }

    // Copy the directory path
    strncpy(pathp, fullpath, dir_offset - fullpath);
    pathp[dir_offset - fullpath] = '\0';

    // Calculate the file name
    *namep = dir_offset == (size_t)fullpath ? '\0' : *(dir_offset);
    strncat(namep, fullpath + dir_offset, namep_size - strlen(namep) - 1);
    namep[namep_size - 1] = '\0';

    return 0;
}

import os
import sys
from io import IOBase, BytesIO

class FastIO:
    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = file.writable()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0)
            self.buffer.seek(0)

    def write(self, s):
        self.buffer.write(s)

    def read(self):
        return os.read(self._fd, 1024)

    def readline(self):
        return os.read(self._fd, 1024)

class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode('ascii'))
        self.read = lambda: self.buffer.read().decode('ascii')
        self.readline = lambda: self.buffer.readline().decode('ascii')

def print(*args, **kwargs):
    sep = kwargs.pop('sep', ' ')
    file = kwargs.pop('file', sys.stdout)
    end = kwargs.pop('end', '\n')

    wrapper = IOWrapper(file)
    at_start = True
    for x in args:
        if not at_start:
            wrapper.write(sep)
        wrapper.write(str(x))
        at_start = False
    wrapper.write(end)
    wrapper.flush()

