    return prod

def main():
    nums = list(map(int, input("Enter a list of numbers separated by space: ")))
    n = len(nums)
    carry = 0
    ans = 0
    for i in range(n - 1, 0, -1):
        if nums[i] + carry >= 10:
            ans += (nums[i] + carry) % 10
            carry = (nums[i] + carry) // 10
        else:
            ans += (nums[i] + carry)
            carry = 0
    if carry > 0:
        ans += carry
    print("Product of the numbers:", findProd(nums))
    print("Sum of the digits of the numbers from right to left:", ans)

