from typing import List
import collections

class Solution:
    def findLatestStep(self, arr: List[int], m: int) -> int:
        n = len(arr)
        parent = list(range(n + 2))  # Include boundary elements
        size = [0] * (n + 2)
        counts = collections.Counter()
        latest_step = -1

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                # Union by size
                if size[rootX] < size[rootY]:
                    rootX, rootY = rootY, rootX
                parent[rootY] = rootX
                size[rootX] += size[rootY]
                counts[size[rootY]] -= 1  # Remove old size
                counts[size[rootX]] += 1  # Add new size

        for index, val in enumerate(arr):
            position = val
            # Check left neighbor
            if s := size[find(position - 1)]:
                counts[s] -= 1
            # Check right neighbor
            if s := size[find(position + 1)]:
                counts[s] -= 1
            size[find(position)] = 1
            # Union with left neighbor
            if left_root := find(position - 1):
                union(left_root, position)
            # Union with right neighbor
            if right_root := find(position + 1):
                union(right_root, position)
            # If there is a group of size m, update latest_step
            if m in counts:
                latest_step = index + 1

        return latest_step

public RBNode getNode(int queryKey, RBNode currentRoot) {
    while (currentRoot != null) {
        if (queryKey < currentRoot.key) {
            currentRoot = currentRoot.left;
        } else if (queryKey > currentRoot.key) {
            currentRoot = currentRoot.right;
        } else {
            return currentRoot;
        }
    }
    return null;
}

