function autoComplete(src, arr) {
    src.onkeyup = function() {
        let value = src.value;
        if (value.length > 2) {
            let res = arr.filter(function(x){
                return x.toLowerCase().indexOf(value.toLowerCase()) > -1;
            });

            if(res.length > 0){
                let ul = document.createElement("ul");
                res.forEach(function(x){
                    let li = document.createElement("li");
                    li.appendChild(document.createTextNode(x));
                    ul.appendChild(li);
                });               
                src.parentNode.replaceChild(ul, src);
            } else {
                src.parentNode.replaceChild(document.createElement("li"), src);
            }  
        } else {
            src.parentNode.replaceChild(document.createElement("li"), src);
        }
    }
}

