    expect(compareable.eq([1, 0])).toBe(false);
    expect(compareable.eq(["hello", "hello"])).toBe(true);
    expect(compareable.eq(["hello", "world"])).toBe(false);
    expect(compareable.eq([null, null])).toBe(true);
    expect(compareable.eq([null, undefined])).toBe(false);
    expect(compareable.eq([undefined, undefined])).toBe(true);
  });

  it('will compare using "neq", "!="', () => {
    expect(compareable.neq([true, true])).toBe(false);
    expect(compareable.neq([false, true])).toBe(true);
    expect(compareable.neq([1, 1])).toBe(false);
    expect(compareable.neq([1, 0])).toBe(true);
    expect(compareable.neq(["hello", "hello"])).toBe(false);
    expect(compareable.neq(["hello", "world"])).toBe(true);
    expect(compareable.neq([null, null])).toBe(false);
    expect(compareable.neq([null, undefined])).toBe(true);
    expect(compareable.neq([undefined, undefined])).toBe(false);
  });

  it('will compare using "gt", ">"', () => {
    expect(compareable.gt([1, 0])).toBe(true);
    expect(compareable.gt([0, 1])).toBe(false);
    expect(compareable.gt([1, 1])).toBe(false);
    expect(compareable.gt(["hello", "world"])).toBe(false);
    expect(compareable.gt(["world", "hello"])).toBe(true);
