    expect(compareable.gte([1, 0])).toBe(true);
    expect(compareable.gte([0, 1])).toBe(false);
    expect(compareable.gte([1, 1])).toBe(true);
    expect(compareable.gte(["hello", "world"])).toBe(false);
    expect(compareable.gte(["world", "hello"])).toBe(true);
