public class RateLimiter {
    private boolean rateLimited = false;
    private Calendar startOfInterval;

    public void limitRate(int requestsPerInterval) {
        // Calculate the start of the interval
        Calendar startOfInterval = Calendar.getInstance();
        startOfInterval.add(Calendar.SECOND, -startOfInterval.get(Calendar.SECOND) % requestsPerInterval);

        // Calculate the end of the interval
        Calendar endOfInterval = (Calendar) startOfInterval.clone();
        endOfInterval.add(Calendar.SECOND, requestsPerInterval);

        // Reset rateLimit if the current time is within the interval
        if (endOfInterval.after(Calendar.getInstance()) && !rateLimited) {
            rateLimited = true;
        }
        rateLimited = false;
    }
}

import com.sleepycat.je.RunRecoveryException;
import java.io.IOException;
import java.net.SocketException;
import java.nio.channels.ClosedChannelException;

public class ExceptionHandler {

    public static int handleException(Exception e) {
        if (!(e instanceof RunRecoveryException)) {
            return 0;
        }

        RunRecoveryException rre = (RunRecoveryException) e;
        Throwable cause = rre.getCause();

        if (!(cause instanceof ClosedChannelException)) {
            return 0;
        }

        ClosedChannelException cce = (ClosedChannelException) cause;
        Throwable cause1 = cce.getCause();

        if (!(cause1 instanceof SocketException)) {
            return 0;
        }

        SocketException se = (SocketException) cause1;
        Throwable cause2 = se.getCause();

        if (!(cause2 instanceof ClosedByInterruptException)) {
            return 0;
        }

        return 3;
    }
}

