MOD = 1000000007

def mod_pow(base, exponent):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exponent //= 2
    return result

def mod_inverse(a):
    return pow(a, MOD - 2, MOD)

