class GPSPicker {
    constructor(settings) {
        this.settings = settings || {};
        this.init();
    }

    init() {
        const { selector, inputElement, mapElement, defaultView } = this.settings;

        if (!selector) throw new Error('Invalid selector');
        if (!selector.value) throw new Error('Input element is empty');

        const map = L.map(mapElement).setView(defaultView.latLng || [defaultView.latitude, defaultView.longitude], defaultView.zoom || 10);

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        }).addTo(map);

        this.initInput(selector, inputElement);
    }

    initInput(selector, inputElement) {
        let inputValue = selector.value;

        const watcher = new MutationObserver(changes => {
            changes.forEach(change => {
                const value = change.target.value;
                if (value !== inputValue) {
                    inputValue = value;
                    this.updateInput(value);
                }
            });
        });

        watcher.observe(selector, { childList: true });

        inputElement.addEventListener('change', () => {
            inputValue = inputElement.value;
            this.updateInput(value);
        });

        this.updateInput(inputValue);
    }

    updateInput(value) {
        inputElement.value = value;
    }
}

