    Vector3 managedOffset = Vector3.zero;

    UpdateMovement(ref managedOffset, ref newState);
    UpdateVerticalMovement(ref managedOffset, ref newState);
    UpdateCollisionMovement(ref managedOffset);

    // Calculate new position considering managedOffset
    Vector3 newPosition = transform.position + GetEndOffset(transform.position, managedOffset);

    // Grounding logic: If the player is on the ground and not jumping, and the velocity is minimal, pull the character down slightly if necessary.
    if (_isGrounded && !_jumping && Vector3.SqrMagnitude(_collisionVelocity) < SqrNotMovingThresh && newState != PlayerState.Climbing)
    {
        if (Cast(newPosition, Vector3.down, out var hit) && hit.collider == _ground)
        {
            newPosition += Vector3.down * (hit.distance - SkinRadius);
        }
    }

    // Depenetration logic: Adjust position to avoid overlapping with other colliders.
    int penetrationCount = OverlapNonAlloc(newPosition, _penetrationColliders, QueryTriggerInteraction.Ignore);
    for (int i = 0; i < penetrationCount; ++i)
    {
        var otherCollider = _penetrationColliders[i];
        if (Physics.ComputePenetration(
            _mainCollider, newPosition, Quaternion.identity,
            otherCollider, otherCollider.transform.position, otherCollider.transform.rotation,
            out _, out var distance))
        {
            if (otherCollider.gameObject != gameObject)
            {
                newPosition += Vector3.Normalize(otherCollider.ClosestPointNonAlloc(newPosition)) * (distance + SkinRadius);
            }
        }
    }

    // Calculate instantaneous velocity and move the Rigidbody
    Vector3 instantVelocity = (newPosition - transform.position) / Time.deltaTime;
    _rigidbody.MovePosition(newPosition);

    // Handle state changes
    HandleStateChange(newState);

    // Set animation speed
    _animator.SetFloat(AnimatorProperties.Speed, instantVelocity.magnitude / Settings.MovementSpeed);
}

// Helper function for more readable penetration adjustment
private Vector3 AdjustForPenetration(Vector3 position, Collider otherCollider, float distance)
{
    return position + Vector3.Normalize(otherCollider.ClosestPointNonAlloc(position)) * (distance + SkinRadius);
}

class Solution {
    static final int MODULO = 1000000007;

    public int numberOfGoodSubarraySplits(int[] nums) {
        int count = 0, ones = 0;
        for (int num : nums) {
            ones += num == 1? 1 : 0;
            if (ones > 1) {
                count = (int) ((long) count * (ones - 1) % MODULO);
            }
        }
        return ones > 1? count : 0;
    }
}

