import csv

class MappingTableWriter:
    def __init__(self, platform, graph, path, process_prefix='process_', process_suffix='_end', metadata_exec_time='exec_time', metadata_energy='energy', attributes=None):
        self.platform = platform
        self.graph = graph
        self.path = path
        self.process_prefix = process_prefix
        self.process_suffix = process_suffix
        self.metadata_exec_time = metadata_exec_time
        self.metadata_energy = metadata_energy
        self.attributes = attributes or {}
        self.file = None
        self.writer = None
        self.fieldnames = self._generate_fieldnames()

    def _generate_fieldnames(self):
        process_columns = [f"{self.process_prefix}{node}{self.process_suffix}" for node in self.graph.nodes]
        metadata_columns = [col for col in [self.metadata_exec_time, self.metadata_energy] if col]
        additional_columns = list(self.attributes.keys())
        return process_columns + metadata_columns + additional_columns

    def open(self):
        self.file = open(self.path, 'w', newline='')
        self.writer = csv.DictWriter(self.file, fieldnames=self.fieldnames)
        self.writer.writeheader()

    def write_header(self):
        if not self.writer:
            self.open()

    def write_mapping(self, mapping):
        row = {}
        for node in self.graph.nodes:
            row[f"{self.process_prefix}{node}{self.process_suffix}"] = mapping.process_allocation.get(node, '')

        if self.metadata_exec_time:
            row[self.metadata_exec_time] = mapping.metadata.get('exec_time', '')

        if self.metadata_energy:
            row[self.metadata_energy] = mapping.metadata.get('energy', '')

        for attr, func in self.attributes.items():
            row[attr] = func(mapping)

        self.writer.writerow(row)

    def close(self):
        if self.file:
            self.file.close()
            self.file = None
            self.writer = None

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

