package storage

import (
	"bytes"
)

type Storage struct {
	data      *bytes.Buffer
	rowSize   int
	maxSize   int
	rowCount  int
	cache     *bytes.Buffer
}

func NewStorage(rowSize, maxSize int) *Storage {
	return &Storage{
		data: bytes.NewBuffer(make([]byte, 0, maxSize)),
		rowSize: rowSize,
		maxSize: maxSize,
		cache: bytes.NewBuffer(make([]byte, 0, rowSize)),
	}
}

func (s *Storage) Write(data []byte) bool {
	s.rowCount++
	if s.rowSize != len(data) {
		return false
	}

	s.cache.Write(data)
	if s.cache.Len() == s.rowSize {
        return s.Flush()
	}
	return false
}

func (s *Storage) Flush() bool {
	if s.data.Len()+s.cache.Len() <= s.maxSize {
		s.data.Write(s.cache.Bytes())
		s.cache.Reset()
		return true
	}
	s.cache.Reset()
	return false
}

