int main() {
    int N;
    cin >> N;

    vector<tuple<int, int, int64_t>> V(N);
    for (int i = 0; i < N; ++i) {
        int x, y;
        int64_t h;
        cin >> x >> y >> h;
        V[i] = make_tuple(h, x, y);
    }

    // Sort the vector in descending order based on the height
    sort(V.begin(), V.end(), [](const tuple<int, int, int64_t>& a, const tuple<int, int, int64_t>& b) {
        return get<0>(a) > get<0>(b);
    });

    tuple<int, int, int64_t> ans;
    bool found = false;

    for (int cx = 0; cx <= 100 && !found; ++cx) {
        for (int cy = 0; cy <= 100 && !found; ++cy) {
            int64_t ch = get<0>(V[0]) + abs(get<1>(V[0]) - cx) + abs(get<2>(V[0]) - cy);
            bool match = true;

            for (const auto& [h, x, y] : V) {
                int64_t _h = max<int64_t>(0, ch - abs(x - cx) - abs(y - cy));
                if (h != _h) {
                    match = false;
                    break;
                }
            }

            if (match) {
                ans = make_tuple(cx, cy, ch);
                found = true;
            }
        }
    }

    cout << get<0>(ans) << " " << get<1>(ans) << " " << get<2>(ans) << endl;
}

