public class CrcCalculator {
    public boolean performCRCCalculation(byte[] bytes, int crcTest) {
        int crc = 0xFFFF; // start value
        int polynomial = 0x1021; // poly value
        for (byte b : bytes) {
            for (int i = 0; i < 8; i++) {
                boolean bit = ((b >> (7-i) & 1) == 1);
                boolean c15 = ((crc >> 15 & 1) == 1);
                crc <<= 1;
                if (c15 ^ bit) crc ^= polynomial;
            }
        }
        crc &= 0xffff;
        return crc == crcTest;
    }
}

