// Deecode RLP, and rebuild transaction with signature, finally encode the whole thing
func EncodeWithSignature(rlpEncoded []byte, sig []byte) (code int, err error) {
	// Decode RLP
	var tx types.Transaction
	err = rlp.DecodeBytes(rlpEncoded, &tx)
	if err != nil {
		return 0, fmt.Errorf("decode rlp err:%s", err)
	}

	// Rebuild transaction with signature
	tx.Signature = sig

	// Encode whole thing
	buf := new(bytes.Buffer)
	err = rlp.Encode(buf, &tx)
	if err != nil {
		return 0, fmt.Errorf("encode rlp err:%s", err)
	}

	code = int(binary.LittleEndian.Uint64(buf.Bytes()))
	return code, nil
}

