import sys

class Node:
    """Represents a node in the tree."""
    def __init__(self, number):
        self.number = number
        self.parent = None
        self.children = []

def main():
    input = sys.stdin.readline
    n = int(input())
    nodes = [Node(i) for i in range(n)]

    for i in range(n):
        node_number, _, *children = map(int, input().split())
        nodes[node_number].children = children
        for child in children:
            nodes[child].parent = nodes[node_number]

    root = next((node for node in nodes if node.parent is None), None)
    if root is None:
        raise ValueError("No root node found")

    # Set depth for all nodes
    depths = {}
    def set_depth(node, depth):
        depths[node.number] = depth
        for child in node.children:
            set_depth(nodes[child], depth + 1)
    set_depth(root, 0)

    # Show tree
    for node in nodes:
        node_type = 'root' if node.parent is None else 'leaf' if not node.children else 'internal node'
        print(f'node {node.number}: parent = {node.parent.number if node.parent else -1}, depth = {depths[node.number]}, {node_type}, children = {node.children}')

