class Solution:
    def NumberOFTurns(self, root, first, second):
        def find_lca(root, first, second):
            if root is None:
                return None
            if root.data == first or root.data == second:
                return root
            left_lca = find_lca(root.left, first, second)
            right_lca = find_lca(root.right, first, second)
            if left_lca and right_lca:
                return root
            return left_lca if left_lca is not None else right_lca

        def count_turns(root, target, direction):
            if root is None:
                return float('inf'), []
            if root.data == target:
                return 0, []
            left_turns, left_path = count_turns(root.left, target, 'left')
            right_turns, right_path = count_turns(root.right, target, 'right')
            if left_turns < right_turns:
                if direction and direction != 'left':
                    return left_turns + 1, ['left'] + left_path
                return left_turns, ['left'] + left_path
            else:
                if direction and direction != 'right':
                    return right_turns + 1, ['right'] + right_path
                return right_turns, ['right'] + right_path

        lca = find_lca(root, first, second)
        if lca is None:
            return -1

        first_turns, first_path = count_turns(lca, first, None)
        second_turns, second_path = count_turns(lca, second, None)

        total_turns = first_turns + second_turns
        if first_turns > 0 and second_turns > 0:
            total_turns -= 1  # Subtract one turn if both paths start in different directions

        return total_turns if total_turns > 0 else -1

public class StateFinder {

    /**
     * Returns the specific state in the sequence alphabet from its integer index.
     * Alternative (ambiguity) alphabet use values > alphabet size, i.e.,
     * as if appended after the original alphabet.
     *
     * @param i the integer code.
     * @return a state (character) from the alphabet.
     */
    public char getStateFromIndex(int i) {
        char[] alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".toCharArray();
        return alphabet[i % alphabet.length];
    }

    public static void main(String[] args) {
        StateFinder finder = new StateFinder();

        // Example usage:
        System.out.println(finder.getStateFromIndex(26)); // Should print 'a' (starting from 0)
        System.out.println(finder.getStateFromIndex(35)); // Should print 'b' since 35 % 62 = 33 (in zero-based index)
        System.out.println(finder.getStateFromIndex(62)); // Should print '0' since 62 % 62 = 0
    }
