// ProfitForecast project estimates profit for a product segment based on the sales figures.
// It requires an input of a ProductSegment with no more than 10 years of annual sales.
// The function returns the projected profit and an error if constraints are not met.
func (ps *ProductSegment) ProfitForecast(slices int) (float64, *error) {
	if len(ps.AnnualSalesFigures) > 10 {
		return 0.0, &errors.New("cannot process more than 10 years of sales data")
	}

	totalSales := 0
	for _, yearlySales := range ps.AnnualSalesFigures {
		totalSales += yearlySales
	}
	projection := float64(totalSales) * 0.75 // Projects three-quarters as profit
	return projection, nil
}

