from collections import deque

def input_matrix(n):
    return [list(input().strip()) for _ in range(n)]

def build_graph(n, adjacency_matrix):
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if adjacency_matrix[i][j] == '1':
                graph[i].append(j)
    return graph

def is_bipartite(graph, n):
    colors = [0] * n
    def dfs(v, color):
        colors[v] = color
        for to in graph[v]:
            if colors[to] == color:
                return False
            if colors[to] == 0 and not dfs(to, -color):
                return False
        return True
    return dfs(0, 1)

def bfs_diameter(graph, n):
    def bfs(start):
        visited = [False] * n
        q = deque([(start, 0)])
        visited[start] = True
        farthest_node, farthest_distance = start, 0
        while q:
            node, dist = q.popleft()
            if dist > farthest_distance:
                farthest_node, farthest_distance = node, dist
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    q.append((neighbor, dist + 1))
        return farthest_node, farthest_distance

    # First BFS to find the farthest node from an arbitrary node (0)
    start_node, _ = bfs(0)
    # Second BFS from the farthest node to find the actual diameter
    _, diameter = bfs(start_node)
    return diameter

def main():
    n = int(input().strip())
    adjacency_matrix = input_matrix(n)
    graph = build_graph(n, adjacency_matrix)

    if not is_bipartite(graph, n):
        print(-1)
        return

    diameter = bfs_diameter(graph, n)
    print(diameter + 1)

if __name__ == "__main__":
