function countElements(container) {
  const countMethod = container.count;
  const sizeMember = container.size;
  const lengthAttr = container.length;

  if (typeof countMethod === 'function') {
    return countMethod.call(container);
  }

  if (typeof sizeMember !== 'undefined') {
    return sizeMember;
  }

  if (typeof lengthAttr !== 'undefined') {
    return lengthAttr;
  }

  if (typeof container === 'object') {
    let count = 0;
    for (let key in container) {
      if (container.hasOwnProperty(key)) {
        count++;
      }
    }
    return count;
  }

  return 0;
}

