public class DeleteFileAsync {

    public static CompletableFuture<Void> deleteFileAsync(String filePath) {
        ExecutorService executor = Executors.newCachedThreadPool();
        CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
            try {
                Files.delete(Path.of(filePath));
            } catch (IOException e) {
                System.out.println("Error deleting file: " + e.getMessage());
            }
        }, executor);

        executor.shutdown();
        return future;
    }

    public static void main(String[] args) {
        String filePath = "path/to/file.txt";
        CompletableFuture<Void> future = deleteFileAsync(filePath);
        System.out.println("File deletion task submitted. Waiting for completion...");
        future.join();
        System.out.println("File deletion completed.");
    }
}

