class Solution:
    def firstDayBeenInAllRooms(self, nextVisit: List[int]) -> int:
        n = len(nextVisit)
        f1 = [None] * n
        f1[0] = 1
        m = 10 ** 9 + 7 

        for i in range(1, n):
            f1_current = f1[i - 1] + 1
            if nextVisit[i] != i:
                f1_next = (2 * f1_current - f1[nextVisit[i]] + 1) % m
            else:
                f1_next = f1_current + 1
            f1[i] = f1_current
            f1[i - 1] = f1_next  # Store f2 in f1 for the next iteration

        return (f1[n - 2] - 1) % m  # f1[n-2] holds the value of f2[n-2] at the end of the loop

