class Solution {
public:
    int largestCombination(std::vector<int>& candidates) {
        int result = 0;
        int maxBit = sizeof(int) * CHAR_BIT - 1; // Handle different integer sizes

        for (int k = maxBit; k >= 0; --k) {
            int count = 0;
            for (const int& candidate : candidates) {
                if ((candidate >> k) & 1) {
                    ++count;
                }
            }
            result = std::max(result, count);
        }
        return result;
    }
};

