public string GetOriginalExtension(string path, string appendedExtension)
{
    if (string.IsNullOrEmpty(path) || string.IsNullOrEmpty(appendedExtension))
    {
        return string.Empty;
    }

    int lastAppendedExtensionIndex = path.LastIndexOf(appendedExtension);
    if (lastAppendedExtensionIndex == -1)
    {
        return Path.GetExtension(path);
    }

    string trimmedPath = path.Substring(0, lastAppendedExtensionIndex);
    return Path.GetExtension(trimmedPath);
}

