public class Solution {
    public int findTargetSumWays(int[] nums, int S) {
        int maxSum = 0;
        for (int num : nums) {
            maxSum += num; 
        }
        if (S > maxSum || S < -maxSum) {
            return 0;
        }

        int[] ways = new int[2 * maxSum + 1];
        int[] oldWays = new int[2 * maxSum + 1];
        int offset = maxSum;
        oldWays[offset] = 1;

        for (int num : nums) {
            for (int i = -maxSum; i <= maxSum; i++) {
                int thisWays = 0;
                if (i - num >= -maxSum) {
                    thisWays += oldWays[i - num + offset];
                }
                if (i + num <= maxSum) {
                    thisWays += oldWays[i + num + offset];
                }
                ways[i + offset] = thisWays;
            }
            // Swap the arrays
            int[] temp = oldWays;
            oldWays = ways;
            ways = temp;
            // Reset the ways array
            for (int i = 0; i < ways.length; i++) {
                ways[i] = 0;
            }
        }

        return oldWays[S + offset];
    }
}

