func (c *Client) call(ctx context.Context, method string, req, rsp interface{}, h callHook) error {
	// Ensure hook is not nil
	if h == nil {
		h = &noopHook{}
	}

	// Check if response is pre-constructed
	if rspBuf, appErr, ok := h.GetResponse(method); ok {
		return c.unmarshalRsp(rspBuf, appErr, rsp, h)
	}

	// Marshal request
	reqBuf, err := Marshal(req)
	if err != nil {
		h.OnError(err)
		return context.Canceled
	}

	// Request hook
	if err = h.OnRequest(method, reqBuf); err != nil {
		h.OnError(err)
		return context.Canceled
	}

	// Set up a context with timeout
	ctxT, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	// Perform the call
	rspBuf, appErr, err := c.t.Call(ctxT, method, reqBuf)
	if ctxErr := ctxT.Err(); ctxErr != nil {
		h.OnError(ctxErr)
		if ctxErr == context.DeadlineExceeded {
			if timeoutErr := h.OnTimeout(method, ctxErr.Error()); timeoutErr != nil {
				h.OnError(timeoutErr)
				return context.Canceled
			}
		}
		return ctxErr // handling DeadlineExceeded or Canceled
	}

	// Separate handling of Call's error
	if err != nil {
		h.OnError(err)
		return context.Canceled
	}

	// Response hook
	if err = h.OnResponse(method, rspBuf, appErr); err != nil {
		h.OnError(err)
		return context.Canceled
	}

	// Unmarshal response
	return c.unmarshalRsp(rspBuf, appErr, rsp, h)
}

