public class PEMContentGenerator {

    public static void pemContent(ByteStringBuilder target, String type, Base64Iterator content) throws IllegalArgumentException {
        if (target == null || type == null || content == null) {
            throw new IllegalArgumentException("Invalid input");
        }

        target.string("-----BEGIN " + type + "-----\n");
        target.string("-----END " + type + "-----\n");
        while (content.hasNext()) {
            target.string(content.next().encodeAsString() + "\n");
        }
        target.string("\n");
    }
}

IOReturn AzulNX2Ethernet::enablePHYAutoMDIX() {
  IOReturn status;
  UInt16 reg;

  //
  // Get value of misc control shadow register.
  //
  status = writePhyReg16(PHY_AUX_CONTROL_SHADOW, PHY_AUX_CONTROL_SHADOW_SELECT_MISC_CONTROL);
  if (IORETURN_ERR(status)) {
    return status;
  }
  status = readPhyReg16(PHY_AUX_CONTROL_SHADOW, &reg);
  if (IORETURN_ERR(status)) {
    return status;
  }

  //
  // Enable Wirespeed, Auto MDIX crossover detection, and writing to the register.
  //
  // Note:
  // Uncomment the PHY_MISC_CONTROL_FORCE_AUTO_MDIX line if you want to forcibly enable Auto MDIX.
  // Otherwise, it will rely on the default setting.
  reg |= PHY_MISC_CONTROL_WIRESPEED_ENABLE | /*PHY_MISC_CONTROL_FORCE_AUTO_MDIX |*/ PHY_MISC_CONTROL_WRITE_ENABLE;

  status = writePhyReg16(PHY_AUX_CONTROL_SHADOW, reg);
  if (IORETURN_ERR(status)) {
    return status;
  }

  return kIOReturnSuccess;
}

