def combination(digits):
    """
    Generates all possible combinations of letters from a given phone number.

    Args:
    digits (str): A string of digits representing a phone number.

    Yields:
    str: A combination of letters corresponding to the input digits.
    """
    alphabet = {
        '2': 'abc',
        '3': 'def',
        '4': 'ghi',
        '5': 'jkl',
        '6': 'mno',
        '7': 'pqrs',
        '8': 'tuv',
        '9': 'wxyz'
    }

    if not digits:
        return
    elif len(digits) == 1:
        yield from alphabet[int(digits)]
    else:
        for letter in alphabet[int(digits[0])]:
            for result in combination(digits[1:]):
                yield letter + result

