class Solution {
    public int[] closestDivisors(int num) {
        int num1 = num + 1;
        int num2 = num + 2;
        int[] result1 = closest(num1);
        int[] result2 = closest(num2);
        int diff1 = Math.abs(result1[0] - result1[1]);
        int diff2 = Math.abs(result2[0] - result2[1]);

        return diff1 < diff2 ? result1 : result2;
    }

    private int[] closest(int num) {
        int minDiff = Integer.MAX_VALUE;
        int[] closestPair = new int[]{1, num};

        for (int i = (int) Math.sqrt(num); i > 0; i--) {
            if (num % i == 0) {
                int j = num / i;
                int diff = Math.abs(i - j);
                if (diff < minDiff) {
                    minDiff = diff;
                    closestPair[0] = i;
                    closestPair[1] = j;
                }
            }
        }
        return closestPair;
    }
}

