void VulkanRenderer::object_to_VkGeometryKHR(Mesh* mesh, VkAccelerationStructureGeometryKHR& acceleration_structure_geometry, 
                                             VkAccelerationStructureBuildRangeInfoKHR& acceleration_structure_build_range_info) {

    // Load the required function once using the Vulkan utility
    auto pvkGetBufferDeviceAddressKHR = reinterpret_cast<PFN_vkGetBufferDeviceAddressKHR>(
        vkGetDeviceProcAddr(MainDevice.logical_device, "vkGetBufferDeviceAddress")
    );

    // Helper lambda to get buffer device address
    auto get_buffer_device_address = [&pvkGetBufferDeviceAddressKHR](VkBuffer buffer) -> VkDeviceAddress {
        VkBufferDeviceAddressInfo buffer_device_address_info{};
        buffer_device_address_info.sType = VK_STRUCTURE_TYPE_BUFFER_DEVICE_ADDRESS_INFO;
        buffer_device_address_info.buffer = buffer;

        return pvkGetBufferDeviceAddressKHR(MainDevice.logical_device, &buffer_device_address_info);
    };

    // Get addresses for vertex and index buffers
    VkDeviceAddress vertex_buffer_address = get_buffer_device_address(mesh->get_vertex_buffer());
    VkDeviceAddress index_buffer_address = get_buffer_device_address(mesh->get_index_buffer());

    // Convert to const address for further processing
    auto to_const_address = [](VkDeviceAddress address) -> VkDeviceOrHostAddressConstKHR {
        VkDeviceOrHostAddressConstKHR const_address{};
        const_address.deviceAddress = address;
        return const_address;
    };

    VkDeviceOrHostAddressConstKHR vertex_address = to_const_address(vertex_buffer_address);
    VkDeviceOrHostAddressConstKHR index_address = to_const_address(index_buffer_address);

    // Setup triangles data
    VkAccelerationStructureGeometryTrianglesDataKHR triangles_data{};
    triangles_data.sType = VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_TRIANGLES_DATA_KHR;
    triangles_data.pNext = nullptr;
    triangles_data.vertexFormat = VK_FORMAT_R32G32B32_SFLOAT;
    triangles_data.vertexData = vertex_address;
    triangles_data.vertexStride = sizeof(Vertex);
    triangles_data.maxVertex = mesh->get_vertex_count();
    triangles_data.indexType = VK_INDEX_TYPE_UINT32;
    triangles_data.indexData = index_address;

    // Setup acceleration structure geometry data
    VkAccelerationStructureGeometryDataKHR geometry_data{};
    geometry_data.triangles = triangles_data;

    // Setup acceleration structure geometry
    acceleration_structure_geometry.sType = VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_KHR;
    acceleration_structure_geometry.pNext = nullptr;
    acceleration_structure_geometry.geometryType = VK_GEOMETRY_TYPE_TRIANGLES_KHR;
    acceleration_structure_geometry.geometry = geometry_data;
    acceleration_structure_geometry.flags = VK_GEOMETRY_OPAQUE_BIT_KHR;

    // Setup acceleration structure build range info
    acceleration_structure_build_range_info.primitiveCount = mesh->get_index_count() / 3; // Number of triangles
    acceleration_structure_build_range_info.primitiveOffset = 0;
    acceleration_structure_build_range_info.firstVertex = 0;
    acceleration_structure_build_range_info.transformOffset = 0;
}

int resolveServerIP(int server_port, const std::string& server_ip, int request_type) {
    // Remove extra, unnecessary comments
    if (server_ip.empty()) {
        // Invalid request
        return 1;
    }
    if (request_type == 1 && !server_ip.find('1') && !server_ip.find('2')) {
        // Invalid request
        return 1;
    }
    // Get the index of the server in a potential routing table
    int routing_table_index = getRoutingTableModel(server_port);

    // If the server is in the routing table...
    if (routing_table_index != -1) {
        // If the request_type is 2, resolve the server IP
        if (request_type == 2) {
            return 2;
        }
        // If the server is reachable...
        if (isServerReachable(routing_table_index)) {
            // The server IP is resolved
            return 2;
        }
        // The server is unreachable
        return 3;
    }
    // If the server is not in the routing table
    // or if the isServerReachable function returns false, 
    // it's an unknown exception
    return 3;
}

