#include <iostream>
#include <sstream>
#include <string>

struct App {
    std::string name;
    std::string version;
};

bool readAppTag(std::istream& input, App& app, std::string& error_detail) {
    std::string line;
    if (!std::getline(input, line)) {
        error_detail = "Failed to read line for <app> tag.";
        return false;
    }

    // Assuming the format is <app name="Appname" version="1.0">
    std::string prefix = "<app name=\"";
    size_t prefix_pos = line.find(prefix);
    if (prefix_pos == std::string::npos) {
        error_detail = "Invalid <app> tag format.";
        return false;
    }

    size_t name_end = line.find("\"", prefix_pos + prefix.length());
    if (name_end == std::string::npos) {
        error_detail = "Invalid <app> tag format, name not found.";
        return false;
    }

    app.name = line.substr(prefix_pos + prefix.length(), name_end - (prefix_pos + prefix.length()));

    std::string version_prefix = "\" version=\"";
    size_t version_pos = line.find(version_prefix, name_end);
    if (version_pos == std::string::npos) {
        error_detail = "Invalid <app> tag format, version not found.";
        return false;
    }

    size_t version_end = line.find("\"", version_pos + version_prefix.length());
    if (version_end == std::string::npos) {
        error_detail = "Invalid <app> tag format, version not closed.";
        return false;
    }

    app.version = line.substr(version_pos + version_prefix.length(), version_end - (version_pos + version_prefix.length()));

    // Check for closing tag
    if (line.find("</app>", version_end) == std::string::npos) {
        error_detail = "No closing </app> tag found.";
        return false;
    }

    return true;
}

