/** Deck.swap(cardPos1, cardPos2)
 * Swap the place of card1 with card2 */
Deck.prototype.swap = function(cardPos1, cardPos2) {
  for (var i = 0; i < this.cards.length; ++i) {
    if (this.cards[i].pos === cardPos1) {
      var temp = this.cards[i].pos;
      this.cards[i].pos = this.getCardByPosition(cardPos2).pos;
      this.getCardByPosition(cardPos2).pos = temp;
      this.draw();
      return;
    }
  }
};

/** Deck.getCardByPosition(pos)
 * Get the card at the specified position
 * @param pos position to get card from */
Deck.prototype.getCardByPosition = function(pos) {
  for (var i = 0; i < this.cards.length; ++i) {
    if (this.cards[i].pos === pos) {
      return this.cards[i];
    }
  }
  return null;
};

/** Deck.draw()
 * Draw all cards on the canvas */
Deck.prototype.draw = function() {
  gCanvasContext.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
  for (var i = 0; i < this.cards.length; ++i) {
    var card = this.cards[i];
    var srcX = (card.id % 3) * CARD_SIZE;
    var srcY = Math.floor(card.id / 3) * CARD_SIZE;
    var destX = (card.pos % 3) * CARD_SIZE;
    var destY = Math.floor(card.pos / 3) * CARD_SIZE;
    var rotation = card.r * Math.PI / 2;

    gCanvasContext.save();
    gCanvasContext.translate(destX + CARD_SIZE / 2, destY + CARD_SIZE / 2);
    gCanvasContext.rotate(rotation);
    gCanvasContext.drawImage(KAMO_IMAGE, srcX, srcY, CARD_SIZE, CARD_SIZE, -CARD_SIZE / 2, -CARD_SIZE / 2, CARD_SIZE, CARD_SIZE);
    gCanvasContext.restore();
  }
};

