/**
 * @param {number} filterMode
 * @param {WebGLContext} gl
 * @return {Array<number>}
 */
export function layerFilterMode(filterMode, gl) {
  const modeMap = {
    2: [gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA], // Blend
    3: [gl.ONE, gl.ONE], // Additive
    4: [gl.SRC_ALPHA, gl.ONE], // Add alpha
    5: [gl.ZERO, gl.SRC_COLOR], // Modulate
    6: [gl.DST_COLOR, gl.SRC_COLOR] // Modulate 2x
  };

  return modeMap[filterMode] || [0, 0];
}

/**
 * @param {number} filterMode
 * @param {WebGLContext} gl
 * @return {Array<number>}
 */
export function emitterFilterMode(filterMode, gl) {
  const modeMap = {
    0: [gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA], // Blend
    1: [gl.SRC_ALPHA, gl.ONE], // Add alpha
    2: [gl.ZERO, gl.SRC_COLOR], // Modulate
    3: [gl.DEST_COLOR, gl.SRC_COLOR], // Modulate 2x
  };

  return modeMap[filterMode] || [gl.SRC_ALPHA, gl.ONE]; // We fall back to add alpha for undefined filterMode
}

