public class SyntaxError implements Comparable<SyntaxError> {
    private String errorDescription;
    private int lineNumber;
    private String errorCategory;

    public SyntaxError(String description, int line) {
        this.errorDescription = description;
        this.lineNumber = line;
        this.errorCategory = determineErrorCategory();
    }

    private String determineErrorCategory() {
        // Simplified categorization logic. In real-world coding, this should be sophisticated
        if (description.contains("expected")) {
            return "Scanner";
        } else if (description.contains("structural") || description.contains("incorrect")) {
            return "Structural";
        } else {
            return "Identifier";
        }
    }

    @Override
    public int compareTo(SyntaxError other) {
        return Integer.compare(this.lineNumber, other.lineNumber);
    }

    @Override
    public String toString() {
        return "SyntaxError[description: " + errorDescription + ", line: " + lineNumber + ", category: " + errorCategory + "]";
    }

    public String toJSON() {
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        return gson.toJson(this);
    }

    public static SyntaxError fromJSON(String json) {
        Gson gson = new GsonBuilder().create();
        return gson.fromJson(json, SyntaxError.class);
    }

    public String getErrorRecoverySuggestion() {
        switch (errorCategory) {
            case "Scanner":
                return "Check if the scanner is properly closed after use.";
            case "Structural":
                return "Review the syntax around the problematic line to resolve structural errors.";
            case "Identifier":
                return "Verify that all identifiers are properly declared and scoped.";
            default:
                return "Check the error description for more details.";
        }
    }
}

