using namespace std;

constexpr int MAX_H = 505;
constexpr int MAX_N = 105;
constexpr int MAX_K = 105;
using ld = long double;

ld dp[MAX_H][MAX_K][MAX_N] = {};

int main() {
    int h, n, p, m, K;
    cin >> h >> n >> p >> m >> K;
    vector<int> v(h + 1, -1);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        v[a] = b;
    }

    dp[h + 1][0][p] = 1.0;

    for (int i = h; i >= 1; --i) {
        for (int j = 0; j <= K; ++j) {
            for (int k = 1; k <= n; ++k) {
                if (v[i] == -1) {
                    dp[i][j][k] = dp[i + 1][j][k];
                    if (j >= 1) {
                        if (k == 1 || k == n) {
                            dp[i][j][k] += dp[i + 1][j - 1][k] * (ld)(n - 2);
                        } else {
                            dp[i][j][k] += dp[i + 1][j - 1][k] * (ld)(n - 3);
                        }
                        if (k != 1) {
                            dp[i][j][k] += dp[i + 1][j - 1][k - 1];
                        }
                        if (k != n) {
                            dp[i][j][k] += dp[i + 1][j - 1][k + 1];
                        }
                    }
                } else {
                    if (k == v[i]) {
                        dp[i][j][k] = dp[i + 1][j][k + 1];
                    } else if (k == v[i] + 1) {
                        dp[i][j][k] = dp[i + 1][j][k - 1];
                    } else {
                        dp[i][j][k] = dp[i + 1][j][k];
                    }
                }
            }
        }
    }

    ld sum = 0.0;
    for (int i = 1; i <= n; ++i) {
        sum += dp[1][K][i];
    }

    ld max_prob = 0.0;
    for (int i = 1; i <= n; ++i) {
        max_prob = max(max_prob, dp[1][K][i] / sum);
    }

    cout << fixed << setprecision(15) << max_prob << endl;
    return 0;
}

