/**
 * Completes the new solution by inserting the missing items in the bins with a FistFit Decreasing Algorithm
 * @param missingItems the items that are not assigned to a bin in form of an ArrayList of Pairs
 * @return a two dimensional array. Each inner array represents a bin and contains the items assigned to it.
 */
public class Solution {
    public Pair[][] fistFitDecreasing(Pair[] missingItems) {
        // Sorting missing items in descending order (by value)
        Arrays.sort(missingItems, (a, b) -> Integer.compare(b.getValue(), a.getValue()));

        Pair[][] bins = new Pair[missingItems[0].getBin()][];
        for(int k=0;k<missingItems.length;k++){
            boolean binFound = false;
            for(int i=0;i<bins.length;i++){
                if(bins[i].length < bins[i].length + 1) {
                    bins[k].add(missingItems[i]);
                    binFound = true;
                    break;
                } else {
                    binFound = false;
                }
            }
        }

        return bins;
    }
}

