void dropout(const Eigen::MatrixXd &x, Eigen::MatrixXd &y, int seed, double dropProb, int leadingDim) {
  // input dimensions
  int rows = x.rows();
  int cols = x.cols();

  // set seed for random number generation
  std::srand(seed);

  // loop through rows or columns based on leadingDim
  for (int i = 0; i < (leadingDim == 0 ? rows : cols); i++) {
    // generate a random number
    double randNum = std::rand() / (double)RAND_MAX;

    // if random number is less than dropProb
    if (randNum < dropProb) {
      // zero out the elements of that row/column
      if (leadingDim == 0) {
        y.row(i) = x.row(i).array() * 0;
      } else {
        y.col(i) = x.col(i).array() * 0;
      }
    } else {
      // if not, scale the elements of that row/column by a factor of 1/(1-dropProb)
      if (leadingDim == 0) {
        y.row(i) = x.row(i).array() * (1.0 / (1.0 - dropProb));
      } else {
        y.col(i) = x.col(i).array() * (1.0 / (1.0 - dropProb));
      }
    }
  }
}

