class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n == m:
            return 1

        self.best = n * m

        def cover(rem, moves):
            # Try placing squares of different sizes
            for i in range(n):
                for j in range(m):
                    if not rem[i][j]:
                        break
                else:
                    continue
                break

            for size in range(min(n - i, m - j), 0, -1):
                if all(rem[x][y] == 0 for x in range(i, i + size) for y in range(j, j + size)):
                    for x in range(i, i + size):
                        for y in range(j, j + size):
                            rem[x][y] = 1
                    cover(rem, moves + 1)
                    for x in range(i, i + size):
                        for y in range(j, j + size):
                            rem[x][y] = 0
                    if moves + 1 >= self.best:
                        return

            if all(not any(row) for row in rem):
                self.best = min(self.best, moves)

        rem = [[0] * m for _ in range(n)]
        cover(rem, 0)
        return self.best

