public class Main {
    private static FastReader fr = new FastReader();
    private static PrintWriter pw = new PrintWriter(System.out);

    public static void solve() {
        int n = fr.nextInt();
        if (n < 3) {
            pw.println(0);
            return;
        }

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fr.nextInt();
        }

        Arrays.sort(a);

        long ans = 0;

        // Calculate the maximum score by considering both scenarios in a single loop
        for (int i = 1; i < n - 1; i++) {
            long score1 = a[n - 1] - a[0] + a[n - 1] - a[n - i - 1];
            long score2 = a[i] - a[0] + a[n - 1] - a[i - 1];
            ans = Math.max(ans, Math.max(score1, score2));
        }

        pw.println(ans);
    }

    public static void main(String[] args) {
        int t = fr.nextInt();
        while (t-- > 0) {
            solve();
        }
        pw.flush();
        pw.close();
    }

    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

