import java.util.Iterator;
import java.util.concurrent.TimeUnit;

public class RateLimitedEventIterator implements Iterator<Event> {
    private long currentEventNumber = 0;
    private long startTime = System.nanoTime();
    private double eventsPerSec;

    public RateLimitedEventIterator(double eventsPerSec) {
        this.eventsPerSec = eventsPerSec;
    }

    @Override
    public boolean hasNext() {
        return true; // This iterator theoretically generates events indefinitely.
    }

    @Override
    public Event next() {
        long currentTime = System.nanoTime();
        long elapsedNanos = currentTime - startTime;
        long expectedNanos = (long) (currentEventNumber * (1.0e9 / eventsPerSec));

        if (elapsedNanos < expectedNanos) {
            long waitNanos = expectedNanos - elapsedNanos;
            try {
                TimeUnit.NANOSECONDS.sleep(waitNanos);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while waiting", e);
            }
        }

        Event event = new Event(currentEventNumber, currentTime);
        currentEventNumber++;
        return event;
    }

    public static class Event {
        private final long eventNumber;
        private final long timestamp;

        public Event(long eventNumber, long timestamp) {
            this.eventNumber = eventNumber;
            this.timestamp = timestamp;
        }

        public long getEventNumber() {
            return eventNumber;
        }

        public long getTimestamp() {
            return timestamp;
        }

        @Override
        public String toString() {
            return "Event{" +
                    "eventNumber=" + eventNumber +
                    ", timestamp=" + timestamp +
                    '}';
        }
    }
}

