class Solution:
    def reorderList(self, head):
        if not head:
            return

        stack = []
        current = head
        while current:
            stack.append(current)
            current = current.next

        first, second = stack.pop(), stack.pop()
        while stack:
            first.next = second
            first = first.next = stack.pop()
            second = stack.pop()

        if stack:
            first.next = stack.pop()

        return head

