public class VersionedControllerSelector : IHttpControllerSelector
{
    private const string VersionKey = "version";
    private readonly HttpConfiguration _configuration;
    private readonly Lazy<Dictionary<string, HttpControllerDescriptor>> _controllers;

    public VersionedControllerSelector(HttpConfiguration configuration)
    {
        _configuration = configuration;
        _controllers = new Lazy<Dictionary<string, HttpControllerDescriptor>>(InitializeControllerDictionary);
    }

    public HttpControllerDescriptor SelectController(HttpRequestMessage request)
    {
        IHttpRouteData routeData = request.GetRouteData();
        if (routeData == null)
        {
            throw new InvalidOperationException("Route data not found.");
        }

        object version;
        if (!routeData.Values.TryGetValue(VersionKey, out version) || version == null)
        {
            throw new InvalidOperationException("Version key not found in route data.");
        }

        string controllerName;
        if (!routeData.Values.TryGetValue("controller", out controllerName) || string.IsNullOrEmpty(controllerName))
        {
            throw new InvalidOperationException("Controller name not found in route data.");
        }

        string versionedControllerName = $"{controllerName}Version{version}";
        string namespacedControllerName = $"Api.{versionedControllerName}Controller";

        var controllers = _controllers.Value;
        if (controllers.TryGetValue(namespacedControllerName, out HttpControllerDescriptor controllerDescriptor))
        {
            return controllerDescriptor;
        }

        throw new InvalidOperationException($"Controller not found for version {version}.");
    }

    public IDictionary<string, HttpControllerDescriptor> GetControllerMapping()
    {
        return _controllers.Value.ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }

    private Dictionary<string, HttpControllerDescriptor> InitializeControllerDictionary()
    {
        var controllers = _configuration.Services.GetHttpControllerSelector().GetControllerMapping();
        return controllers.ToDictionary(kvp => $"Api.{kvp.Key}Controller", kvp => kvp.Value);
    }
}

