func largestPalindromic(num string) string {
    count := make([]int, 10)
    for _, digit := range num {
        count[digit-'0']++
    }

    var firstHalf []byte
    for i := 9; i >= 0; i-- {
        firstHalf = append(firstHalf, bytes.Repeat([]byte{'0' + byte(i)}, count[i]/2)...)
    }

    middle := ""
    for i := 9; i >= 0; i-- {
        if count[i]&1!= 0 {
            middle = string('0' + byte(i))
            break
        }
    }

    secondHalf := make([]byte, len(firstHalf))
    copy(secondHalf, firstHalf)
    reverse(secondHalf)

    result := append(firstHalf, middle...)
    result = append(result, secondHalf...)
    if len(result) == 0 {
        return "0"
    }
    return string(result)
}

func reverse(s []byte) {
    for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
        s[i], s[j] = s[j], s[i]
    }
}

