private void positionPopup(final Popup popup, final PopupType popupType, final PopupPosition popupPosition,
                             int offsetWidth, int offsetHeight) {
    int shadowWidth = popupType!= PopupType.POPUP? POPUP_SHADOW_WIDTH : 0;

    // Adjust offsetWidth and offsetHeight for shadow
    offsetWidth -= 2 * shadowWidth;
    offsetHeight -= 2 * shadowWidth;

    int left = popupPosition.getLeft() - shadowWidth;
    int top = popupPosition.getBottom() - shadowWidth;

    // Calculate window bounds
    int windowLeft = Window.getScrollLeft();
    int windowRight = Window.getClientWidth() + Window.getScrollLeft();
    int windowTop = Window.getScrollTop();
    int windowBottom = Window.getScrollTop() + Window.getClientHeight();

    // Adjust left position based on horizontal location
    if (HorizontalLocation.LEFT.equals(popupPosition.getHorizontalLocation())) {
        left = popupPosition.getRight() - offsetWidth + shadowWidth;
    } else if (popupPosition.getRight() - left < offsetWidth && left - windowLeft >= offsetWidth) {
        left = popupPosition.getRight() - offsetWidth + shadowWidth;
    } else if (left < 0) {
        left = 0;
    } else if (left + offsetWidth > windowRight) {
        left = windowRight - offsetWidth;
    }

    // Adjust top position based on vertical location
    if (VerticalLocation.ABOVE.equals(popupPosition.getVerticalLocation())) {
        top = popupPosition.getTop() - offsetHeight + shadowWidth;
    } else if (windowBottom - top < offsetHeight && top - windowTop >= offsetHeight) {
        top = popupPosition.getTop() - offsetHeight + shadowWidth;
    } else if (top < 0) {
        top = 0;
    } else if (top + offsetHeight > windowBottom) {
        top = windowBottom - offsetHeight;
    }

    // Ensure left and top positions are within window bounds
    left = Math.max(0, Math.min(left, windowRight - offsetWidth));
    top = Math.max(0, Math.min(top, windowBottom - offsetHeight));

    popup.setPopupPosition(left, top);
}

