def analyze_strategy(strategy):
    vars_to_partition = {}
    unpartitioned_vars = {}

    # Analyze the strategy to get the partition and reduction information
    for variable, details in strategy.items():
        partition_str = details['partition_str']
        reduction_devices = details['reduction_devices']
        vars_to_partition[variable] = (partition_str, reduction_devices)

        # Unpartitioned vars are the variables that are not considered for partitioning
        unpartitioned_vars[variable] = variable

    return vars_to_partition, unpartitioned_vars

