class DocTags:
    def __init__(self, dt):
        self.dt = dt

    def get_tag_fields(self):
        """Returns tag fields for the document type."""
        return frappe.db.get_value('DocType', self.dt, 'tag_fields')

    def get_tags(self, dn):
        """Returns tags for a particular document."""
        return (frappe.db.get_value(self.dt, dn, '_user_tags', ignore=1) or '').strip()

    def add(self, dn, tag):
        """Adds a new user tag."""
        self.update(dn, self.get_tags(dn) + ',' + tag)

    def remove(self, dn, tag):
        """Removes a user tag."""
        self.update(dn, self.get_tags(dn).replace(',' + tag + ',', ','))

    def remove_all(self, dn):
        """Removes all user tags."""
        self.update(dn, '')

    def update(self, dn, tags):
        """Updates the _user_tags column in the table."""
        if tags:
            tags = unique(tags.split(','))
        else:
            tags = ''
        frappe.db.sql("update `tab%s` set _user_tags=%s where name=%s" % (self.dt, '%s', dn), (tags, dn))

    def setup(self):
        """Adds the _user_tags column if not exists."""
        from frappe.database.schema import add_column
        add_column(self.dt, "_user_tags", "Data")

