 * the database. 
 * @param result
 * @param entityClass
 * @param deleteAllRows
 */
public <T> void insertEntityData(GenericType<T> result, Class<T> entityClass, boolean deleteAllRows) {
    if (deleteAllRows) {
        // Delete all rows from the table corresponding to the entity class
        database.deleteAllRows(entityClass);
    }

    // Get the list of entities from the result
    List<T> entities = result.getList();

    // Insert each entity into the database
    for (T entity : entities) {
        database.insert(entityClass, entity);
    }
