private void ResetPosition()
{
    cullArea.transform.position = Vector3.zero;
}

private void ResetScaling()
{
    cullArea.transform.localScale = new Vector3(25.0f, 25.0f, 25.0f);
}

private void HandleTransformChanges()
{
    // Ensuring transform updates don't modify unnecessary components if Y is the up axis
    float posX = cullArea.transform.position.x;
    float posY = cullArea.YIsUpAxis ? cullArea.transform.position.y : 0.0f;
    float posZ = !cullArea.YIsUpAxis ? cullArea.transform.position.z : 0.0f;
    cullArea.transform.position = new Vector3(posX, posY, posZ);

    // Adjusting scaling for being too small, but maintaining original offsets
    AdjustScaling();

    cullArea.RecreateCellHierarchy = true;
    AlignEditorView();
}

private void AdjustScaling()
{
    float scaleX = Mathf.Max(1.0f, cullArea.transform.localScale.x);
    float scaleY = Mathf.Max(1.0f, cullArea.transform.localScale.y);
    float scaleZ = Mathf.Max(1.0f, cullArea.transform.localScale.z);

    cullArea.transform.localScale = new Vector3(scaleX, scaleY, scaleZ);

    if (cullArea.transform.localScale.x < 1.0f || cullArea.transform.localScale.y < 1.0f)
    {
        Debug.LogWarning("Scaling on a single axis cannot be lower than 1. Resetting...");
    }
}

class Node:
    def __init__(self, parent, left, right):
        self.parent = parent
        self.left = left
        self.right = right

    def __repr__(self):
        return f'{self.parent} {self.left} {self.right}'

class BinarySearchTree:
    def __init__(self, size):
        self.tree = [Node(-1, -1, -1) for _ in range(size + 1)]
        self.root = None

    def add(self, key, left, right):
        self.tree[key].left = left
        self.tree[key].right = right
        if left!= -1:
            self.tree[left].parent = key
        if right!= -1:
            self.tree[right].parent = key

    def height(self, node):
        if node == -1:
            return 0
        return 1 + max(self.height(self.tree[node].left), self.height(self.tree[node].right))

    def depth(self, node):
        if node == -1:
            return -1
        return 1 + self.depth(self.tree[node].parent)

    def node_type(self, node):
        if node.parent == -1:
            return 'root'
        elif node.left == node.right == -1:
            return 'leaf'
        return 'internal node'

    def print_all(self):
        self.root = next((i for i, node in enumerate(self.tree) if node.parent == -1), None)
        for idx, node in enumerate(self.tree):
            if node.parent == -1:
                continue
            parent = node.parent
            sibling = self.tree[parent].left if node == self.tree[parent].right else self.tree[parent].right
            degree = sum(1 for child in [node.left, node.right] if child!= -1)
            depth = self.depth(idx)
            height = self.height(idx)
            typed = self.node_type(node)
            print(f'node {idx}: parent = {parent}, sibling = {sibling}, degree = {degree}, depth = {depth}, height = {height}, {typed}')

