public boolean doLayout(int[] bounds, float alignX, float alignY, boolean debug, boolean checkPrefChange) {
    // Assuming there are some instance variables and methods already defined
    // that are used in the layout process.

    boolean preferredSizeChanged = false;

    // Use the bounds to layout components
    for (Component component : components) {
        int x = calculateX(bounds[0], bounds[2], component.getWidth(), alignX);
        int y = calculateY(bounds[1], bounds[3], component.getHeight(), alignY);
        component.setBounds(x, y, component.getWidth(), component.getHeight());

        if (debug) {
            debugRects.add(new Rectangle(x, y, component.getWidth(), component.getHeight()));
        }

        if (checkPrefChange) {
            Dimension newPrefSize = component.getPreferredSize();
            if (!newPrefSize.equals(component.getPreferredSize())) {
                component.setPreferredSize(newPrefSize);
                preferredSizeChanged = true;
            }
        }
    }

    return preferredSizeChanged;
}

private int calculateX(int x, int width, int componentWidth, float alignX) {
    return x + (int) ((width - componentWidth) * alignX);
}

private int calculateY(int y, int height, int componentHeight, float alignY) {
    return y + (int) ((height - componentHeight) * alignY);
}

