type CLI struct {
	playerStore  PlayerStore
	in           *bufio.Scanner
	out          io.Writer
	game         Game
}

const (
	PlayerPrompt           = "Please enter the number of players: "
	BadPlayerInputErrMsg   = "Bad value received for number of players, please try again with a number"
	BadWinnerInputMsg      = "Invalid winner input, expected format of 'PlayerName wins'"
)

func NewCLI(in io.Reader, out io.Writer, game Game) *CLI {
	return &CLI{
		in:   bufio.NewScanner(in),
		out:  out,
		game: game,
	}
}

func (cli *CLI) PlayPoker() {
	displayPrompt(cli.out, PlayerPrompt)
	numberOfPlayers, err := readNumberInput(cli.in)

	if err != nil {
		fmt.Fprint(cli.out, BadPlayerInputErrMsg)
		return
	}

	cli.game.Start(numberOfPlayers, cli.out)

	winnerInput := readLine(cli.in)
	winner, err := extractWinner(winnerInput)

	if err != nil {
		fmt.Fprint(cli.out, BadWinnerInputMsg)
		return
	}

	cli.game.Finish(winner)
}

func displayPrompt(out io.Writer, prompt string) {
	fmt.Fprint(out, prompt)
}

func readNumberInput(scanner *bufio.Scanner) (int, error) {  // awaiting for more context like from which file/event is scanning
	clientNumber, err := strconv.Atoi(readLine(scanner))

	if err != nil {
		return 0, err
	}

	return clientNumber, nil
}

func extractWinner(userInput string) (string, error) {
	if !strings.HasSuffix(userInput, " wins") {
		return "", errors.New(BadWinnerInputMsg)
	}
	return strings.TrimSpace(strings.TrimSuffix(userInput, " wins")), nil
}

func readLine(scanner *bufio.Scanner) string {
	if scanner.Scan() {
		return scanner.Text()
	}
	return ""
}

