import java.util.PriorityQueue;

class Solution {
    public int eatenApples(int[] apples, int[] days) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int ans = 0;
        int day = 1;

        while (true) {
            // Add new apples to the priority queue
            int i = day - 1;
            if (i < apples.length && apples[i] != 0) {
                pq.add(new int[]{i + days[i], apples[i]});
            }

            // Remove rotten apples from the priority queue
            while (!pq.isEmpty() && (pq.peek()[0] <= day || pq.peek()[1] == 0)) {
                pq.poll();
            }

            // Eat an apple if possible
            if (!pq.isEmpty()) {
                int[] top = pq.poll();
                ans++;
                top[1]--; // Decrement the count of apples
                if (top[1] > 0) {
                    pq.add(top); // Add the remaining apples back to the queue if there are any left
                }
            }

            // If there are no more apples to eat and no more days to consider, break the loop
            if (pq.isEmpty() && i >= apples.length - 1) {
                break;
            }

            day++;
        }

        return ans;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] apples = {1, 2, 3, 5, 2};
        int[] days = {3, 2, 1, 4, 2};
        int result = solution.eatenApples(apples, days);
        System.out.println("Total apples eaten: " + result);
    }
}

