/**
 * Copy the OR port (IP address and TCP port) for a given router and family
 * into the provided tor_addr_port_t structure.
 *
 * If the requested ORPort does not exist, sets *ap_out to the null
 * address and port, and returns -1. Otherwise, returns 0.
 */
int
router_get_orport(const routerinfo_t *router,
                  tor_addr_port_t *ap_out,
                  int family)
{
  tor_assert(ap_out != NULL);

  if (family == AF_INET) {
    // Check if the IPv4 orport is valid and not the default null address
    if (tor_addr_is_valid(&router->ipv4_addr) && router->ipv4_orport != 0) {
      tor_addr_copy(&ap_out->addr, &router->ipv4_addr);
      ap_out->port = router->ipv4_orport;
      return 0;
    } else {
      tor_addr_port_make_null_ap(ap_out, AF_INET);
      return -1;
    }
  } else if (family == AF_INET6) {
    // IPv6 addresses are optional, so check if it is valid.
    if (tor_addr_is_valid(&router->ipv6_addr) && router->ipv6_orport != 0) {
      tor_addr_copy(&ap_out->addr, &router->ipv6_addr);
      ap_out->port = router->ipv6_orport;
      return 0;
    } else {
      tor_addr_port_make_null_ap(ap_out, AF_INET6);
      return -1;
    }
  } else {
    // Unsupported address family
    tor_assert_nonfatal_unreached();
    tor_addr_port_make_null_ap(ap_out, AF_UNSPEC);
    return -1;
  }
}

/**
 * Helper function to determine if an ORPort is valid.
 *
 * Returns true if the provided tor_addr_port_t structure represents a valid ORPort.
 */
bool
tor_addr_port_is_valid(const tor_addr_t *addr, uint16_t port, int flags)
{
  // Check if the IP address and port are valid
  return tor_addr_is_valid(addr) && port != 0;
}

/**
 * Helper function to make a tor_addr_port_t structure null.
 *
 * Sets the IP address to the null address and the port to 0.
 */
void
tor_addr_port_make_null_ap(tor_addr_port_t *ap, int family)
{
  tor_addr_make_null(&ap->addr, family);
  ap->port = 0;
}

