public class PollingService extends IntentService {

    private static final String TAG = "PollingService";

    public PollingService() {
        super("PollingService");
    }

    @Override
    protected void onHandleIntent(Intent intent) {
        Log.d(TAG, "Attempting to poll");
        HttpResponse response = null;
        JsonParser jsonParser = null;

        try {
            response = new APIClient(this).get("/poll", "");
            int status = response.getStatusLine().getStatusCode();

            if (status >= 200 && status < 300) {
                Log.d(TAG, "Got server response");
                ObjectMapper objectMapper = new ObjectMapper();
                ObjectReader objectReader = objectMapper.readerForUpdating(new ToSend());
                jsonParser = objectMapper.getJsonFactory().createJsonParser(response.getEntity().getContent());

                jsonParser.nextToken(); // StartArray
                while (jsonParser.nextToken() != JsonToken.END_ARRAY) {
                    ToSend toSend = objectReader.readValue(jsonParser);
                    Util.sendSms(toSend.getTarget(), toSend.getMessage());
                }
            } else {
                String body = EntityUtils.toString(response.getEntity());
                Log.e(TAG, "Error while contacting server. Got status " + status + " and response: " + body);
            }
        } catch (Exception e) {
            Log.e(TAG, "Error while contacting server", e);
        } finally {
            closeResource(jsonParser);
            closeResource(response);
        }
    }

    private void closeResource(Closeable resource) {
        if (resource != null) {
            try {
                resource.close();
            } catch (IOException e) {
                Log.w(TAG, "Error closing resource", e);
            }
        }
    }
}

