        /// <summary>
        /// Initializes a new instance of the <see cref="UserController"/> class.
        /// </summary>
        /// <param name="userService">The injected <see cref="IUserService"/> instance.</param>
        public UserController(IUserService userService)
        {
            _userService = userService ?? throw new ArgumentNullException(nameof(userService));
        }

        /// <summary>
        /// Gets users with vacations filtered by the given parameters.
        /// </summary>
        /// <param name="name">First, last, or full user name.</param>
        /// <param name="dateFrom">Vacation start date.</param>
        /// <param name="dateTo">Vacation end date.</param>
        /// <returns>A <see cref="JsonResult"/> containing data.</returns>
        [HttpGet]
        public async Task<IActionResult> GetUsersWithVacations(string name = null, DateTime? dateFrom = null, DateTime? dateTo = null)
        {
            var result = await _userService.GetUsersWithVacationsAsync(name, dateFrom, dateTo);
            return Json(result);
        }

        /// <summary>
        /// Gets the user by an ID.
        /// </summary>
        /// <param name="id">User ID.</param>
        /// <returns>A <see cref="JsonResult"/> containing data.</returns>
        [HttpGet("{id:int}")]
        [Authorize]
        public async Task<IActionResult> GetUserWithVacations(int? id)
        {
            if (!id.HasValue)
            {
                return BadRequest("User ID is required.");
            }

            var result = await _userService.GetAsync(id.Value);
            return result != null ? Json(result) : NotFound();
        }

        /// <summary>
        /// Authenticates user and provides a JWT token.
        /// </summary>
        /// <param name="data">The <see cref="LoginDto"/> instance containing data.</param>
        /// <returns>A <see cref="JsonResult"/> containing data.</returns>
        [HttpPost]
        [Route("login")]
        public async Task<IActionResult> LogIn([FromBody] LoginDto data)
        {
            if (data == null)
            {
                return BadRequest("Login data is required.");
            }

            var result = await _userService.AuthenticateAsync(data.Email, data.Password);
            return result != null ? Json(result) : Unauthorized();
        }
    }
}

