public class ServerManager
{
    private Dictionary<int, Delegate> _callbackRegistry = new Dictionary<int, Delegate>();
    private int _nextId = 0;

    /// <summary>
    /// Registers a callback delegate for server replies and returns the ID. ID == -1 if
    /// not unique and already registered.
    /// </summary>
    /// <param name="callback">The callback delegate to register.</param>
    /// <returns>The ID of the registered callback, or -1 if the callback is already registered.</returns>
    public int RegisterCallback(Delegate callback)
    {
        if (_callbackRegistry.ContainsValue(callback))
        {
            return -1;
        }

        int id = _nextId++;
        _callbackRegistry[id] = callback;
        return id;
    }
}

