public synchronized static int removeAllImageTrackers( NodeList elements, HTMLDivElement parentDiv, double trackerSizeLimit, Logger logger ) {
    int removedCount = 0;
    for( Node element : elements ) {
        if( element instanceof HTMLElement && element.parentNode == parentDiv ) {
            HTMLElement el = (HTMLElement) element;
            String encodedSize = el.getAttribute( "data-image-tracker" );
            if( encodedSize != null && Base64.getDecoder().decode(encodedSize).length() >= trackerSizeLimit ) {
                logger.info( "Removing image tracker from: " + el);
                el.removeAttribute( "data-image-tracker" );
                removedCount++;
                el.removeChild( el );
            }
        }
    }
    return removedCount;
}

