    cout.flush();
    ll res;
    cin >> res;
    return res;
}

void solve() {
    cin >> n;
    ll l = 1, r = n;
    while (r > l) {
        int mid = l + r >> 1;
        if (ask(1, mid)!= 0) r = mid;
        else l = mid + 1;
    }
    ll i = l - 1;
    ll j = tot - ask(i + 1, n) + i + 1;
    ll k = tot - (j - i) * (j - i - 1) / 2 - ask(j + 1, n) + j;
