/**
 * This write method is used to write all the element contacts from
 * the provided source object to the XML element. This visits all
 * the contacts marked with the <code>Element</code> annotation in
 * the source object. All annotated contacts are written as children
 * to the XML element. This will throw an exception if a required
 * contact within the source object is null. 
 * 
 * @param source this is the source object to be serialized
 * @param node this is the XML element to write elements to
 * @param section this is the section that defines the XML structure
 */
public void writeIEEEContact(java.lang.Object source, javax.xml.parsers.Element node, java.lang.Object section) {
    final java.lang.reflect.Field[] fields = source.getClass().getDeclaredFields();

    int sectionIndex = ((Iterable<?>) section).indexOf(source.getClass());

    int getAnnotatedFieldsCount = 0;

    for (java.lang.reflect.Field f : fields) {
        final java.lang.annotation.Annotation annotation = f.getAnnotation(javax.faces.el.ELContext.Element.class);
        if (annotation != null) {
            ++getAnnotatedFieldsCount;

            java.lang.reflect.Method getter = null;

            try {
                final java.lang.reflect.Method method = source.getClass().getMethod(f.getName(), new java.lang.Class[] {});
                if ((method != null) && (method.getAnnotation(javax.faces.el.ELContext.Element.class) != null)) {
                    getter = method;
                }
            } catch (Exception ex) {

            }

            if (getter != null) {
                try {
                    String value = (String) getter.invoke(source);

                    javax.xml.parsers.Element child = javax.xml.parsers.ElementFactory.createElement(value);
                    child.setAttribute("section", sectionIndex + "");
                    node.appendChild(child);
                } catch (Exception ex) {                  
                }
            }
        }
    }

