import heapq
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        if not grid:
            return -1

        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        queue = [(self.heuristic(m, n, 0, 0), 0, 0, 0)]
        visited = {(0, 0): 0}

        while queue:
            (heuristic, steps, row, col) = heapq.heappop(queue)
            if (row, col) == (m - 1, n - 1):
                return steps

            for y, x in directions:
                r, c = row + y, col + x
                if 0 <= r < m and 0 <= c < n:
                    total_ones = steps + grid[r][c]
                    if total_ones < visited.get((r, c), k + 1):
                        heapq.heappush(queue, (steps + 1 + self.heuristic(m, n, r, c), steps + 1, r, c))
                        visited[(r, c)] = total_ones

        return -1

    def heuristic(self, m, n, y, x):
        return m + n - y - x - 2

#include <ctime> // include the correct header for tm

class MatchQueue {
public:
    struct Match {
        int teamHome;
        int teamAway;
        tm date;
        Match* next;

        Match(int teamHome, int teamAway, tm date) 
            : teamHome(teamHome), teamAway(teamAway), date(date), next(nullptr) {}
    };

    MatchQueue() : head(nullptr), tail(nullptr) {}

    bool isEmpty() const { return head == nullptr; }

    void enqueue(Match* match) {
        match->next = nullptr;
        if (isEmpty()) {
            head = tail = match;
        } else {
            tail->next = match;
            tail = match;
        }
    }

    Match* dequeue() {
        if (isEmpty()) return nullptr;
        Match* const match = head;
        head = head->next;
        if (head == nullptr) tail = nullptr; // update tail if necessary
        return match;
    }

private:
    Match* head;
    Match* tail;
};

