/* Total amount of buffers in the pool */
#define POOL_SIZE 1024

/* Amount of buffers to keep available in the pool */
#define MARGIN 100

struct buffer_pool {
    int size;
    int used;
    pthread_mutex_t lock;
};

int ensure_enough_buffers(struct buffer_pool *pool, int needed)
{
    int ret = 0;
    int available;

    /* Acquire the lock to protect the critical section */
    pthread_mutex_lock(&pool->lock);

    /* Calculate how many buffers are currently available */
    available = pool->size - pool->used;

    /* If the needed amount of buffers aren't available, fail */
    if (needed > available - MARGIN)
        ret = -ENOMEM;
    else
        /* Otherwise, increment the used buffers count */
        pool->used += needed;

    /* Release the lock */
    pthread_mutex_unlock(&pool->lock);

    return ret;
}

