function optimizeSpriteRendering(ctx, spriteSheets, sprite, frameIndex) {

  const bufferCanvas = document.createElement('canvas');

  bufferCanvas.width = sprite.width;

  bufferCanvas.height = sprite.height;

  const bufferCtx = bufferCanvas.getContext('2d');


  bufferCtx.clearRect(0, 0, bufferCanvas.width, bufferCanvas.height);


  bufferCtx.drawImage(

    spriteSheets[sprite.sheetIndex],

    sprite.x * sprite.width + frameIndex * sprite.width,

    sprite.y * sprite.height,

    sprite.width,

    sprite.height,

    0,

    0,

    sprite.width,

    sprite.height

  );


  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  ctx.drawImage(bufferCanvas, 0, 0);

}

