public class SpawnObject {

    public int spawnObject(String oid, CollectedWorldMessage preMessage, CollectedWorldMessage postMessage) {
        Perceiver perceiver = getPerceiver(oid); //getPerceiver get the Perceiver object

        if (perceiver == null || !(perceiver instanceof NonMobilePerceiver)) {
            return -1; // Object does not exist or is not a mobile perceiver
        }

        if (perceiver.live() == -1) {
            return -2; // Object's instance does not exist on this world manager
        }

        if (perceiver.live() == 1) {
            return -3; // Object is already spawned
        }

        spawn(oid, preMessage, postMessage); // spawn suspends the object

        if (perceiver.live() == 0) {
            return 0; // Suspended
        } else {
            return 1; // Spawned
        }
    }

    //This may not be the correct method depending on the specific context, 
    // but it's just a placeholder for simplicity in this example
