int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        long long sum = 0;
        int a[100010] = {0};

        for (int i = 0; i < n; i++) {
            cin >> a[i];
            sum += a[i];
        }

        if (sum % n != 0) {
            cout << "-1\n";
            continue;
        }

        // Calculate the target value for each element
        long long target = sum / n;
        cout << 3 * (n - 1) << "\n";

        for (int i = 0; i < n - 1; i++) {
            cout << "1 " << i + 1 << " " << (a[n-1] % (n - i)) << "\n";
            a[0] += a[i+1];
            a[i+1] = 0;
        }

        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) {
                cout << "1 " << i + 1 << " " << (target - (a[i] % 2)) << "\n";
                a[0] += a[1];
                a[1] = 0;
            }
        }
    }
    return 0;
}

