from ghapi.all import GhApi
from bot.driven.repositories import ParamsRepository

class GithubService:
    def __init__(self, params_repository: ParamsRepository):
        self._params_repository = params_repository

    def _extract_repo_and_commit(self, url):
        """Extract repository and commit hash from a GitHub URL"""
        if not url.endswith(('/commit/', '/compare/')):
            return None

        url_parts = url.split('/')
        repo = url_parts[-2]
        commit_hash = url_parts[-1].split('...')[-1]

        return repo, commit_hash

    def _get_pr_url_from_commit(self, repo, commit_hash):
        """Get PR URL from commit hash"""
        api = GhApi(
            owner=self._params_repository.get_github_organization(), repo=repo)
        prs = api.search.issues_and_pull_requests(commit_hash)

        if prs:
            for pr_item in prs['items']:
                html_url = pr_item['html_url']
                if html_url and repo in html_url:
                    return html_url

        return None

    def get_pr_url_from_commit_url(self, url):
        """Get PR URL from commit URL"""
        repo, commit_hash = self._extract_repo_and_commit(url)
        if not repo or not commit_hash:
            return None

        return self._get_pr_url_from_commit(repo, commit_hash)

    def get_pr_url_from_compare_url(self, url):
        """Get PR URL from compare URL"""
        repo, commit_hash = self._extract_repo_and_commit(url)
        if not repo or not commit_hash:
            return None

        return self._get_pr_url_from_commit(repo, commit_hash)

