public static class EasingFunctions


{

    /// <summary>

    /// Calculates the power ease in function.

    /// </summary>

    /// <param name="t">The current time value, usually ranging from 0 to 1.</param>

    /// <param name="n">The power value.</param>

    /// <returns>The ease in value for the current time at the power n.</returns>

    public static double PowerEaseInOut(double t, double n)


    {

        return t < 0.5 ? Math.Pow(t, n) * (2.0 / n) : 1 - Math.Pow((1.0 - t), n) * (2.0 / n);

    }


    /// <summary>

    /// Calculates the power ease out function.

    /// </summary>

    /// <param name="t">The current time value, usually ranging from 0 to 1.</param>

    /// <param name="n">The power value.</param>

    /// <returns>The ease out value for the current time at the power n.</returns>

    public static double PowerEaseOut(double t, double n)


    {

        return 1 - Math.Pow(1.0 - t, n);

    }


    /// <summary>

    /// Calculates the power ease in function.

    /// </summary>

    /// <param name="t">The current time value, usually ranging from 0 to 1.</param>

    /// <param name="n">The power value.</param>

    /// <returns>The ease in value for the current time at the power n.</returns>

    public static double PowerEaseIn(double t, double n)


    {

        return Math.Pow(t, n);

    }

