/**
 * @param {string} S
 * @return {string[]}
 */
let permute = function(S) {
    // Remove the enclosing curly braces if they exist
    S = S.replace(/^\{/, '').replace(/\}$/, '');

    // Split the string by commas and curly braces, then filter out any empty strings
    let arr = S.split(/[{}]/).map(s => s.split(',')).filter(a => a.length);

    // Sort each sub-array of characters
    arr = arr.map(val => val.sort());

    let res = [];

    function getPermute(index, temp) {
        if (temp.length === arr.length) {
            res.push(temp.join(''));
            return;
        }

        for (let e of arr[index]) {
            temp.push(e);
            getPermute(index + 1, temp);
            temp.pop();
        }
    }

    getPermute(0, []);

    return res;
};

