#include <stdint.h>

typedef uint32_t fifo_ptr_t;  // Assuming fifo_ptr_t is some unsigned integer type

void increment_fifo_ptr(fifo_ptr_t *ptr, uint32_t increment, uint32_t fifo_len) {
    // Calculate the mask for the phase bit (assuming phase bit is the most significant bit)
    uint32_t phase_mask = 1 << (sizeof(fifo_ptr_t) * 8 - 1);

    // Extract the phase bit and the actual pointer value
    uint32_t phase_bit = *ptr & phase_mask;
    uint32_t ptr_value = *ptr & ~phase_mask;

    // Increment the pointer value
    ptr_value += increment;

    // Check for overflow and flip the phase bit if necessary
    if (ptr_value >= fifo_len) {
        ptr_value %= fifo_len;
        phase_bit ^= phase_mask;  // Flip the phase bit
    }

    // Combine the phase bit and the pointer value back together
    *ptr = phase_bit | ptr_value;
}

