        if (referenceIndex > -1) {
            int nextIndex = Arrays.asList(parts).indexOf(referenceText, referenceIndex + 1);
            if (nextIndex == -1) {
                System.out.println("Section after reference not found.");
            } else {
                System.out.println(String.join("\n", parts, referenceIndex, nextIndex).substring(referenceIndex + referenceText.length() + 2));
