#include "mp_pid.h"

template<typename Type>
void ControlHandler::integrateError() {
    this->integralError += this->error * this->step;
}

template<typename Type>
void ControlHandler::differentiateError() {
    this->derivativeError = (this->error - this->pastError) / this->step;
    this->pastError = this->error;
}

template<typename Type>
Type ControlHandler::computePID(Type reference, Type signalInput) {
    this->error = reference - signalInput;

    this->differentiateError();
    this->integrateError();

    LinAlg::Matrix state(3, 1);
    state(0, 0) = this->integralError;
    state(1, 0) = this->error;
    state(2, 0) = this->derivativeError;

    if (this->isInside(state)) {
        auto& params = this->controllerParameters[this->inWitchRegion];
        this->ki = params(0, 0);
        this->kp = params(0, 1);
        this->kd = params(0, 2);
        this->bias = params(0, 3);

        this->PIDout = this->kp * this->error + this->ki * this->integralError + this->kd * this->derivativeError + this->bias;
    } else {
        std::cout << "Valor enviado nao pertence ao conjunto de restricoes!" << std::endl;
    }

    return this->PIDout;
}

