def find_missing_number(n: int, numbers: list[int]) -> int:
    """Finds the missing number in the range [1, n+1] given a list of numbers."""
    num_set = set(range(1, n + 2))
    for num in numbers:
        if num in num_set:
            num_set.remove(num)
    return min(num_set)

