module.exports = function(binary, args) {
    const directory = findup.sync(
        path.join('node_modules', '.bin', binary),
        { cwd: __dirname },
    );

    if (!directory) {
        console.error(`Failed to find any binary named "${binary}".`);
        return;
    }

    const binaryPath = path.join(directory, '..', binary);

    execFile(binaryPath, args, (error, stdout, stderr) => {
        if (error) {
            console.error(`Error executing ${binary}:`, error);
            console.error(stderr);
            return;
        }

        console.log(stdout);
