def calculate_sum(Mid, N):
    total_sum = 0
    count = 0
    for j in range(30, -1, -1):
        if Mid & (1 << j):
            total_sum += (N - 1) * (1 << j)
            count = min(count + 1, N - 1)
        else:
            total_sum += count * (1 << j)
    return total_sum

def find_min_Y(N, S):
    X, Y = 0, S + 1
    while X + 1 < Y:
        Mid = (X + Y) >> 1
        if calculate_sum(Mid, N) >= S:
            Y = Mid
        else:
            X = Mid
    return Y

