import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(new java.io.BufferedOutputStream(System.out));
        FastReader sc = new FastReader();

        int testCases = sc.nextInt();
        for (int t = 1; t <= testCases; t++) {
            solve(sc, out);
        }
        out.close();
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int n = sc.nextInt();
        long aliceWhite = 1, aliceBlack = 0, bobWhite = 0, bobBlack = 0;
        long remaining = n - 1;
        boolean isAliceTurn = true;
        boolean isBlackTurn = true;

        for (int i = 2; remaining > 0; i++) {
            long give = Math.min(remaining, i);
            long white = give / 2;
            long black = (give + 1) / 2;

            if (isBlackTurn) {
                aliceWhite += isAliceTurn ? white : 0;
                aliceBlack += isAliceTurn ? black : 0;
                bobWhite += isAliceTurn ? 0 : white;
                bobBlack += isAliceTurn ? 0 : black;
            } else {
                aliceWhite += isAliceTurn ? 0 : black;
                aliceBlack += isAliceTurn ? 0 : white;
                bobWhite += isAliceTurn ? black : 0;
                bobBlack += isAliceTurn ? white : 0;
            }

            remaining -= give;
            isBlackTurn = !isBlackTurn;
            if (i % 2 == 0) {
                isAliceTurn = !isAliceTurn;
            }
        }

        out.println(aliceWhite + " " + aliceBlack + " " + bobWhite + " " + bobBlack);
    }

    public static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

