class Solution {
    public String minWindow(String S, String T) {
        int m = S.length();
        int n = T.length();

        // Arrays to keep track of the current and previous positions
        int[] current = new int[n];
        int[] prev = new int[n];

        // Initialize the previous array with -1
        Arrays.fill(prev, -1);

        int minLen = Integer.MAX_VALUE;
        int minStart = -1;

        for (int i = 0; i < m; ++i) {
            char ch = S.charAt(i);

            // Update the positions array
            if (ch == T.charAt(0)) {
                prev[0] = i;
            }

            for (int j = 1; j < n; ++j) {
                if (ch == T.charAt(j)) {
                    prev[j] = current[j - 1];
                }
            }

            // Update the current array with the values from the previous array
            for (int j = 0; j < n; ++j) {
                current[j] = prev[j];
            }

            // Check if the current character is the last character of T
            if (ch == T.charAt(n - 1) && prev[n - 1] != -1) {
                int windowStart = prev[n - 1];
                int windowLen = i - windowStart + 1;

                if (windowLen < minLen) {
                    minLen = windowLen;
                    minStart = windowStart;
                }
            }
        }

        // Return the minimum window substring
        if (minStart == -1) return "";
        return S.substring(minStart, minStart + minLen);
    }
}

