func ReturnBuffer(result *Buffer, ctx context.Context) int {
	// Error Handling
	if result == nil {
		return 1
	}

	// Get the pool instance for Buffer
	bufPool, err := shared.GetPool(ctx)
	if err != nil {
		return 1
	}

	// Buffer should not be added to the pool if it was already full. (validation error)
	if err := bufPool.Add(result); err != nil {
		// Handling error and returning an appropriate error code to the caller
		if bufPool.IsFull() && err == pool.ErrBufferAlreadyFull {
			return 1
		}
		fmt.Println("Error adding buffer to pool:", err)
		return 1
	}

	return 0
}

