#define int long long
#define lowbit(x) ((x) & (-x))

const int mod = 998244353;
const int N = 20; // max number of elements in the bitset

int a[26]; // frequency of each character
int dp[(1 << N) + 1]; // dp array
int siz[(1 << N) + 1]; // size array
int firstp[(1 << N) + 1]; // first position array

void input(int n) {
    for (int i = 1; i <= n; i++) {
        std::string s;
        std::cin >> s;
        for (int j = 0; j < 26; j++) {
            a[j] = 0;
        }
        for (int j = 0; j < s.size(); j++) {
            a[s[j] - 'a']++;
        }
    }
}

void init() {
    std::memset(dp, 0, sizeof(dp));
    for (int i = 1; i < (1 << N); i++) {
        dp[i] = 1;
        firstp[i] = __builtin_ctz(i); // find the first position of 1 in i
    }
}

void solve(int n) {
    init();
    for (int j = 0; j < 26; j++) {
        std::memset(siz, 0, sizeof(siz));
        siz[0] = 114514; // arbitrary value, will be overwritten
        for (int i = 1; i < (1 << n); i++) {
            siz[i] = std::min(a[j], siz[i ^ lowbit(i)]);
            dp[i] = (dp[i] * siz[i]) % mod;
        }
    }
    for (int i = 1; i < (1 << n); i++) {
        if (__builtin_popcount(i) % 2 == 0) {
            dp[i] = mod - dp[i];
        }
    }
    for (int j = 0; j < n; j++) {
        for (int i = 1; i < (1 << n); i++) {
            if (!((1 << j) & i)) {
                dp[i | (1 << j)] = (dp[i | (1 << j)] + dp[i]) % mod;
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < (1 << n); i++) {
        int k = __builtin_popcount(i);
        int t = i, tot = 0;
        for (int j = 1; j <= n; j++) {
            if ((t % 2) == 1) {
                tot += j;
            }
            t /= 2;
        }
        ans ^= (dp[i] * k * tot);
    }
    std::cout << ans << std::endl;
}

int main() {
    int n;
    std::cin >> n;
    input(n);
    solve(n);
    return 0;
}

