type CallParams struct {
	timezone      int            `json:"timezone"`
	startTime    string          `json:"startTime"`
	endTime      string          `json:"endTime"`
	metric       string          `json:"metric"`
	variable     string          `json:"variable"`
}

func validateParams(callParams *CallParams) (err error) {
	if callParams == nil {
		return fmt.Errorf("Invalid request, missing required parameters")
	}

	// validate the 'timezone' field here
	if callParams.timezone <= 0 {
		return fmt.Errorf("Timezone must be positive, locally absolute and convertable into date format")
	}

	// validate the 'startTime' field here
	if callParams.startTime == "" {
		return fmt.Errorf("startTime is required")
	}

	// validate the 'endTime' field here
	if callParams.endTime == "" {
		return fmt.Errorf("endTime is required")
	}

	// validate the 'metric' field here
	if callParams.metric == "" {
		return fmt.Errorf("metric is required")
	}

	// validate the 'variable' field here
	if callParams.variable == "" {
		return fmt.Errorf("variable is required")
	}

	return nil
}

func extractCallParams(req *http.Request) (*CallParams, error) {
	var callParams CallParams
	err := json.NewDecoder(req.Body).Decode(&callParams)
	if err != nil {
		return nil, fmt.Errorf("failed to decode request body, %s", err)
	}

	if err := validateParams(&callParams); err != nil {
		return nil, err
	}

	return &callParams, nil
}

