using json = nlohmann::json;

class Structure {
public:
    std::string name;
    std::map<std::string, std::unique_ptr<Structure>> attributes;

    Structure(const std::string& name) : name(name) {}

    void addAttribute(const std::string& attrName, std::unique_ptr<Structure> attr) {
        attributes[attrName] = std::move(attr);
    }

    void modifyAttribute(const std::string& attrName, std::unique_ptr<Structure> attr) {
        if (attributes.find(attrName) != attributes.end()) {
            attributes[attrName] = std::move(attr);
        }
    }
};

Structure* createStructureFromJson(const json& json, Structure* base = nullptr) {
    if (json["kind"] != "struct") {
        return nullptr;
    }

    std::string name = json["name"];
    std::unique_ptr<Structure> newStruct = std::make_unique<Structure>(name);

    for (const auto& [attrName, attrJson] : json["attributes"].items()) {
        if (attrJson["kind"] == "struct") {
            newStruct->addAttribute(attrName, std::move(createStructureFromJson(attrJson, nullptr)));
        }
    }

    if (base != nullptr) {
        if (base->attributes.find(name) != base->attributes.end()) {
            base->modifyAttribute(name, std::move(newStruct));
        } else {
            base->addAttribute(name, std::move(newStruct));
        }
        return nullptr;
    } else {
        return newStruct.release();
    }
}

BOOL TPortsLV::bDeletePorts(HWND hDlg, LPCTSTR pszServer)
{
    // Check if any ports are selected
    COUNT cItems = cSelectedItems();
    if (cItems == 0)
    {
        return FALSE;
    }

    // Get the first selected port name for the warning message
    TCHAR szPortName[TPortsLV::kPortNameMax];
    TStatusB bStatus = bGetSelectedPort(szPortName, COUNTOF(szPortName));
    SPLASSERT(bStatus);

    // Show the confirmation message
    INT nResult = iMessage(hDlg,
                           IDS_DELETE_PORT_TITLE,
                           cItems > 1 ? IDS_DELETE_PORTN : IDS_DELETE_PORT,
                           MB_YESNO | MB_ICONQUESTION,
                           kMsgNone,
                           NULL,
                           szPortName);

    if (nResult != IDYES)
    {
        return FALSE;
    }

    BOOL bDeleted = FALSE;
    BOOL bFailed = FALSE;

    // Try to delete all selected items
    for (INT i = 0; i < (INT)cItems; i++)
    {
        INT iItem = -1;
        bStatus = bGetSelectedPort(szPortName, COUNTOF(szPortName), &iItem);
        SPLASSERT(bStatus);
        SPLASSERT(iItem != -1);

        // Attempt to delete the selected port
        bStatus = DeletePort((LPTSTR)pszServer, hDlg, szPortName);
        if (bStatus)
        {
            // Succeeded, refresh the ports UI by deleting the port
            vDeletePortFromListView(szPortName);
            iItem--;
            bDeleted = TRUE;
        }
        else
        {
            if (GetLastError() != ERROR_CANCELLED)
            {
                bFailed = TRUE;
            }
        }
    }

    // Show an error message if any deletion failed and the action was not cancelled
    if (bFailed)
