from functools import wraps
from sqlalchemy.orm import sessionmaker
from sqlalchemy.exc import SQLAlchemyError

def db_session_decorator(engine):
    Session = sessionmaker(bind=engine)

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            session = Session()
            try:
                result = func(session, *args, **kwargs)
                if isinstance(result, tuple):
                    models, return_value = result[:2]
                    if len(result) == 3:
                        rollback_value = result[2]
                    else:
                        rollback_value = None
                else:
                    models, return_value = result, result
                    rollback_value = None

                session.add_all(models)
                session.commit()
                return return_value
            except SQLAlchemyError as e:
                session.rollback()
                if rollback_value is not None:
                    return rollback_value
                raise e
            finally:
                session.close()
        return wrapper
    return decorator

class Solution {
    public int distanceBetweenBusStops(int[] distance, int start, int destination) {
        // Normalize the start and destination to be in the range [0, distance.length)
        start = normalize(start, distance.length);
        destination = normalize(destination, distance.length);

        // Calculation based on clockwise path
        int distanceClockwise = calculateDistance(distance, start, destination);

        // Calculation based on counter-clockwise path
        int distanceCounterClockwise = calculateDistance(distance, destination, start);

        // Return the minimum of the two paths
        return Math.min(distanceClockwise, distanceCounterClockwise);
    }

    private int normalize(int index, int length) {
        return (index % length + length) % length;
    }

    private int calculateDistance(int[] distance, int from, int to) {
        int sum = 0;
        for (int i = from; i != to; i = (i + 1) % distance.length) {
            sum += distance[i];
        }
        return sum;
    }
}

