// Assume we have a Resource class
class Resource {
public:
    Resource(int id) : id_(id) {}
    int getId() const { return id_; }
private:
    int id_;
};

// Timepoint associated with a resource
using Timepoint = std::chrono::steady_clock::time_point;

// Mapping from Resource ID to Timepoint
std::unordered_map<int, Timepoint> resourceTimepoints;

// Function to setup the mapping before any lookup
void setupResourceTimepoints(const std::vector<std::shared_ptr<Resource>>& resources) {
    for (const auto& resource : resources) {
        int resourceId = resource->getId();
        // Record the current timepoint for this resource
        Timepoint tp = std::chrono::steady_clock::now();
        resourceTimepoints[resourceId] = tp;
    }
}

// Function to lookup the timepoint for a resource
Timepoint getResourceTimepoint(int resourceId) {
    auto it = resourceTimepoints.find(resourceId);
    if (it != resourceTimepoints.end()) {
        return it->second;
    }
    throw std::runtime_error("Resource not found");
}

int main() {
    // Example usage
    std::vector<std::shared_ptr<Resource>> resources = {
        std::make_shared<Resource>(1),
        std::make_shared<Resource>(2),
        std::make_shared<Resource>(3)
    };

    // Setup the mapping
    setupResourceTimepoints(resources);

    // Perform a lookup
    try {
        Timepoint tp = getResourceTimepoint(1);
        std::chrono::duration<double> dur = tp - std::chrono::steady_clock::now();
        std::cout << "Resource 1 timepoint: " << dur.count() << "s ago.\n";
    } catch (const std::runtime_error& e) {
        std::cerr << e.what() << '\n';
    }

    return 0;
}

