int Fill_Numeric_In_Array(unsigned char *buffer, int len, int *out_precision, int *out_scale, long double *out_numeric)
{
    int error = 0;
    long double decNum = 0;
    for(int i=0;i<len;i++){
        decNum += buffer[i] * pow(256,len-1-i);
    }
    *out_scale = len;
    if((int)ceil(log10(fabs(decNum))) > rsql.DATATYPE_NUMERIC_PRECISION_MAX){
        error = MDQ_ERROR_INVALID_ARGUMENT;
    }
    else
        *out_numeric = decNum;

    *out_precision = len;
    return error;
}

def solve(Y, X, N):
    points = list(zip(Y, X))
    points.sort()
    result = 0
    y_prev, x_prev = 1, 1

    for y, x in points:
        if y - x == y_prev - x_prev:
            if (y_prev + x_prev) % 2 == 0:
                result += y - y_prev
        else:
            y_diff = y - y_prev + 1
            x_diff = x - x_prev + 1
            if (y_prev + x_prev) % 2 == 0:
                result += (y_diff - x_diff) // 2
            else:
                result += (y_diff - x_diff + 1) // 2
        y_prev, x_prev = y, x

    return result

