byte lart_sysui_app_free(LARTAPP_SYSUI *app) {
    if (!app) {
        return 0;
    }

    // Send exit event to the application
    lart_send(app->efd, LART_EV_EXIT, 0, NULL, 0);

    int appn = _lart_sysui->appn;

    // Special case: When there is only one application
    if (appn == 1) {
        if (_lart_sysui->apps[0] == app) {
            _lart_sysui->appn = 0;
            free(_lart_sysui->apps);
            _lart_sysui->apps = NULL;
        }
        return 1;
    }

    // General case: Remove the application from the list
    LARTAPP_SYSUI **newapps = calloc(appn - 1, sizeof(LARTAPP_SYSUI *));
    if (!newapps) {
        return 0;  // Handle allocation failure
    }

    int j = 0;
    for (int i = 0; i < appn; ++i) {
        if (_lart_sysui->apps[i] != app) {
            newapps[j++] = _lart_sysui->apps[i];
        }
    }
    _lart_sysui->appn--;
    free(_lart_sysui->apps);
    _lart_sysui->apps = newapps;

    // Sleep for a short duration
    usleep(200000);

    // Cleanup file descriptors and named pipes
    char stmp[256];
    int appid = app->aid;

    close_file_and_unlink(stmp, sizeof(stmp), app, LART_NAMED_PIPE_APP_WRITE, appid, &app->wfd);
    close_file_and_unlink(stmp, sizeof(stmp), app, LART_NAMED_PIPE_APP_READ, appid, &app->rfd);
    close_file_and_unlink(stmp, sizeof(stmp), app, LART_NAMED_PIPE_APP_EVENT, appid, &app->efd);

    // Cleanup resources
    if (app->csb) {
        libaroma_canvas_delete(app->csb);
        app->csb = NULL;
    }
    if (app->cfb) {
        libaroma_canvas_delete(app->cfb);
        app->cfb = NULL;
    }

    _lart_sysui_killpid(app->pid);

    return 1;
}

void close_file_and_unlink(char *buf, size_t buflen, LARTAPP_SYSUI *app, const char *pipe_name_format, int appid, int *fd) {
    if (*fd > 0) {
        close(*fd);
        *fd = -1;
        snprintf(buf, buflen, pipe_name_format, appid);
        unlink(buf);
    }
}

