public class JsonExtractor {

    // Utf-8 character encoding
    public static final String UTF_8 = "UTF-8";

    /**
     * Safely extracts a nested JSON value by providing the JSON text and the path to the desired value. 
     * Handles potential exceptions by catching IOException and printing the stack trace.
     * 
     * Example usage:
     * String json ejemplo suponiendo que estaba como {"name": "John", "age": 30}
     * String path = "name";
     * JsonNode extractedValue = extractJsonValue(jsonExample, path);
     * System.out.println(extractedValue.asText());  // Output: John
     * 
     * @param jsonText           The JSON text from which to extract the value.
     * @param path              The path to the specific value within the JSON.
     * @return                  The extracted JSON node or null if an error occurred.
     */
    public static JsonNode extractJsonValue(String jsonText, String path) {
        ObjectMapper objectMapper = new ObjectMapper();
        try {
            JsonNode dataNode = objectMapper.readTree(jsonText);
            JsonNode resultNode = objectMapper.path(path).resolve(dataNode);
            return resultNode;
        } catch (IOException e) {
            System.err.println("Error extracting JSON value: " + e.getMessage());
            e.printStackTrace();
        }
        return null;
    }

    public static void main(String[] args) {
        String jsonExample = "{\"name\": \"John\", \"age\": 30}";
        String path = "name";
        JsonNode extractedValue = extractJsonValue(jsonExample, path);
        System.out.println(extractedValue.asText());  // Output: John
    }
}

