import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> goodSubsetofBinaryMatrix(int[][] grid) {
        List<Integer> [] list = new List[32];

        List<Integer> result = new ArrayList<>();

        int val, opp;

        // Initialize the list array with empty lists
        for (int i = 0; i < list.length; ++i) {
            list[i] = new ArrayList<>();
        }

        // Populate the list with row indices based on their binary value
        for (int i = 0; i < grid.length; ++i) {
            val = 0;
            for (int j = 0; j < grid[0].length; ++j) {
                val = (val << 1) | grid[i][j];
            }
            list[val].add(i);
        }

        // Check for a single row that is all zeros
        if (!list[0].isEmpty()) {
            result.add(list[0].get(0));
            return result;
        }

        // Check for pairs of rows whose bitwise AND is zero
        for (int i = 1; i < list.length; ++i) {
            if (list[i].isEmpty()) continue;
            for (int j = i; j < list.length; ++j) {
                if (list[j].isEmpty()) continue;
                if ((i & j) == 0) {
                    result.add(list[i].get(0));
                    result.add(list[j].get(0));
                    return result;
                }
            }
        }

        // If no such subset is found, return an empty list
        return result;
    }
}

