var isAlienSorted = function(words, order) {
    var o = {};
    for (var i = 0; i < order.length; i++) {
        o[order[i]] = i;
    }

    for (var i = 0; i < words.length - 1; i++) {
        if (!compareWords(words[i], words[i + 1], o)) {
            return false;
        }
    }

    return true;

    function compareWords(word1, word2, orderMap) {
        var char1 = word1.charAt(0);
        var char2 = word2.charAt(0);
        while (char1.length > 0 && char2.length > 0) {
            var index1 = orderMap[char1];
            var index2 = orderMap[char2];
            if (index1 < index2) {
                return true;
            } else if (index1 > index2) {
                return false;
            }
            char1 = char1.substring(1);
            char2 = char2.substring(1);
        }
        if (char1.length > 0) {
            return true;
        } else if (char2.length > 0) {
            return false;
        } else {
            return true; // both words are empty, they are equal
        }
    }
};

