def getmultiply(self, nums):
    res = {}
    for x in range(len(nums)):
        for y in range(x + 1, len(nums)):
            product = nums[x] * nums[y]
            if product not in res:
                res[product] = 1
            else:
                res[product] += 1
    return res

def getcommon(self, nums1, nums2):
    m1 = self.getmultiply(nums1)
    m2 = self.getmultiply(nums2)
    res = 0
    for x in nums1:
        if x * x in m2:
            res = res + len(m2[x * x])
    for y in nums2:
        if y * y in m1:
            res = res + len(m1[y * y])
    return res

