def count_divisors(n):
    cnt = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            if i * i == n:
                cnt += 1
            else:
                cnt += 2
    return cnt

def is_prime(n):
    if n <= 1:
        return False
    if n <= 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

