type State int

const (
	StateExclusive State = iota
	StateInclusive
)

func StateCondition(q squirrel.SelectBuilder, field string, fs State) squirrel.SelectBuilder {
	switch fs {
	case StateExclusive:
		// only non-null values
		return q.Where(squirrel.NotEq{field: nil})

