public class WordCollapser {
    public String collapse(String sentence) {
        String[] words = sentence.split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0 && words[i].equals(words[i - 1])) {
                continue;
            }
            sb.append(words[i]);
            sb.append(" ");
        }
        return sb.toString().trim();
    }
}

public class ComplexNumber {
    private double real;
    private double imaginary;

    //Constructor with parameters
    public ComplexNumber(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    //Default Constructor
    public ComplexNumber() {
        this(0,0);
    }

    // Method for adding two ComplexNumbers
    public ComplexNumber plus(ComplexNumber secondNumber){
        double realPart = this.real + secondNumber.real;
        double imaginaryPart = this.imaginary + secondNumber.imaginary;
        return new ComplexNumber(realPart, imaginaryPart);
    }

    // Method for subtracting two ComplexNumbers
    public ComplexNumber minus(ComplexNumber secondNumber){
        double realPart = this.real - secondNumber.real;
        double imaginaryPart = this.imaginary - secondNumber.imaginary;
        return new ComplexNumber(realPart, imaginaryPart);
    }
}

