import math

def evaluate_bleu(k, translations, references):
	# You may need to add extra logic to handle cases when translations or references are None
	if translations is None or references is None:
		return None

	trans = []
	for t in translations:
		t = t.split()
		trans.append(t[:k])

	refs = []
	for r in references:
		r = r.split()
		refs.append(r[:k])

	n = len(trans)
	m = len(refs[0])

	c = 0
	for i in range(n):
		count = 0
		for j in range(k):
			if trans[i][j] in refs[i]:
				count += 1
		c += math.comb(m, count)
	return c / math.comb(m+k-1, k)

def evaluate_sentence_bleu(k, translations, references):
	if translations is None or references is None:
		return None

	translation = translations[0].split()
	references = [r.split() for r in references]
	reference = [item for sublist in references for item in sublist]
	count = sum(1 for item in translation[:k] if item in reference)
	return math.comb(len(reference), count) / math.comb(len(reference) + k - 1, k)

