public static void AddRange<TSource, TTarget>(this List<TTarget> collection, IEnumerable<TSource> sourceValues) where TSource : TTarget {
    if (collection == null) {
        throw new ArgumentNullException(nameof(collection));
    }

    if (sourceValues == null) {
        throw new ArgumentNullException(nameof(sourceValues));
    }

    var startingCount = collection.Count;

    foreach (var value in sourceValues) {
        collection.Add(value);
    }

    if (collection is INotifyCollectionChanged notifyCollectionChanged && startingCount != collection.Count && sourceValues.Any()) {
        notifyCollectionChanged.CollectionChanged?.Invoke(collection, new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, collection.Skip(startingCount).Take(collection.Count - startingCount).ToList()));
    }
}

public String buildPostParamsString(Map<String, String> params) {
    StringBuilder paramsString = new StringBuilder();
    for (Map.Entry<String, String> entry : params.entrySet()) {
        if (paramsString.length() > 0) {
            paramsString.append("&");
        }
        try {
            paramsString.append(URLEncoder.encode(entry.getKey(), "UTF-8"))
                        .append("=")
                        .append(URLEncoder.encode(entry.getValue(), "UTF-8"));
        } catch (UnsupportedEncodingException e) {
            // UTF-8 is guaranteed to be supported, so this should never happen
            throw new RuntimeException("UTF-8 encoding not supported", e);
        }
    }
    return paramsString.toString();
}

