public static Action returnAction(ActionContext context, ActionHint hint, Supplier<String> infoSupplier) throws AssertionError {

    // Get the actions from the context
    Set<Action> actions = context.getActions();

    // Iterate through the actions to find the matching one
    for (Action action : actions) {
        if (action.equals(hint)) {
            // Check if an action is required
            if (action.isRequired()) {
                // If an action is required, return it
                return action;
            } else {
                // If an action is not required, check if it should be present
                if (action.shouldPresent()) {
                    // If an action should be present, throw an assertion error
                    throw new AssertionError("Action should not be present.");
                }
            }
        }
    }

    // If no action was found, return null
    if (hint.isRequired()) {
        throw new AssertionError("Action should be present.");
    }
    return null;
}

