public static MethodInfo[] GetOverriddenMethods(MethodInfo info)
{
    foreach (var baseType in info.DeclaringType.BaseTypes())
    {
        if (baseType == null) continue;
        foreach (var member in baseType.GetMethods())
        {
            if (!member.IsVirtual || member == info) continue;

            MethodInfo[] baseOverrides = GetOverriddenMethods(member);
            if (baseOverrides.Length > 0)
            {
                return baseOverrides;
            }
        }
    }

    return new MethodInfo[] { info };
}

// FindAllTabletAliasesInShard uses the replication graph to find all the
// tablet aliases in the given shard.
// It can return ErrPartialResult if some cells were not fetched,
// in which case the result only contains the cells that were fetched.
func FindAllTabletAliasesInShard(shardID uint64, service ObservableService, channel chan<- []string) {
	// Get the cells in the shard.
	cells := service.Cells.FindAllCells(shardID)
	// Create a list of tablet aliases.
	tabletAliases := make([]string, 0)
	// Iterate over the cells
	for _, cell := range cells {
		// Get the tablet aliases for the cell.
		cellData := service.Cells.GetCell(cell)
		if cellData == nil {
			continue
		}
		tabletAliases = append(tabletAliases, cellData.TabletAliases...)
	}
	// Send the tablet aliases.
	channel <- tabletAliases
}

