public static void HandleRequest(HttpContextBase filterContext) 
{
    //fetching action and controller names from filterContext
    string controllerName = filterContext.RouteData.GetRequiredString("controller");
    string actionName = filterContext.RouteData.GetRequiredString("action");

    //restoring original controller and action for execution after redirection
    ActionDescriptor actionDescriptor = filterContext.RouteData.GetRequiredTestValue("action");
    ControllerContext controllerContext = new ControllerContext(filterContext.RequestContext, new RouteData(actionDescriptor), filterContext.RouteData.Values["controller"]);

    //redirecting to the desired controller and action
    filterContext.Redirect(string.Format("/{0}/{1}",controllerName,actionName));

    //ensure the controller and action properties are set correctly after redirection
    filterContext.RouteData.Values["controller"] = controllerName;
    filterContext.RouteData.Values["action"] = actionName;

    //ensure ActionFilter attributes are included after the redirection
    foreach (ICustomFilter filter in filterContext.Filters)
    {
        filterContext.RemoveFilter(filter);
        filterContext.Filters.Add(filter);
    }

    //inject actionDescriptor back
    filterContext.RouteData.Values["action"] = actionDescriptor;
}

