public class Solution {
    public int maxDistance(int[][] arrays) {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        int min2 = Integer.MAX_VALUE;
        int max2 = Integer.MIN_VALUE;
        int minIndex = -1;
        int maxIndex = -1;

        for (int i = 0; i < arrays.length; i++) {
            int currentMin = arrays[i][0];
            int currentMax = arrays[i][arrays[i].length - 1];

            if (currentMin < min) {
                min2 = min;
                min = currentMin;
                minIndex = i;
            } else if (currentMin < min2) {
                min2 = currentMin;
            }

            if (currentMax > max) {
                max2 = max;
                max = currentMax;
                maxIndex = i;
            } else if (currentMax > max2) {
                max2 = currentMax;
            }
        }

        // If the min and max are from different arrays, return the difference
        if (minIndex != maxIndex) {
            return max - min;
        }

        // Otherwise, return the maximum of the two possible distances
        return Math.max(max - min2, max2 - min);
    }
}

