public int appendDecodedSequence(StringBuilder sb, int c) throws JsonPointerException {

        switch (c) {
            case NUMBER_SIGN:
                sb.append('-');
                return 1;
            case DIGIT_0:
            case DIGIT_1:
            case DIGIT_2:
            case DIGIT_3:
            case DIGIT_4:
            case DIGIT_5:
            case DIGIT_6:
            case DIGIT_7:
            case DIGIT_8:
            case DIGIT_9:
                int result = c - DIGIT_0;
                sb.append((char) (result + '0'));
                return 1;
            case LOWER_ASCII_letters:
                sb.append((char) (c - LOWER_ASCII_letters + 'A')); // 'a' - 'A' = 20
                return 1;
            case UPPER_ASCII_letters:
                sb.append((char) (c - UPPER_ASCII_letters + 'a')); // 'A' - 'a' = 22
                return 1;
            case BACKSLASH_Quad_BYTE:
                int count = 0;
                for (int i = 0; i < 4; i++) {
                    c = Character.getNumericValue(readChar());
                    if (c >= 0 && c <= 7) {
                        sb.append((char) ((c << (count++)) & 0xFF));
                    } else {
                        throw new JsonPointerException("Illegal escaped character");
                    }
                }
                return 1;
            case END_UNICODE_CHAR:
                int u = readChar();
                if (Character.isHighSurrogate((char) u)) {
                    if (readChar() != LOWER_ASCII_letters + 'L') {
                        throw new JsonPointerException("Illegal escaped character");
                    }
                    u = (u << 10) + readChar() - LOWER_ASCII_letters + 0x10000;
                } else {
                    if (u >= LOWER_ASCII_letters && u <= UPPER_ASCII_letters) {
                        u -= LOWER_ASCII_letters - 'a' + 55; // 'A' - 'a' = 22
                    } else if (u >= DIGIT_0 && u <= DIGIT_9) {
                        u -= DIGIT_0 + 48; // '0' - '0' = 48
                    } else {
                        throw new JsonPointerException("Illegal escaped character");
                    }
                }
                sb.append((char) u);
                return 1;
            default:
                throw new JsonPointerException("Illegal escaped character");

        }

    }

