function positionScrollerAndSliders(resizeSlides) {
    // get scrollbar width
    var width = window.innerWidth - document.documentElement.clientWidth;

    // Apply transformations for desktop
    var desktop = window.matchMedia( "only screen and (min-width: 768px)" ).matches;
    if(desktop){
        // adjust slide contents if resizeSlides is set to true
        if(resizeSlides) {
            var slides = document.querySelectorAll(".slide");
            slides.forEach(function(slide) {
                slide.style.width = (window.innerWidth - width - 10) + "px"; // minus 10px for the scrollbar
                slide.style.marginLeft = -(window.innerWidth - width - 10)/2 + "px";
            })
        }

        // apply styling rules for desktop view
        document.documentElement.style.cssText = "";
        // load desktop styles
        document.documentElement.style.cssText = document.getElementById("desktopCSS").innerHTML;
        // set up window resize to recalculate on window resize
        window.addEventListener('resize', function(){
            positionScrollerAndSliders(resizeSlides);
        });
    }

    // check viewport for mobile
    var mobile = window.matchMedia("only screen and (max-width: 767px)").matches;
    if(!desktop && mobile){
        // load mobile styles
        document.documentElement.style.cssText = document.getElementById("mobileCSS").innerHTML;
        // remove desktop CSS in desktop view
        document.documentElement.style.cssText = document.documentElement.style.cssText.replace(document.getElementById("desktopCSS").innerHTML, "");
    }
}

