public void cleanUpAgent() {
    for (Component component : agent.getComponents()) {
        if (!containsRemoteCandidates(component)) {
            agent.removeComponent(component);
            component.free();
        }
    }

    for (Stream stream : agent.getStreams()) {
        if (!containsRemoteCandidates(stream)) {
            agent.removeStream(stream);
            stream.free();
        }
    }
}

private boolean containsRemoteCandidates(Component component) {
    for (Candidate<?> candidate : component.getCandidates()) {
        if (candidate.getType() == CandidateType.RELAYED || candidate.getType() == CandidateType.HOST) {
            return true;
        }
    }
    return false;
}

private boolean containsRemoteCandidates(Stream stream) {
    for (Component component : stream.getComponents()) {
        if (containsRemoteCandidates(component)) {
            return true;
        }
    }
    return false;
}

