    [TestClass]
    public class DefaultExecuteStrategyTests
    {
        private static void ExecuteTestponce(WebExceptionStatus webExceptionStatus, HttpStatusCode httpStatusCode, int expectedAttempts, int delay = 0)
        {
            using (ShimsContext.Create())
            {
                var lastModified = DateTime.Now;

                var shimHttpWebResponse = new ShimHttpWebResponse
                {
                    StatusCodeGet = () => httpStatusCode,
                    StatusDescriptionGet = () => "Entity not found.",
                    SupportsHeadersGet = () => true,
                    LastModifiedGet = () => lastModified,
                    HeadersGet = () => new WebHeaderCollection { { "Server", "Test" } }
                };

                var targetException = new WebException("Failed request", null, webExceptionStatus, shimHttpWebResponse);

                var strategy = new DefaultExecuteStrategy<string, string>(new[] { TimeSpan.FromMilliseconds(100), TimeSpan.FromMilliseconds(200) });

                Exception exception = null;
                var attempts = 0;

                var started = DateTime.UtcNow;

                try
                {
                    strategy.Execute("Hello World!", x => { ++attempts; throw targetException; });
                }
                catch (WebException e)
                {
                    exception = e;
                }

                var duration = DateTime.UtcNow - started;

                Assert.IsNotNull(exception);

                Assert.IsInstanceOfType(exception, typeof(WebException));

                Assert.AreEqual(expectedAttempts, attempts);

                var lowerBound = expectedAttempts == 1 ? TimeSpan.FromMilliseconds(delay) : TimeSpan.FromMilliseconds(300);
                var upperBound = TimeSpan.FromSeconds(1);

                Assert.IsTrue(duration > lowerBound && duration < upperBound);
            }
        }

        [TestMethod]
        public void WhenExecutingActionThrowsWebExceptionWith404()
        {
            ExecuteTestOnce(WebExceptionStatus.ProtocolError, HttpStatusCode.NotFound, 1, 0);
        }

        [TestMethod]
        public void WhenExecutingActionThrowsWebExceptionWithConnectFailure()
        {
            ExecuteTestOnce(WebExceptionStatus.ConnectFailure, HttpStatusCode.Conflict, 3);
        }

        [TestMethod]
        public void WhenExecutingActionThrowsWebExceptionWithRequestTimeout()
        {
            ExecuteTestOnce(WebExceptionStatus.ProtocolError, HttpStatusCode.RequestTimeout, 3);
        }

        [TestMethod]
        public void WhenExecutingActionThrowsWebExceptionWithGatewayTimeout()
        {
            ExecuteTestOnce(WebExceptionStatus.ProtocolError, HttpStatusCode.GatewayTimeout, 3);
        }
    }
