function synchronizeControllers() {
    const currentControllers = new Set([...document.querySelectorAll('[data-controller]')].map(el => el.dataset.controller));
    const existingControllers = new Set(this.controllers.map(controller => controller.element.dataset.controller));

    // Process new controllers
    currentControllers.forEach(controllerName => {
        if (!existingControllers.has(controllerName)) {
            const newControllers = document.querySelectorAll(`[data-controller="${controllerName}"]`);
            newControllers.forEach(element => {
                const newController = new Controller(element);
                this.controllers.push(newController);
            });
        }
    });

    // Destroy controllers whose elements are no longer on the DOM
    this.controllers = this.controllers.filter(controller => {
        if (!document.contains(controller.element)) {
            controller.destroy();
            return false;
        }
        return true;
    });

    // Sync other controllers
    this.controllers.forEach(controller => {
        controller.sync();
    });
}

