std::vector<std::vector<Interval>> splitIntervals(std::vector<Interval> patterns) {
    std::vector<std::vector<Interval>> result;
    std::sort(patterns.begin(), patterns.end(), [](const Interval& a, const Interval& b) {
        return a.start < b.start;
    });
    for (const Interval& pattern : patterns) {
        bool merged = false;
        for (std::vector<Interval>& group : result) {
            if (group.back().end < pattern.start) {
                group.push_back(pattern);
                merged = true;
                break;
            }
        }
        if (!merged) {
            result.push_back({pattern});
        }
    }
    return result;
}

