import java.util.List;

/**
 * This class is responsible for approving or rejecting entities in the Infospace.
 */
public class EntityApprover {

    private List<String> approvedEntities;

    public EntityApprover() {
        this.approvedEntities = new ArrayList<>();
    }

    /**
     * Approves the given entity.
     * 
     * @param entity the entity to be approved
     */
    public void approveEntity(String entity) {
        if (!approvedEntities.contains(entity)) {
            approvedEntities.add(entity);
        }
    }

    /**
     * Rejects the given entity.
     * 
     * @param entity the entity to be rejected
     */
    public void rejectEntity(String entity) {
        approvedEntities.remove(entity);
    }

    /**
     * Checks if the given entity is approved.
     * 
     * @param entity the entity to be checked
     * @return true if the entity is approved, false otherwise
     */
    public boolean isEntityApproved(String entity) {
        return approvedEntities.contains(entity);
    }

    public static void main(String[] args) {
        EntityApprover approver = new EntityApprover();
        approver.approveEntity("Entity1");
        approver.approveEntity("Entity2");
        System.out.println(approver.isEntityApproved("Entity1")); // prints: true
        System.out.println(approver.isEntityApproved("Entity3")); // prints: false
    }
}

