import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;

public class DataEncoder {

    public static ByteBuffer encodeArray(Class<?> vtype, Object[] values) {
        Charset charset = StandardCharsets.UTF_8;

        ByteBuffer bb = ByteBuffer.allocate((int) (values.length * 8));

        for (Object value : values) {
            if (vtype == byte.class) {
                bb.put(((Byte) value));
            } else if (vtype == short.class) {
                bb.putShort(((Short) value));
            } else if (vtype == int.class) {
                bb.putInt(((Integer) value));
            } else if (vtype == long.class) {
                bb.putLong(((Long) value));
            } else if (vtype == float.class) {
                bb.putFloat(((Float) value));
            } else if (vtype == double.class) {
                bb.putDouble(((Double) value));
            } else if (vtype == char.class) {
                bb.putChar(((Character) value));
            } else if (vtype == boolean.class) {
                bb.putBoolean(((Boolean) value));
            } else if (vtype == String.class) {
                byte[] strBytes = ((String) value).getBytes(charset);
                bb.putInt(strBytes.length);
                bb.put(strBytes);
            }
        }

        return bb;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class LineReader {
    private BufferedReader reader;
    private String separator;
    private char commentChar;

    public LineReader(String filePath, String separator, char commentChar) throws IOException {
        this.reader = new BufferedReader(new java.io.FileReader(filePath));
        this.separator = separator;
        this.commentChar = commentChar;
    }

    public List<String> readLine() throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IOException("End of file reached or file was closed.");
        }

        // Remove any content after the comment character
        int commentIndex = line.indexOf(commentChar);
        if (commentIndex != -1) {
            line = line.substring(0, commentIndex);
        }

        // Split the line according to the separator
        String[] tokens = line.split(separator);
        List<String> tokenList = new ArrayList<>();
        for (String token : tokens) {
            tokenList.add(token.trim());
        }

        return tokenList;
    }

    public void close() throws IOException {
        reader.close();
    }
}

