/// <summary>
/// Represents base properties and behavior for executing queries. This class provides the foundational setup 
/// for any query, including the execution pattern and callback functionality.
/// </summary>
public abstract class BasicQuery
{
    /// <summary>
    /// A delegate that represents a method that will receive notification when a query has completed execution.
    /// This can be utilized by derived classes to hook in additional synchronous query logic or callback
    /// after a query completes.
    /// </summary>
    public delegate void QueryCompleteHandler();

    /// <summary>
    /// Constructs a basic query instance with no additional setup required.
    /// </summary>
    public BasicQuery()
    {
    }

    /// <summary>
    /// Abstract method that must be implemented by derived classes to initiate the query's execution. This 
    /// method represents the core logic that will be carried out by a child class. It should be designed with the
    /// understanding that it must complete before the `OnQueryCompleted` method is called on the same thread.
    /// </summary>
    /// <exception cref="NotImplementedException">Thrown by derived classes to indicate that execution functionality 
    /// is not yet implemented and must be provided.</exception>
    public abstract void Execute();

    /// <summary>
    /// Defines the pattern for callback invocation after the execution of a query.
    /// Derived classes will use this to register additional synchronous post-query operations that need to be performed.
    /// </summary>
    /// <param name="callback">The delegate representing the callback method to be executed after query completion.</param>
    public abstract void OnQueryCompleted(QueryCompleteHandler callback);
}

