import java.util.HashSet;
import java.util.Set;

class Solution {
    public int[] fairCandySwap(int[] A, int[] B) {
        int sumA = 0, sumB = 0;

        // Calculate the sum of both arrays
        for (int i : A) sumA += i;
        for (int i : B) sumB += i;

        // The target difference after the swap
        int diff = (sumA - sumB) / 2;

        // Create a set from array B
        Set<Integer> setB = new HashSet<>();
        for (int i : B) {
            setB.add(i);
        }

        // Find the fair swap
        for (int i : A) {
            if (setB.contains(i + diff)) {
                return new int[] {i, i + diff};
            }
        }

        // If no solution exists
        return new int[0];
    }
}

