const mod = 1e9 + 7

// maximumProduct returns the maximum product of an array after k operations
func maximumProduct(a []int, k int) (ans int) {
	h := &intHeap{a}
	heap.Init(h)

	for ; k > 0; k-- {
		v := heap.Pop(h).(int)
		heap.Push(h, v+1)
	}

	ans = 1
	for _, v := range h.IntSlice {
		ans = ans * v % mod
	}

	return
}

// intHeap is a min heap implementation
type intHeap struct{ sort.IntSlice }

func (h *intHeap) Less(i, j int) bool { return h.IntSlice[i] < h.IntSlice[j] }
func (h *intHeap) Push(v interface{}) { h.IntSlice = append(h.IntSlice, v.(int)) }
func (h *intHeap) Pop() interface{}   { a := h.IntSlice; v := a[len(a)-1]; h.IntSlice = a[:len(a)-1]; return v }

