import re
import toml

class ReStructuredTextFormatter:
    def __init__(self, filename, config):
        self.filename = filename
        self.config = config

    def reformat_snippets(self):
        with open(self.filename, 'r') as file:
            content = file.read()

        pattern = re.compile(r'(\.\. code-block::\s*\w+\n+\s*)(.)*(?=\n+\.\. code-block::|\Z)', re.DOTALL)
        code_blocks = pattern.finditer(content)

        formatted_content = ''
        last_end = 0

        for match in code_blocks:
            start, end = match.span()
            formatted_content += content[last_end:start]
            code_block = match.group(0)
            formatted_code_block = self._format_code_block(code_block)
            formatted_content += formatted_code_block
            last_end = end

        formatted_content += content[last_end:]

        with open(self.filename, 'w') as file:
            file.write(formatted_content)

    def _format_code_block(self, code_block):
        lines = code_block.split('\n')
        formatted_lines = []

        for line in lines:
            if line.strip().startswith('#'):
                formatted_lines.append(self._apply_snippet_format(line))
            else:
                formatted_lines.append(line)

        return '\n'.join(formatted_lines)

    def _apply_snippet_format(self, line):
        format_string = self.config.get('format', {}).get('comment', '')
        return format_string.format(comment=line.strip())

package rsa;

import java.security.PublicKey;
import org.bouncycastle.util.encoders.Hex;

public class SecureSignature {
    private static final int BYTES = 512;
    private final byte[] secsignature;

    public SecureSignature(Signature signature, PublicKey pubKey) {
        byte[] encryptedSignature = RSALibrary.encrypt(signature.getSignature(), pubKey);
        validateSignatureLength(encryptedSignature);
        this.secsignature = encryptedSignature;
    }

    public SecureSignature(byte[] secsignature) {
        validateSignatureLength(secsignature);
        this.secsignature = secsignature.clone(); // Clone to prevent external modification
    }

    private SecureSignature() {
        this.secsignature = new byte[0]; // Private constructor for safety
    }

    public byte[] getSignature() {
        return secsignature.clone(); // Clone to prevent external modification
    }

    @Override
    public String toString() {
        return Hex.toHexString(this.secsignature);
    }

    private void validateSignatureLength(byte[] signature) {
        if (signature.length > BYTES) {
            throw new IllegalArgumentException("Signature length exceeds the maximum allowed bytes: " + BYTES);
        }
    }
}

