// Dukkha runtime specific template funcs

type dukkhaNS struct {
	rc        dukkha.RenderingContext
 cacheDir  string
 workDir   string
 newValues map[string]interface{}
 lock      sync.RWMutex
}

func createDukkhaNS(rc dukkha.RenderingContext) *dukkhaNS {
	return &dukkhaNS{rc: rc, cacheDir: rc.CacheDir(), workDir: rc.WorkDir()}
}

func (ns *dukkhaNS) Set(key string, v interface{}) (interface{}, error) {
	return ns.SetValue(key, v)
}

func (ns *dukkhaNS) SetValue(key string, v interface{}) (interface{}, error) {
	ns.lock.RLock()
	defer ns.lock.RUnlock()

	if err := ns.genNewVal(key, v); err!= nil {
		return v, fmt.Errorf("generate new values for key %q: %w", key, err)
	}

	return v, ns.rc.AddValues(ns.newValues)
}

func (ns *dukkhaNS) genNewVal(key string, v interface{}) error {
	newValues := make(map[string]interface{})

	switch t := v.(type) {
	case string:
		fallthrough
	case []byte:
		v, err := fromYaml(ns.rc, string(t))
		if err!= nil {
			return err
		}
		newValues[key] = v
	case map[string]interface{}:
		for k, vv := range t {
			err := ns.genNewVal(k, vv)
			if err!= nil {
				return err
			}
		}
	case []interface{}:
		for i, v := range t {
			err := ns.genNewVal(fmt.Sprintf("%s[%d]", key, i), v)
			if err!= nil {
				return err
			}
		}
	default:
		newValues[key] = v
	}

	ns.lock.Lock()
	defer ns.lock.Unlock()
	ns.newValues = newValues

	return nil
}

func fromYaml(rc dukkha.RenderingContext, yamlDoc string) (interface{}, error) {
	var data map[string]interface{}
	err := yaml.Unmarshal([]byte(yamlDoc), &data)
	if err!= nil {
		return nil, err
	}

	var val interface{}
	switch valT := data["value"].(type) {
	case string:
		val = valT
	case []byte:
		val = valT
	case map[string]interface{}:
		val = valT
	case []interface{}:
		val = valT
	default:
		return nil, fmt.Errorf("unsupported type %T for value", valT)
	}

	return rc.Deserialize(val)
}

