import org.springframework.security.authentication.AbstractAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.GrantedAuthority;

/**
 * A user object to hold all required information for authentication and authorization.
 * This class also contains the user's authorities, enabling it to be used as an authentication token
 * in the Spring Security context.
 *
 * @author cn40580
 */
public class MyUserToken extends AbstractAuthenticationToken {

    private static final long serialVersionUID = 1L;

    private final Object principal;
    private final Object credentials;

    /**
     * Constructs a new MyUserToken with the given authorities.
     *
     * @param authorities The collection of granted authorities.
     */
    public MyUserToken(Object principal, Object credentials, Collection<? extends GrantedAuthority> authorities) {
        super(authorities);
        this.principal = principal;
        this.credentials = credentials;
        super.setAuthenticated(false);
    }

    /**
     * Constructs a new MyUserToken with the given authorities and authenticated status.
     *
     * @param principal   The principal (user) object.
     * @param credentials The credentials (password) object.
     * @param authorities The collection of granted authorities.
     * @param authenticated The authenticated status.
     */
    public MyUserToken(Object principal, Object credentials, Collection<? extends GrantedAuthority> authorities, boolean authenticated) {
        super(authorities);
        this.principal = principal;
        this.credentials = credentials;
        super.setAuthenticated(authenticated);
    }

    @Override
    public Object getCredentials() {
        return this.credentials;
    }

    @Override
    public Object getPrincipal() {
        return this.principal;
    }

    @Override
    public void setAuthenticated(boolean authenticated) {
        if (authenticated) {
            throw new IllegalArgumentException("Cannot set this token to trusted - use constructor which takes a GrantedAuthority list instead");
        }
        super.setAuthenticated(false);
    }

    @Override
    public String toString() {
        return "MyUserToken{" +
                "principal=" + principal +
                ", credentials=" + credentials +
                ", authorities=" + getAuthorities() +
                '}';
    }
}

