def inv(x, m):
    # Function to compute the modular inverse using the Extended Euclidean Algorithm
    def egcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = egcd(b % a, a)
            return (g, x - (b // a) * y, y)

    g, x, _ = egcd(x, m)
    if g != 1:
        raise Exception('Modular inverse does not exist')
    else:
        return x % m

def binomial_coefficient_mod(a, b, m):
    ans = 1
    for x in range(1, min(b, a - b) + 1):
        ans = ans * (a - x + 1) % m
        ans = ans * inv(x, m) % m
    return ans

def modPow(a, b, m):
    ans = 1
    aa = a
    while b > 0:
        if b & 1:
            ans = ans * aa % m
        b >>= 1
        aa = aa * aa % m
    return ans

# Example usage:
a, b, m = 10, 3, 13
