// removeDuplicates removes duplicates from a sorted array in-place and returns the new length.
// The function modifies the input array to contain only unique elements.
// It ensures O(1) extra memory usage.
func removeDuplicates(nums []int) int {
    if len(nums) == 0 {
        return 0
    }

    // Initialize the length of the unique elements array
    uniqueLength := 1

    // Iterate through the array starting from the second element
    for i := 1; i < len(nums); i++ {
        // If the current element is different from the previous one
        if nums[i] != nums[i-1] {
            // Place the unique element at the current uniqueLength position
            nums[uniqueLength] = nums[i]
            // Increment the uniqueLength counter
            uniqueLength++
        }
    }

    // Return the length of the unique elements array
    return uniqueLength
}

func main() {
    nums := []int{1, 1, 2, 2, 3, 4, 4, 5}
    newLength := removeDuplicates(nums)
    fmt.Println("New length:", newLength)
    fmt.Println("Modified array:", nums[:newLength])
}

public static double ComputeJulianDate(int Year, int Month, int Day, double Hour)
{
    if (Month <= 2)
    {
        Year -= 1;
        Month += 12;
    }

    int A = (int)(Year / 100);
    int B = 2 - A + (int)(A / 4);

    double JD = Math.Floor(365.25 * (Year + 4716)) + Math.Floor(30.6001 * (Month + 1)) + Day + B - 1524.5;
    JD += Hour / 24.0;

    return JD;
}

// Merge one trace into another, but only at fall-through points.
for (int i = 0; i < size; i++) {
  for (int j = i + 1; j < size; j++) {
    // Check if edges[i] and edges[j] can be merged at fall-through points
    if (uf->can_merge(i, j)) {
      // Merge i and j into k (i.e., k = i)
      int k = uf->find(i);
      // Remove all edges at fall-through points
      for (int j = 0; j < edges->size(); j++) {
        CFGEdge *edge = edges->at(j);
        if (edge->b1 == i && edge->b2 == j) {
          edge->b2 = k;
        } else if (edge->b1 == j && edge->b2 == i) {
          edge->b1 = k;
        }
      }
      // Remove all edges from i and j
      edges->remove(i);
      edges->remove(j);
      // Add all edges from k
      for (int p = 0; p < size; p++) {
        if (uf->find(p) == i) {
          CFGEdge *edge = new CFGEdge(p, k);
          edges->add(edge);
        }
      }
    }
  }
}

