class Solution {
    int m;
    int n;
    int[][] grid;
    int[][] dir = new int[][]{
        {0,1},{0,-1},{1,0},{-1,0}
    };

    public int findMaxFish(int[][] grid) {
        this.grid = grid;
        m = grid.length;
        n = grid[0].length;

        boolean[][] vis = new boolean[m][n];

        int ans = 0;

        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                if(vis[i][j])
                    continue;
                if(grid[i][j] > 0){
                    ans = Math.max(ans, dfs(i,j, vis));
                }
            }
        }
        return ans;
    }

    private int dfs(int x, int y, boolean[][] vis) {
        if (x < 0 || x >= m || y < 0 || y >= n || vis[x][y] || grid[x][y] == 0) {
            return 0;
        }

        vis[x][y] = true;
        int sum = grid[x][y];

        for (int[] d : dir) {
            int newX = x + d[0];
            int newY = y + d[1];
            sum += dfs(newX, newY, vis);
        }

        return sum;
    }
}

