int copyItemsInDirectory(const std::string& dir, HandlerFunc handler, std::vector<std::string>& list, size_t length, size_t offset_start = 0, bool one_cmd = true) {
    DIR* directory;
    struct dirent* entry;
    struct stat file_stat;
    std::string path;

    if (dir.empty()) {
        directory = opendir(".");
    } else {
        directory = opendir(dir.c_str());
    }

    if (!directory) {
        std::cerr << "Error opening directory: " << dir << std::endl;
        return 0;
    }

    size_t copied_items = 0;

    while ((entry = readdir(directory)) != nullptr) {
        if (copied_items >= length) {
            break;
        }

        if (offset_start > 0) {
            offset_start--;
            continue;
        }

        path = dir.empty() ? entry->d_name : (dir + "/" + entry->d_name);

        if (stat(path.c_str(), &file_stat) == 0) {
            if (S_ISDIR(file_stat.st_mode)) {
                continue; // Skip directories
            }
        } else {
            std::cerr << "Error getting file stats: " << path << std::endl;
            continue;
        }

        list.push_back(entry->d_name);
        if (handler) {
            handler(entry->d_name);
        }
        copied_items++;
    }

    closedir(directory);
    return copied_items;
}

