from collections import Counter

def val(c):
    if c >= '0' and c <= '9':
        return ord(c) - ord('0')
    else:
        return ord(c) - ord('A') + 10

def get_mini_base(s):
    d1 = Counter(s)
    curr = -1
    for key in d1:
        if val(key) > curr:
            curr = val(key)
    return curr + 1

def toDeci(str, base):
    llen = len(str)
    power = 1
    num = 0
    for i in range(llen - 1, -1, -1):
        if val(str[i]) >= base:
            return -1
        num += val(str[i]) * power
        power = power * base
    return num

