package com.github.eugenelessia.hashset;

public class ListNode {
    int val;
    ListNode next;

    ListNode(int x) {
        val = x;
        next = null;
    }

    /**
     * Returns the node where the cycle begins. If there is no cycle, returns null.
     */
    static class Solution {
        public ListNode detectCycle(ListNode head) {
            if (head == null || head.next == null) {
                return null;
            }

            ListNode fast = head;
            ListNode slow = head;

            while(fast != null && fast.next != null) {
                slow = slow.next;
                fast = fast.next.next;

                if (fast == slow) {
                    break;
                }
            }

            if (fast == null || fast.next == null) {
                return null;
            }

            slow = head;
            while(slow != fast) {
                slow = slow.next;
                fast = fast.next;
            }

            return slow;
        }
    }
}

