Blind* allocateBlinds(int screenWidth, int screenHeight) {
    // Calculate the number of blinds based on screen dimensions
    // Assuming 1 blind per unit width and height, for simplicity
    int numBlinds = screenWidth * screenHeight;

    // Allocate memory for the array of blinds
    Blind* blinds = (Blind*)malloc(numBlinds * sizeof(Blind));
    if (blinds == NULL) {
        perror("Unable to allocate memory for blinds");
        exit(EXIT_FAILURE);
    }

    // Initialize the blinds
    for (int i = 0; i < numBlinds; i++) {
        blinds[i].id = i;
        blinds[i].position = 0;  // Initialize all blinds to 'open'
        blinds[i].size = 1;  // Assuming a standard size for simplicity
