#define READ_SIZE 1024
char* getNextLineFromControlSocket(int sock) {
    char *buf = (char*) malloc(READ_SIZE + 1);
    int bytesReceived;
    do {
        bytesReceived = read(sock, buf, READ_SIZE);
        if (bytesReceived == -1) {
            perror("read");
            break;
        } else if (bytesReceived == 0) {
            free(buf);
            return NULL;
        }
        buf[bytesReceived] = '\0';
        if (bytesReceived < READ_SIZE && buf[bytesReceived - 1] == '\n') {
            // Found an empty line - read more to get the next line
            int ret = read(sock, buf + bytesReceived, READ_SIZE - bytesReceived);
            if (ret == -1) {
                perror("read");
                break;
            } else if (ret == 0) {
                free(buf);
                return NULL;
            }
            for (int i = ret - 1; i >= 0; i--) {
                if (buf[bytesReceived + i] != '\n') break;
                buf[bytesReceived + i] = '\0';
            }
        }
    } while (buf[bytesReceived - 1] == '\n');

    return buf;
}

const {
  isArray, array, empty, keys, merge, concat, keyValues, filter, getIn, notEmpty
} = require('lib/util');
const { validationError } = require('lib/errors');
const { codeToLanguage, languageToCode } = require('lib/language_codes');

function getTranslatedProperties(model) {
  return filter(getIn(model, 'schema.properties'), p => getIn(p, 'x-meta.translated'));
}

function createLanguageParam(languages) {
  const validValues = languages.map(languageToCode);
  return {
    name: 'language',
    in: 'query',
    description: 'Language to return, given as an ISO 639-1 code',
    required: false,
    schema: { enum: validValues }
  };
}

function addTranslatedParameters(route, options) {
  const languages = getIn(options, 'space.languages');
  const translatedProps = getTranslatedProperties(options.model);
  if (languages && notEmpty(translatedProps)) {
    return merge(route, { parameters: concat(route.parameters, [createLanguageParam(languages)]) });
  }
  return route;
}

function validateTranslatedFields(doc, options) {
  const translatedProps = getTranslatedProperties(options.model);

  for (const [property, { maxLength }] of keyValues(translatedProps)) {
    for (const [code, value] of keyValues(doc[property] || {})) {
      if (!codeToLanguage(code)) {
        throw validationError(
          options.model,
          doc,
          `Language code ${code} not supported`,
          `${property}.${code}`
        );
      }
      if (value && maxLength && value.length > maxLength) {
        throw validationError(
          options.model,
          doc,
          `Translation for language ${codeToLanguage(code)} (${code}) cannot be longer than ${maxLength}`,
          `${property}.${code}`
        );
      }
    }
  }
}

async function selectLanguage(data, { queryParams: { language }, model }) {
  const translatedFields = keys(getTranslatedProperties(model));
  if (empty(data) || empty(translatedFields) || !language) return data;

  const docs = array(data);
  const docsWithLanguage = docs.map(doc => {
    const languageProperties = translatedFields.reduce((acc, key) => {
      acc[key] = getIn(doc, `${key}.${language}`);
      return acc;
    }, {});

    return merge(doc, languageProperties);
  });

  return isArray(data) ? docsWithLanguage : docsWithLanguage[0];
}

const model = {
  callbacks: {
    save: {
      beforeValidation: [validateTranslatedFields],
    },
    list: {
      after: [selectLanguage],
    },
    get: {
      after: [selectLanguage],
    },
    routeCreate: {
      after: [addTranslatedParameters],
    },
  },
