class EventManager
{
    static void Main(string[] args)
    {
        int[,] EventXYLocation = { { 10, 20 }, { 15, 25 }, { 30, 40 } };
        int[] EventID = { 1, 2, 3 };
        int userXLocation = 5;
        int userYLocation = 5;
        int NumberOfEvents = EventXYLocation.GetLength(0);
        int[] EventDistanceFromUser = new int[NumberOfEvents];
        int NumberOfTicketClasses = 3;
        int basePriceOfTicket = 50;
        int highestPriceOfTicket = 150;
        int[][] EventTicketClass = new int[NumberOfEvents][];
        int[][] EventTicketSortedByPrice = new int[NumberOfEvents][];

        for (int index = 0; index < NumberOfEvents; index++)
        {
            int currentEventXLocation = EventXYLocation[index, 0];
            int currentEventYLocation = EventXYLocation[index, 1];
            EventDistanceFromUser[index] = CalculateManhattanDistance(currentEventXLocation, currentEventYLocation, userXLocation, userYLocation);

            Console.WriteLine("| Event ID: " + EventID[index] + "    Event Distance: " + EventDistanceFromUser[index] + " |");

            EventTicketClass[index] = new int[NumberOfTicketClasses];

            for (int ticketIndex = 0; ticketIndex < NumberOfTicketClasses; ticketIndex++)
            {
                EventTicketClass[index][ticketIndex] = GenerateRandomEventTicketPrice(basePriceOfTicket, highestPriceOfTicket);
            }

            EventTicketSortedByPrice[index] = OrderTicketByLowestPrice(EventTicketClass[index]);
        }

        // Display sorted ticket prices for each event
        for (int index = 0; index < NumberOfEvents; index++)
        {
            Console.Write("Event ID: " + EventID[index] + " Ticket Prices: ");
            foreach (int price in EventTicketSortedByPrice[index])
            {
                Console.Write(price + " ");
            }
            Console.WriteLine();
        }
    }

    static int CalculateManhattanDistance(int x1, int y1, int x2, int y2)
    {
        return Math.Abs(x1 - x2) + Math.Abs(y1 - y2);
    }

    static int GenerateRandomEventTicketPrice(int basePrice, int highestPrice)
    {
        Random random = new Random();
        return random.Next(basePrice, highestPrice + 1);
    }

    static int[] OrderTicketByLowestPrice(int[] ticketPrices)
    {
        // Simple bubble sort implementation
        int[] sortedPrices = (int[])ticketPrices.Clone();
        for (int i = 0; i < sortedPrices.Length - 1; i++)
        {
            for (int j = 0; j < sortedPrices.Length - i - 1; j++)
            {
                if (sortedPrices[j] > sortedPrices[j + 1])
                {
                    int temp = sortedPrices[j];
                    sortedPrices[j] = sortedPrices[j + 1];
                    sortedPrices[j + 1] = temp;
                }
            }
        }
        return sortedPrices;
    }
}

