private Set<Pair> set = new HashSet<Pair>();
private List<List<Integer>> ans = new ArrayList<>();

public List<List<Integer>> findSubsequences(int[] nums) {
    dfs(nums, 0, new ArrayList<Integer>());
    return ans;
}

private int hash1(List<Integer> list) {
    int value = 31;
    for (int temp : list)
        value = value * 37 + temp;
    return value;
}

private int hash2(List<Integer> list) {
    int value = 71;
    for (int temp : list)
        value = value * 73 + temp;
    return value;
}

private void dfs(int[] nums, int current, List<Integer> list) {
    if (current == nums.length) {
        if (!list.isEmpty()) {
            int hash1Value = hash1(list);
            int hash2Value = hash2(list);
            Pair pair = new Pair(hash1Value, hash2Value);
            if (!set.contains(pair)) {
                set.add(pair);
                ans.add(new ArrayList<>(list));
            }
        }
        return;
    }

    if (list.isEmpty() || list.get(list.size() - 1) <= nums[current]) {
        list.add(nums[current]);
        dfs(nums, current + 1, list);
        list.remove(list.size() - 1);
    }

    dfs(nums, current + 1, list);
}

private class Pair {
    int hash1;
    int hash2;

    public Pair(int hash1, int hash2) {
        this.hash1 = hash1;
        this.hash2 = hash2;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Pair pair = (Pair) o;
        return hash1 == pair.hash1 && hash2 == pair.hash2;
    }

    @Override
    public int hashCode() {
        return Objects.hash(hash1, hash2);
    }
}

