    return {
        name: max(
            max(value for port, value in defect.connection.items() if connections[port].slave == name),
            max(value for port, value in defect.output.items() if connections[port].slave == name) if defect.output else float('inf'),  # Add conditional statement for empty output
        )
        for name in slaves
    }

