                Class<?> fieldClass = field.getType();
                String className = fieldClass.getName();
                String qualifiedName = resolver.resolveQualifiedName(pkg, className);
                nameMap.put(fieldName, qualifiedName);
            }
        } catch (Exception e) {
            // Log or handle exception accordingly
        }
    }
