public class Main {

    public static void main(String[] args) {
        String atomixEntries[] = {"POSITION 1", "position 23", "Home 45", "Position 56"};
        int position = 23;
        int match = binarySearch(atomixEntries, position);
        System.out.println("the match is " + match);
    }

    public static int binarySearch(String atomixEntries[], int position) {
        int left = 0, right = atomixEntries.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int positionInMiddle = Integer.parseInt(atomixEntries[mid].substring(11, 14));
            if (positionInMiddle == position)
                return positionInMiddle;
            if (positionInMiddle < position)
                left = mid + 1;
            else
                right = mid - 1;
        }
        return -1;
    }
}

