    private final ExecutorService threadPool;
    private PipeServerSocket pipeServerSocket;

    public NgWin32NamedPipeServer(String pipeName, PipeServerSocketFactory factory) throws IOException, InterruptedException {
        pipeServerSocket = factory.getPipeServerSocket(pipeName);
        threadPool = Executors.newFixedThreadPool(POOL_SIZE);

        new Thread(() -> runServer()).start();
    }

    private void runServer() {
        while (!Thread.currentThread().isInterrupted()) {
            PipeClientConnection pipeConnection = pipeServerSocket.acceptConnection();
            // Start accepting/sending messages from client

            // Handle client connection and messages...

            // When connection closes
            // 1. Release client resources and close the channel.
            // 2. Stop reading from/writing to the channel.
            // 3. Return client from holder and continue with other clients

            pipeConnection.release();

            // If the thread is interrupted...
            pipeServerSocket.release();

            // Restarts the thread
        }
    }
}

interface PipeServerSocket {
    PipeClientConnection acceptConnection() throws InterruptedIOException;
}

