func (c *Component) setParameterFromBytes(b []byte) error {
    if b == nil {
        return io.ErrUnexpectedEOF
    }

    // Attempt to parse IEs from the given bytes
    ies, err := ParseMultiIEs(b)
    if err!= nil {
        // Log the error, but proceed with a default IE
        logf("failed to parse given bytes, building it anyway: %v", err)
    }

    // Create a new IE with the given bytes
    c.Parameter = &IE{
        Tag:   NewUniversalConstructorTag(0x10), // TODO: tag should not be determined here
        Value: b,
    }

    // If IEs were parsed successfully, set them
    if ies!= nil {
        c.Parameter.IE = ies
    }

    return nil
}

