import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.NoSuchAlgorithmException;
import java.security.spec.InvalidKeySpecException;
import java.security.spec.InvalidParameterSpecException;

public Cipher encryptPassword(String salt) { 
    try {
        PBEKeySpec keySpec = new PBEKeySpec("password".toCharArray(), salt.getBytes(), 65536, 256);
        SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
        SecretKey secretKey = new SecretKeySpec(keyFactory.generateSecret(keySpec).getEncoded(), "AES");
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, new IvParameterSpec(new byte[16]));
        return cipher;
    } catch (NoSuchAlgorithmException | InvalidKeySpecException | javax.crypto.NoSuchPaddingException | java.security.InvalidKeyException | InvalidParameterSpecException e) {
        e.printStackTrace();
    }
    return null;
}

def c_sort(arr):
    non_decreasing = 0
    last_index = len(arr) - 1

    for i in range(last_index):
        if arr[i] <= arr[i + 1]:
            non_decreasing += 1

    return non_decreasing + 1

def main():
    n = int(input())
    arr = list(map(int, input().split()))

    while c_sort(arr) != len(arr):
        mid = len(arr) // 2
        c1 = c_sort(arr[:mid])
        c2 = c_sort(arr[mid:])

        if c1 < c2:
            arr = arr[mid:]
        else:
            arr = arr[:mid]

    print(len(arr))

if __name__ == "__main__":
    main()

