class Solution {
    public int maxSubarraySumCircular(int[] A) {
        if (A == null || A.length == 0) {
            throw new IllegalArgumentException("Input array must not be null or empty");
        }

        int total = 0;
        int maxSum = Integer.MIN_VALUE;
        int curMax = 0;
        int minSum = Integer.MAX_VALUE;
        int curMin = 0;

        for (int i = 0; i < A.length; i++) {
            curMax = Math.max(A[i], curMax + A[i]);
            maxSum = Math.max(maxSum, curMax);

            curMin = Math.min(A[i], curMin + A[i]);
            minSum = Math.min(minSum, curMin);

            total += A[i];
        }

        // If the entire array is negative
        if (minSum == total) {
            return maxSum;
        }

        int circularMax = total - minSum;

        // The maximum subarray sum in a circular array is either the maximum subarray sum or the total sum minus the minimum subarray sum
        return Math.max(maxSum, circularMax);
    }
}

