		var t = in.nextLong();

		var values = new TreeSet<Long>();

		var st = new StringTokenizer(in.nextLine());

		for (var i=0; i<n; i++) {

			var x = Long.parseLong(st.nextToken());

		(values).add(x);

		}(values).remove(0L);

		while(values.size() >1 && values.first() + values.pollFirst() >= t){

			var first = values.first();

			values.pollFirst();

