public class Single2Future {

    public static Future wait(String asyncResult) {
        if (Ut.isBlank(asyncResult)) {
            return null;
        }
        return WaitFuture.wait(new Single2FutureTask(asyncResult));
    }

    public static class Single2FutureTask extends AsyncAwaitFutureTaskBase {

        private final String objectKey;

        public Single2FutureTask(String objectKey) {
            super();
            this.objectKey = objectKey;
        }

        protected String getAsyncResult() {
            return objectKey;
        }
    }

}

