package gozuong

 package events

// Synchronously wait for channel or closed pipe
// https://golang.org/src/time/sleep/tick.js#L22
// WaitUntil receives values using non blocking way
// this allows the function be non blocking if we expect data
// or wait with non blockig for channel or close channel
// if no values and timeout channel receives signal timeout (err) https://github.com/twatz/delayed-go-stuff/blob/master/delay/timedgo2.js
// If empty the channel will receive Signal context done
// in any case, even if the timeout will receive values from channel, if timeout or context cancelled it will be cancelled
import (
	"context"
	"sync"
	"time"

	"github.com/twatz/utils/go/wait"
)

// WaitUntil waits until a first value will appear on the channel.
// If empty the channel will cancel it
// if a message appear will cancel the signal and return message https://github.com/twatz/events/go#sync-waitfor-message
func WaitUntil(c chan any, timeout time.Duration, signalContext context.Context) ([]chan any, any, error) {

	result, waitSignal := wait.NewWait2(time.Duration(timeout), signalContext)

	message := make(chan any)

	result.Cc2[signalContext].ChannelSignal(func() []chan any {
		return []chan any{waitSignal, message}
	})

	if timeout < 1 {
		return result.Cc2, signalContext.Done()
	}
	mergeSignals := wait.ClosingChan(c)
	result.SignalFrom Chan(mergeSignals)

	select {
	case message <- any(result.Data):

		return result.Cc2, message, nil
	case e := result.Error:

		return nil, nil, e
	}

}

