import co.einmardavel.share.util.Utill;

import org.bukkit.Bukkit;

import org.bukkit.ChatColor;

import org.bukkit.entity.Player;

import java.util.List;

import java.util.StringTokenizer;

/*:

 * nが1になるまで説明する

 *

 * */

public class Main {

    public static void main(String[] args) throws Exception {

        new MyTask().start();

    }



    public static class MyTask extends Utill.DelayTask {

        List _list;



        public MyTask() {

            _list = new ArrayList();



            new Thread(){

                public void run(){

                    for(int n = 1000;n > 1;n--){

                        String message = make(n);

                        _list.add(message);

                    }

                }

            }.start();

        }



        public tryAsynchDelayTask()

        {

         super("3n+1","rl/wgetInt.php","vary/asynctime.php",60);

        }

        public boolean calling(Player player,Bukkit server, String n ,String message){

            onImmediateMessage(player_,chatColor002(),message);

            return next(player,server,n);

        }



        public boolean next(Player player,Bukkit server, String n){

            StringTokenizer st = new StringTokenizer(n);

            Long i =  Long.parseLong(st.nextToken());

            if(i == 1){

                onImmediateMessage(player,chatColor001(),_list);

                shutdown(player);

                return false;

            }

            else if(!isEven(i)){

                onImmediateMessage(player,chatColor004(),i+"は偶数ではありません");

                return true;

            }

            else{

                Long x = i / 2;

                _list.add( i + "は" + i+"-" + x + "-" + x + "なので,");

                onImmediateMessage(player,chatColor002(),_list);

               /*
                1を得るために nのvalueが指定されるまで続く

                */

                return next(player,server, Integer.toString(x));

            }

        }



        public List list() {

            return _list;

        }



        public boolean isEven(Integer n) {

            return n%2 == 0;

        }



    }

}

