package com.hackerrank.chalengers.icecreamparlor;

import java.util.*;

import com.hackerrank.util.Util;

import java.io.*;

public class Solution5 {

	public static class Pair implements Comparable {

		int x;

		int y;

		public Pair(int x, int y) {

			this.x = x;

			this.y = y;

		}

		public int compareTo(Object o) {

			Pair pair = (Pair)o;

			return this.x - pair.x;

		}

	}

	public static void main(String[] args) throws IOException {

		Util sc = new Util();

		int t = sc.nextInt();

		for (int ti = 0; ti  t; ti++) {

			int n = sc.nextInt();

			int a[] = new int[n];

			int x = sc.nextInt();

			int cost = sc.nextInt();

			for (int i = 0; i  n - 1; i++) {

				a[i] = sc.nextInt();

			}

			a[n - 1] = cost;

			List pairs = new ArrayList<>();

			List list = new ArrayList<>();

			for (int i = 0; i  n; i++) {

				if (a[i]  x) {

					list.add(i);

				}

			}

			for (int i = 0; i  list.size(); i++) {

				int b[] = new int[n];

				for (int j = 0; j  n; j++) {

					if (j == list.get(i)) {

						b[j] = 2 * x;

					} else {

						b[j] = a[j];

					}

				}

				int current = -1;

				int sum = 0;

				for (int j = 0; j  n; j++) {

					if (sum == cost) {

						break;

					} else if (sum  cost) {

						sum += b[j];

						current = j;

					} else {

						if (j == current) {

							continue;

						} else {

							sum -= b[j];

						}

					}

				}

				if (sum == cost) {

					pairs.add(new Pair(list.get(i) + 1, current + 1));

				}

			}

			if (pairs.isEmpty()) {

				System.out.println(-1);

			} else {

				for (Pair pair : pairs) {

					System.out.println(pair.x + " " + pair.y);

				}

			}

		}

	}

}

