package codeup.problemset;

import codeup.lib.CodeProblemBase;
import codeup.lib.util.Util;

import java.io.PrintWriter;

/**
 * https://codeup.com/problem.php?id=1443
 */
public class Codeup1443 extends CodeProblemBase {

    public Codeup1443() {
        super(1443);
    }

    @Override
    public void solve() {
        long physAddr = longOf();
        int segSize = intOf();
        int segCnt = intOf();
        long[] segs = new long[segCnt];
        for (int i = 0; i < segCnt; i++) {
            segs[i] = longOf();
        }
        out.print(new Solution().getAddress(physAddr, segSize, segs));
    }

  public class Solution {
        public String getAddress(long physAddr, int segSize, long[] segs) {
            int n = segs.length;
            long[] a = new long[n + 1];
            a[0] = 0;
            for (int i = 0; i < n; i++) {
                a[i + 1] = a[i] + segSize;
            }
            int l = 0, r = n;
            while (l < r) {
                int m = l + r + 1 >> 1;
                if (a[m] >= physAddr) {
                    r = m - 1;
                } else {
                    l = m;
                }
            }
            int segIdx = l;
            long segAddr = a[segIdx];
            long rem = physAddr - segAddr;
            int remIdx = Util.bsearch(0, segSize, x -> segSize - x >= rem);
            return String.format("%d:%d", segIdx + 1, remIdx + 1);
        }
    }

    public static void main(String[] args) {
        new Codeup1443().main();
    }

    @Override
    public String run() {
        return super.run();
    }

    @Override
    protected void after() {
        super.after();
    }

    @Override
    protected void before() {
        super.before();
    }

    @Override
    protected PrintWriter writer() {
        return super.writer();
    }

    @Override
    protected void reader() {
        super.reader();
    }
}

