public class Solution {
	/**
	 * Find near-index of comparekey in leaf under this node.
	 *
	 * @param compareKey
	 * @param inLeaf
	 * @param lookPastOnly
	 * @return
	 */
	public static int findNearIndex(String compareKey, BloomFilterNode[] inLeaf, boolean lookPastOnly) {
		return inLeaf().stream()
				.filter(node -> node.compareKey().equals(compareKey))
				.mapToInt(BloomFilterNode::index)
				.findFirst().orElseGet(() -> {
					if (lookPastOnly) {
						return inLeaf().stream()
								.filter(node -> node.compareKey().compareTo(compareKey) > 0)
								.mapToInt(BloomFilterNode::index)
								.findFirst()
								.orElseThrow();
					} else {
						int left = 0;
						int right = inLeaf().length - 1;
						while (left <= right) {
							int middle = left + (right - left) / 2;
							if (inLeaf()[middle].compareKey().equals(compareKey)) {
								return middle;
							} else if (inLeaf()[middle].compareKey().compareTo(compareKey) > 0) {
								right = middle - 1;
							} else {
								left = middle + 1;
							}
						}
						return left;
					}
				});

