package powsal.core.acpi.utils.parser;

import powsal.core.acpi.utils.parser.scope.AcpiParserScope;
import powsal.core.acpi.utils.parser.structs.*;
import powsal.core.utils.ACPIConsts;
import powsal.core.utils.ErrorStatus;
import java.util.*;

import static powsal.core.utils.TextUtils.createElementText;

public class AcpiPsUtils {

	/**
	 * Destroy available list, remaining stack levels, and return root scope
	 *
	 * FUNCTION:  Acpi_ps_cleanup_scope
	 *
	 * PARAMETERS: Parser_state        - Current parser state object
	 *
	 * RETURN:    Status
	 *
	 * DESCRIPTION: Destroy existing parser scope correctly, so we may parse 
	 *              Scope levels above the current one.
	 *
	 */
	public static ErrorStatus cleanupScope(AcpiParserScope parserState)
	{
		ErrorStatus status = new ErrorStatus();

		/// Clean up current list
		if (parserState.getAnchorList() != null) {
			for (int i = parserState.getAnchorList().size() - 1; i >= 0; i--) {
				GameObject obj = (GameObject) parserState.getAnchorList().get(i);
				if (obj.hasConcrete()) {
					if (obj.getType() > ACPIConsts.blockType && obj.getType() <= ACPIConstsMethodInfo) {
						obj.setConcrete(false);
					} else {
						parserState.getAnchorList().remove(i);
					}
				}
			}
		}

		/// Remove remaining stack levels
		while (parserState.unstackLevel(status)) {
			if (status.getErrorStatus() != 0) {
				break;
			}
		}

		/// Return scope
		return parserState.getParserStateTop();
	}

}

