import java.lang.reflect.Field;
import java.lang.reflect.Method;

import co.elecphant.push.exception.PushValueExtractException;
import co.elecphant.push.model.AppOpen;

/**
 * <p>
 *
 * @author <a href="mailto:junwen.bj@gmail.com">JunWen.Zhang</a> (2014)
 * 
 */
public @interface ExtractValue {

    public String name() default "";

    public String value() default "";

    public class Extractor {
        private String name;

        public Extractor(String name) {
            this.name = name;
        }

        public Object extractValue(AppOpen appOpen) throws PushValueExtractException {
            if (name.isEmpty()) {
                return null;
            }
            Method method;
            Field field;
            try {
                method = appOpen.getClass().getMethod(getValue() + "Value");
                return method.invoke(appOpen);
            } catch (NoSuchMethodException e) {
                method = null;
            }
            if (method == null) {
                try {
                    field = appOpen.getClass().getDeclaredField(name);
                    return get(field, appOpen);
                } catch (NoSuchFieldException e) {
                    // 
                    throw new PushValueExtractException("Field '" + name
                            + "' was not found");
                }
            } else {
                try {
                    return method.invoke(appOpen);
                } catch (Exception e) {
                    // 
                    throw new PushValueExtractException("Method '"
                            + name + "Value()' return type error. "
                            + "it must be " + field.getType() + ", not " + method
                            .getReturnType());
                }
            }
        }
    }

    private static Object get(Field field, AppOpen appOpen) throws Exception {
        return field.get(field.getType().newInstance()).extractValue(appOpen);
    }

} 

