export default function splitMostlikelyLessLikely(workers, dur, minPieces, overdrive) {
	if (overdrive > minPieces) {
		return {
			likelyWorkers: workers,
			unlikelyWorkers: []
		};
	}

	var likeLikelyWorkers = [];
	var i = minPieces;

	// start with minPieces workers, take the next ones to reach the amount of overdrive workers
	var j = minPieces + overdrive;
	while (i > 0 && j <= workers.length) {
		likeLikelyWorkers.push(workers[i - 1]);
		--i;
		j += 1;
	}

	// add all workers that are beyond the overdrive amount
	j = minPieces + overdrive + 1;
	while (j <= workers.length) {
		likeLikelyWorkers.push(workers[j - 1]);
		j++;
	}

	var unlikLikelyWorkers = workers.slice(0, minPieces).concat(workers.slice(minPieces + overdrive + 1));
	return {
		likelyWorkers: likeLikelyWorkers,
		unlikelyWorkers: unlikLikelyWorkers
	};
}

