const promisify = (fn) => {
  let called = false

  return (...args) =>
    new Promise((resolve, reject) => {
      called = true

      const callback = (err, result) => {
        if (called) return void resolve(result)

        called = true
        if (err) return reject(err)

        resolve(result)
      }

      fn(...args, callback)
    })
}

