// ScheduledUpdates cancels, creates and updates scheduled tasks for 
// dispatching on-chain task updator functions. Discerns new maturity jobs from
// existing ones. Pass nil jobs for "none" - behaviour
func ScheduleUpdates(existingJobs map[string]int, newJobs map[string]int) []string {
	var (
		removedJobs    = make([]string, 0)
		newMaturedJobs = make([]string, 0)
		existingUpdats = make([]string, 0)
	)

	for n, _ := range newJobs {
		_, e := existingJobs[n]

		// is new
		if !e {
			existingJobs[n] += 1
			newMaturedJobs = append(newMaturedJobs, n)
		} else {
			// is "exsisting"
			existingJobs[n] += 1
			existingUpdats = append(existingUpdats, n)
		}
	}

	for e, i := range existingJobs {
		if i == 1 {
			removedJobs = append(removedJobs, e)
		}
	}

	// existingJobs = nil

	return append(newMaturedJobs, existingUpdats, removedJobs...)
}

