 * @version $Id: RotateZ.java, v 0.1 2015-05-26 09:14:30 xiaolong Exp $
 */
public class RotateZ {

	public FloatVector rotate(FloatVector vec, FloatVector3D angle) {

		return new FloatVector(vec.x, vec.y, vec.z
				* Math.cos(angle.x) - vec.x * Math.sin(angle.x), vec.x
				* Math.sin(angle.x) + vec.y * Math.cos(angle.x), vec.z
				* Math.cos(angle.y) - vec.y * Math.sin(angle.y));
	}
}

