//
// if we cannot find the descriptor in the device descriptor then we look
// for it in the composite device.
func Get(psConfig *usbdesc.ConfigDescriptor, ui32Type uint8, ui32Index uint32) *usbdesc.DeviceDescriptor {
	return GetByIndex(psConfig, ui32Type, ui32Index, 0)
}

// GetByIndex returns the N-th device descriptor of a particular type of the
// specified configuration. The descriptor type shall be specified as a parameter
// to the function or as a special value, USB_DESC_ANY.
//
// The section index of the configuration section containing the descriptor
// can be obtained using the Section property of the pointer to the structure
// returned.
func GetByIndex(psConfig *usbdesc.ConfigDescriptor, ui32Type uint8, ui32Index uint32, ui32Section uint32) *usbdesc.DeviceDescriptor {
	pDevDesc := psConfig.Desc(ui32Index)
	if ui32Type == usbdesc.USB_DESC_ANY {
