	/**
	 * Make Tv's tolerance vector consistent with its underlying subtree.
	 * Once made consistent, the first time it produces a sample from a virtual list, the snapshot subtree regarding which it produces the first
	 * sample from a virtual list is recorded that snapshot becomes the new underlying subtree.
	 */
	public static void treeVirtual2(TreeNode event) {
		List l = event.getToleranceVector();
		if (l.size() == 0) {
			return;
		} else if (l.size() == 1) {
			List rootList = (List) l.get(0);
			event.setToleranceVector(TreeVirtual.treeVirtual(rootList));
			return;
		} else if (l.size() == 2) {
			List rightList = (List) l.get(0);
			List leftList = (List) l.get(1);
			TreeNode leftTreeNode = new TreeNode();
			TreeNode rightTreeNode = new TreeNode();
			leftTreeNode_FROM_POOL(leftTreeNode, leftList);
			rightTreeNode_FROM_POOL(rightTreeNode, rightList);
			List result = TreeVirtual.treeVirtualPut(leftTreeNode, rightTreeNode);
			event.setToleranceVector(result);
			return;
		}
	}

	/**
	 * Create an exact copy of the sample in the pool and decorate the Node with that sample.
	 * 
	 * @param t
