            Pattern pattern = Pattern.compile(PATTERN);

            Matcher matcher;

            try {
                String input = request.getParameter("input");
                matcher = pattern.matcher(input);

                StringBuffer masked = matcher.replaceFirst(new StringBuffer(showFirst));

