				throw e;
			}

			var (parentType, id, action) = (strings[0], strings[1], string.Join(".", strings.Skip(2)));
			var baseUrl = new BaseUrlResolver
			{
				ParentType = parentType,
				ParentId = new IdResolver().ById(id).Url,
			};

			var url = $"{baseUrl.Url}/{action}";

			return url;
