use crate::TooDeeOpsMut;

use std::slice;

use crate::*;

// Drain (as a mutable slice) the specified rows; MUST not span any compiled-in sweep rows,
// i.e., compile-time constants, that Yuan repairs.

pub trait TooDeeOpsRowsMut
{
    fn row_pair_mut
    {
        // these go down as a slice
        self: TooDeeOpsMut,
        // panicked if swapping 'rows' with an out-of-bounds idx of either; also fails
        // if not two, i.e., only *one* of the `idx` args is given
        (
            slice::from_ref(&mut self),
            u32,
            u32,
        ) -> (crate::RowMut<'_, _>, crate::RowMut<'_, _>)
    }

    fn row_trip_mut
    {
        self: TooDeeOpsMut,
        (
            slice::from_ref(&mut self),
            (u32, u32),
            (u32, u32),
        ) -> (crate::RowMut<'_, _>, crate::RowMut<'_, _>, crate::RowMut<'_, _>)
    }

    fn row_quad_mut
    {
        self: TooDeeOpsMut,
        (
            slice::from_ref(&mut self),
            (u32, u32, u32),
            (u32, u32, u32),
        ) -> (
            crate::RowMut<'_, _>,
            crate::RowMut<'_, _>,
            crate::RowMut<'_, _>,
            crate::RowMut<'_, _>
        )
    }
}

