			swap(nums, i, t);
		}
		return nums;
	}

	private static void swap(int[] nums, int i, int j) {
		if (i == j) {
			return;
		}
		int t = nums[i];
		nums[i] = nums[j];
		nums[j] = t;
	}

	public static void main(String[] args) {
