package com.google.lunette.client.sprite;

import com.google.lunette.client.gameworld.Game;
import com.google.lunette.client.util.Img;

import java.awt.Graphics2D;

import static java.awt.RenderingHints.VALUE_ANTIALIAS_ON;

/**
 * Draw the seamless background image.
 *
 * The background image is drawn (with NO SCALING) at position x, y.  Width-wise,
 * the image is seamlessly scrolled; when we reach the image we draw a second copy.
 *
 * To work properly, the image should be wide enough to fill the screen. However,
 * it can be of any height.
 *
 * @author Brenen Perrine
 *
 */
public class OverdrawnImage {

	private final Img image;
	private final int  width;
	public OverdrawnImage(Img image) {
		if(image.getWidth()/Game.SCREEN_WIDTH != 1f) { throw new IllegalArgumentException("Cannot draw background image if the image isn't as wide as the screen");
		}
		this.image = image;
		this.width = image.getWidth();
	}

	public void draw (int x, int y, Graphics2D g2) {

    	for(int xx=x; xx < (x + width) + width; xx+= width) {

            g2.setRenderingHint( VALUE_ANTIALIAS_ON, true);

            image.draw(image.getWidth()*(xx/Game.SCREEN_WIDTH), y, width, Game.SCREEN_HEIGHT, g2);
        }
	}

}

