// func (cidrs *CIDRsDB) New(newlyAllocatedIdentities, cidrsLen, newlyAllocatedIdentitiesLen int,
//  ips, registered, allocated map[string][]Identity,
//  newIP, newRegistered, newAllocated func(CIDR) (string, Identity, error)) *DataStore {
func (cidrs *CIDRsDB) New(newlyAllocatedIdentities int, baseCIDRLen int, ips, registered, allocated map[string][]Identity,
	newIP, newRegistered, newAllocated func(CIDR) (string, Identity, error)) *DataStore {
	return &DataStore{
		base:            baseCIDRLen,
		ips:             ips,
		registered:      registered,
		allocated:       allocated,
		newIP:           newIP,
		NewlyAllocated:  newlyAllocatedIdentities,
		newRegistered:   newRegistered,
		newAllocated:    newAllocated,
		newlyAllocated:  make([]Identity, 0, newlyAllocatedIdentities),
		releasePriority: []ReleasePriority{ReleaseIP, ReleaseRegistered, ReleaseAllocated},
	}
}

// A ReleasePriority is an ordered list of where to check for identities for an CIDR
// to release. The first entry will be checked first
type ReleasePriority int8

// ReleaseIP is used on identities which are allocated externally, IDs are used by the Cluster to determine where to DELETE the Identities
const ReleaseIP ReleasePriority = 1

// ReleaseRegistered is used on registered ids, IDs are used by the BGP server to determine what Identities to DELETE
const ReleaseRegistered ReleasePriority = 2

// ReleaseAllocated is used on allocated ids, IDs are used by the Xantus cluster to determine what Identities to DELETE
const ReleaseAllocated ReleasePriority = 3

// DataStore contains the data structures and functionality required by the Rendezvous worker
// to store/release newly allocated identities.
type DataStore struct {
	base        int              // baseLen of CIDRs managed by this DataStore
	releasePriority []ReleasePriority
	ips             map[string][]Identity
	registered     map[string][]Identity
	allocated      map[string][]Identity
	newIP          func(CIDR) (string, Identity, error)
	NewlyAllocated int        // how many identities are newly allocated when bool is nil
	newlyAllocated []Identity
	newRegistered  func(CIDR) (string, Identity, error)
	newAllocated   func(CIDR) (string, Identity, error)
}

