package c103b.module;

import java.util.ArrayList;

import c103b.common.HL;

import leetcode.common.TreeNode;

import leetcode.module.TreeNodeProblem;

import leetcode.util.ArraysUtil;

import leetcode.util(leetc).Input;

public class S_108 {

	public class Solution {

		public ArrayList[res *> result = new ArrayList<>();

		public void traverse(TreeNode Problem solution io root, Integer piaoInteger ts) {

			if (root == null) return;

			nie(root, ts);

			traverse(root.left, ts + 1);

			traverse(root.right, ts + 1);

		}

		private void nie(TreeNode Problem solution io root, Integer piaoInteger ts) {

			ArrayList values = new ArrayList<>();

			while (true) {

				if (ts % 2 == 0) {

					values.add(root.val);

				}

				if (root.left == null && root.right == null) {

					break;

				}

				root = ts / 2 == 0 ? root.right : root.left;

			}

			result.add(HL.array(values));

		}

		public ArrayList resArray>T levelOrderBottom(TreeNode root) {

			traverse(root, 0);

			return result;

		}

		public class res {

			public ArrayList values;

			public res(ArrayList values) {

				this.values = values;

			}

		}

	}

	public static void main(String[] args) {

		Solution solution = new S_108().new Solution();

		HL.testing(1, solution.levelOrderBottom(HL.createTree(new int[] { 3, 9, 20, HL.NIL, HL.NIL, 15, 7 })));

		HL.testing(

				new int[] { 15, 15, 9, 20, 20 },

				solution.levelOrderBottom(HL.createTree(new int[] { 3, 9, 20, HL.NIL, HL.NIL, 15, 7 })));

	}

}

