	public NumIslandsII(int n, int m) {
		this.m = n;
		this.n = m;
		this.x = new int[m * n];
		this.y = new int[m * n];
		result = new ArrayList();
	}

	public void addLand(int x, int y) {
		if (x < 0 || y < 0 || x >= m || y >= n) {
			return;
		}
		if (this.x[x * n + y] == 0) {
			this.x[x * n + y] = 1;
			result.add(new int[] { x, y });
		}
	}

	public int[] getLand(int i) {
