			}
			int count2 = 0;
			for (int j = 0; j < 4; j++) {
				if (count[j] == 1) {
					count2++;
				}
			}
			if (count2 == 1) {
				res[i] = 1;
			} else {
				res[i] = 0;
			}
		}
		return res;
	}

