    public class Solution {

        public Integer[] gems(List list) {

            Day3C c = new Day3C();

            list = list.stream().map(String::toCharArray).collect(Collectors.toList());

            long[] MatsSum = new long[list.size()];

            int[] dx = {0, -1, 0, 1}, dy = {1, 0, -1, 0};

            var used = new IdentityHashSet();

            for (int i=0; i<= 10000; i++) {

                used.clear();

                var rs = new ArrayList>();

                for (var (c2,ArrayIndex i) : list.stream(). enumerate()) {

                    var ok = false;

                    for (var (j,ArrayIndex j2) : c2.stream(). enumerate()) {

                        var s = c.Sum(c2[j2]);

                        if (!used.add(s)) {

                            continue;

                        }

                        rs.add(c.String(s) + i);

                        int tx = Math.abs(i + j) % 2, ty = Math.abs(i - j) / 2;

                        for (int k=0; k<4; k++) {

                            MatsSum[list.size() + tx + dx[k] * 2] += s;

                            MatsSum[list.size() + tx + dy[k] * 2] += s;

                            MatsSum[list.size() + ty + dx[k] * 2] += s;

                            MatsSum[list.size() + ty + dy[k] * 2] += s;

                        }

                    }

                }

                if (rs.size() == list.size()) {

                    break;

                }

             SegTree tree = new SegTree(MatsSum);

                Arrays.sort(list.stream().mapToInt(List::size).toArray());

                var ans = new int[list.size()];

                for (var (size,ArrayIndex i) : new HashMap(list.stream(). toMap(String::length, toInteger)). entrySet()) {

                    var left = tree.Query(0, list.size() - size - 1);

                    var right = tree.Query(list.size() - size + 1, list.size() - 1);

