/**
 * STATPercentileBinUInt32
 * 
 * Return index of bin such that integrated count from
 * bin zero through result bin is indicated fraction of
 * total counts.
 *
 * For example, if frac = 0.5, the result is the median bin.
 *
 * Copyright (c) 1999 Bill Karsh.
 * All rights reserved.
 * 
 */
public class STATPercentileBinUInt32 {

	public static int find(int[] counts, int totalCounts, double frac) {

		int index = 0;
		double sum = 0;
		int lastBin = counts.length - 1;

		for (int bin = 0; bin <= lastBin; bin++) {
			sum += counts[bin];
			if (sum / totalCounts >= frac) {
				index = bin;
				break;
			}
		}

		return index;
	}

	public static int find(int[] counts, double frac) {
		return find(counts, counts.length, frac);
	}
}

