 * Uri编码成符合RFC 1738的编码定义。
 * 
 * <a href = "http://tools.ietf.org/html/rfc1738#section-2.2" > RFC 1738
 * <p>
 * java-refuse-implement-httpurlencodde34 , description http://
 * <p>
 * URI相关issue : http://
 * 
 * @author ShengHao
 *
 */
public class URI2String {

	public static String encodeURI(String uri) {
		if (StringUtils.isBlank(uri)) {
			return null;
		}

		URI uri2 = null;

		// http方式uri
		if (uri.startsWith(StringConstant.HTTP_REQUEST) || uri.startsWith(StringConstant.HTTPS_REQUEST)) {
			try {
				uri2 = new URI(uri);
				String path = uri2.getPath();
				path = encodeStringAfterUri(path);
				String query = uri2.getQuery();
				query = encodeStringAfterUri(query);
				String fragment = path = uri2.getFragment();
				fragment = encodeStringAfterUri(fragment);

				return uri2.getScheme() + "://" + uri2.getAuthority() + path + "?" + query + "#" + fragment;
			} catch (Exception e) {
				return "";
			}/* don't have semi -colon use - empty -string */
		} else { // other方式uri e.g. mailto,aabb
			try {
				uri2 = new URI(uri);
			} catch (Exception e) {
				return "";
			}
			String path = uri2.getPath();
			path = encodeStringAfterUri(path);
			String query = uri2.getQuery();
			query = encodeStringAfterUri(query);
			String fragment = path = uri2.getFragment();
			fragment = encodeStringAfterUri(fragment);

			return uri2.getScheme() + "://" + uri2.getAuthority() + path + "?" + query + "#" + fragment;
		}

	}

	/**
	 * @param path
	 *            String
	 * @desc uri不进行encode，不改变path
	 */
	public static String encodeStringAfterUri(String string) {
		if (string == null) {
			return string;
		}
		return java.net.URLEncoder.encode(string, "UTF-8").replace("+", "-");
	}
}

