public class Solution_1022 {

    public int sumRootToLeaf(TreeNode root) {

        int sum = 0;

        return dfs(root,0,sum);

    }

    private int dfs(TreeNode root,int preSum,int sum){

        if (root == null){

            return 0;

        }

        sum = sum * 2 + root.val;

        if (root.left == null && root.right == null){

            return sum;

        }

        return dfs(root.left,preSum,sum) + dfs(root.right,preSum,sum);

    }

    public static void main(String[] args) throws IOException {

        Solution_1022 solution = new Solution_1022();

        TreeNode root = new TreeNode(1);

        root.left = new TreeNode(2);

        root.right = new TreeNode(3);

        root.left.left = new TreeNode(4);

        root.left.right = new TreeNode(5);

        root.right.right = new TreeNode(6);

        Printer.printTree(root);

        System.out.println(solution.sumRootToLeaf(root));

    }

    public class TreeNode {

        int val;

        TreeNode left;

        TreeNode right;

        TreeNode(int x) { val = x; }

    }

    public class Solution_1021 {

        public int removeOuterParentheses(String S) {

            int ans = 0;

            int left = 0;

            int right = 0;

            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < S.length(); i++){

                if (S.charAt(i) == '('){

                    left++;

                }else {

                    right++;

                }

                if (left == right){

                    sb.append(S.substring(i+1,left-i-1));

                    ans++;

                }

            }

            return sb.toString().length();

        }

    }

    public class Solution_1020 {

        public int numJewelsInStones(String J, String S) {

            Set set = new HashSet<>();

            for (int i = 0; i < J.length(); i++){

                set.add(J.charAt(i));

            }

            int ans = 0;

            for (int i = 0; i < S.length(); i++){

                if (set.contains(S.charAt(i))){

                    ans++;

                }

            }

            return ans;

        }

    }

    public class Solution_1019 {

        public int numTeams(int[] A) {

            int ans = 0;

            for (int i = 1; i < A.length-1; i++){

                int left = 0;

                int right = 0;

                int left2 = 0;

                int right2 = 0;

                for (int j = 0; j < i; j++){

                    if (A[j] < A[i]){

                        left++;

                    }else {

                        left2++;

                    }

                }

                for (int j = i+1; j < A.length; j++){

                    if (A[j] < A[i]){

                        right++;

                    }else {

                        right2++;

                    }

                }

                ans += left * right + left2 * right2;

            }

            return ans;

        }

    }

    public class Solution_1018 {

        public int[] sortedSquares(int[] A) {

            int[] ans = new int[A.length];

            for (int i = 0; i < A.length; i++){

                ans[i] = A[i] * A[i];

            }

            Arrays.sort(ans);

            return ans;

        }

    }

    public class Solution_1017 {

        public int[] findDiagonalOrder(List lists) {

            int n = lists.size();

            int m = lists.get(0).size();

            int[][] ans = new int[n][m];

            for (int i = 0; i < n; i++){

                for (int j = 0; j < m; j++){

                    ans[i][j] = lists.get(i).get(j);

                }

            }

            return ans;

        }

    }

