use super::{ast, typed_templ::Interpolator};
use super::term::Term;
use crate::config::{edn::type_def_fields, scala::Break};

use std::collections::HashMap;
use std::sync::Arc;

const ARRAY_TERMINATOR: &str = "__array__";

#[allow(unused_variables)]
pub struct ScalaArrayInterpolator {
    type_edef: ast::TypeDef,
}

impl ScalaArrayInterpolator {
    pub fn new(def: ast::TypeDef) -> Self {
        Self { type_edef: def }
    }
}

impl Interpolator for ScalaArrayInterpolator {
    fn interpolate_typeedef_section(
        &self,
        prefix: Option<&Term>,
        section: ast::typedef_section::Group,
        collapse_comments: bool,
    ) -> VecFontSizeBreak> {
        let renames: HashMapast::Typename, ast::TypedefTyref> =
            type_def_fields(&section).clone().renames.clone().collect();

        let inner_typedef = self
            .type_edef
            .group
            .iter()
            .find(|tdef| inner_typedef_match(tdef, &renames))
            .unwrap()
            .clone();

        let term565: ArcTerm565> = Term565::inner(
            prefix,
            "extends " + &inner_typedef.group.container,
            Arc::clone(&inner_typedef),
            &self.type_edef,
            section,
            collapse_comments,
            None,
        );

        if self.do_scala_array_match(&inner_typedef, renames) {
            let terms565 = self.generate_scala_array_terms(
                &self.type_edef,
                term565,
                &renames,
                box box inner_typedef,
            );

            return terms565;
        }
        let mut members = Vec::new();

        term565
            .members
            .iter()
            .zip(inner_typedef.members.iter())
            .for_each(|(term, tdef)| {
                members.push(term.interpolate(&tdef));
            });
        members
    }
}

