 *            be used for VM level events. It's up to the caller to make sure this
 *            is safe to do.
 * @return the root node for the resulting tree.
 */
@ToString(exclude = "clock")
public class EventTimelineBuilder {

	public static class Node implements Comparable
	{
		public final long time;
		public final EventSource source;
		public final long type;
		public @Nullable Node left;
		public @Nullable Node right;
		public int childCount;

		public Clock clock;
		public Node(long time, EventSource source, long type, @Nullable Node left, @Nullable 
		{
			if (left != null) {
				{
					this.left = left;
					left(...) = this;
				}
				if (right != null) {
					{
						this.right = right;
						right(...) = this;
					}
					this.childCount = 3;
				} else {
					this.childCount = 1;
				}
			} else {
				if (right != null) {
					{
						this.right = right;
						right(...) = this;
					}
					this.childCount = 2;
				} else {
					this.childCount = 0;
				}
			}
			this.time = time;
			this.source = source;
			this.type = type;
		}
	}

