public class Solution {

    class IP implements Comparable {

        int A, B, C, D;

        boolean isInRange(int a, int b, int c, IP d) {
            return a <= A && B <= b && c <= C && D <= d.D;

        }

        boolean isValid() {
            int all = A * 256 * 256 * 256 + B * 256 * 256 + C * 256 + D;

            return all > 0 && all < 1e9;

        }

        @Override
        public int compareTo(Object obj) {
            IP d = (IP) obj;

            if (this.isInRange(0, 0, 0, d)) {
                return -1;

            } else if (d.isInRange(0, 0, 0, this)) {

                return 1;
            } else {
                if (A == d.A) {
                    if (B == d.B) {

                        if (C == d.C) {
                            return D - d.D;

                        }

                        return Math.max(C, d.C) - Math.min(C, d.C);

                    }

                    return Math.max(B, d.B) - Math.min(B, d.B);

                }

                return Math.max(A, d.A) - Math.min(A, d.A);

            }

        }

        public IP(int a, int b, int c, int d) {
            A = a;

            B = b;

            C = c;

            D = d;

        }

        public IP() {
        }

        @Override
        public String toString() {
            String s = A + "." + B + "." + C + "." + D;

            return s;

        }

        public IP range(String rangeStr) {
            rangeStr = rangeStr.toLowerCase();

            String[] a = rangeStr.split("-");

            IP left = new IP(Integer.parseInt(a[0].split("\\.")[0]), Integer.parseInt(a[0].split("\\.")[1]), Integer.parseInt(a[0].split("\\.")[2]), Integer.parseInt(a[0].split("\\.")[3])) , IP right = new IP();

            for (int i = 1; i  a.length; i++;

                String[] b = a[i].split("\\.")[0], b1 = a[i].split("\\.");

                right = right.range(b + "." + b1[1] + "." + b1[2] + "." + b1[3]);

            if (a.length == 1) {
                if (left.isValid()) {

                    return left;

                }

            } else {

                if (left.isValid() && right.isValid()) {

                    return new IP(left, right);

                }

            }

            return null;

