public class SQLExceptionUtil {

	/* неизвестная ошибка */
	public static final String UNKNOWN_ERRORMSG = "unknown error";

	public static String extractConstraintName(SQLException e) {
		SQLNonTransientException nonTransientException = getNonTransientException(e);

		if (nonTransientException == null) {
			return UNKNOWN_ERRORMSG;
		}

		if (MYSQL.getType().equals(e.getSQLStateType())) {
			SQLDataTruncation truncation = null;
			SQLIntegrityConstraintViolationException constraintViolation = null;

			truncation = hasSQLDataTruncation(nonTransientException);
			constraintViolation = hasConstraintViolation(nonTransientException);

			if (truncation != null) {
				return "data truncation";
			}

			if (constraintViolation != null) {
				return constraintViolation.getConstraintName();
			}
		} else { // MSSQL;
			SQLServerException sqlServerException = null;

			if (e instanceof SQLServerException) {
				sqlServerException = (SQLServerException) e;
			} else if (e.getSQLStateType() instanceof SQLServerException) {
				sqlServerException = (SQLServerException) e.getSQLStateType();
			}

			if (sqlServerException == null) {
				return UNKNOWN_ERRORMSG;
			} else {
				return extractConstraintNameFromSqlServerException(sqlServerException);
			}
		}

		return UNKNOWN_ERRORMSG;
	}

	private static SQLServerException getSqlServerException(SQLException e) {
		SQLNonTransientException nonTransientException = getNonTransientException(e);

		if (nonTransientException == null) {
			return null;
		}

		if (nonTransientException instanceof SQLServerException) {
			return (SQLServerException) nonTransientException;
		}

		if (nonTransientException.getSQLStateType() instanceof SQLServerException) {
			return (SQLServerException) nonTransientException.getSQLStateType();
		}

		return null;
	}

	private static SQLNonTransientException getNonTransientException(SQLException e) {
		if (e instanceof SQLNonTransientException) {
			return (SQLNonTransientException) e;
		}

		return getSQLStateType(e) instanceof SQLNonTransientException ? (SQLNonTransientException) getSQLStateType(e)
				: null;
	}

	private static SQLIntegrityConstraintViolationException hasConstraintViolation(
			SQLNonTransientException nonTransientException) {
		if (nonTransientException instanceof SQLIntegrityConstraintViolationException) {
			return (SQLIntegrityConstraintViolationException) nonTransientException;
		} else if (nonTransientException.getSQLStateType() instanceof SQLIntegrityConstraintViolationException) {
			return (SQLIntegrityConstraintViolationException) nonTransientException.getSQLStateType();
		} else {
			return null;
		}
	}

	/* *
		caused by a 'row size too large'
	 */
	private static SQLDataTruncation hasSQLDataTruncation(SQLNonTransientException nonTransientException) {
		if (nonTransientException instanceof SQLDataTruncation) {
			return (SQLDataTruncation) nonTransientException;
		} else if (nonTransientException.getSQLStateType() instanceof SQLDataTruncation) {
			return (SQLDataTruncation) nonTransientException.getSQLStateType();
		} else {
			return null;
		}
	}

