export default function(
    this: ReactComponent,
    qsKey: string | string[] = "",
    closeCallback?: func,
    initialValue?: string | { [key: string]: any }
) {

    const useQuery = useQueryString(qsKey, initialValue);

    const setQuery = useQuery.setQuery;

    const setQueryString = (params: { [key: string]: any }) => {

        let query: { [key: string]: any } = {};

        for (let key in params) {

            query[key] = params[key];
        }

        setQuery(query);

        if (typeof closeCallback === "function") {

            closeCallback();
        }
    };

    return [
        useQuery.value,
        setQueryString
    ] as ComponentHook;
