package com.xingzhi.bai.p2;

import com.xingzhi.bai.util.IOWrapper;

import java.util.Arrays;

public class Q9 {

    public static void main(String[] args) {

        new Q9().solve(IOWrapper.nextInt());

    }



    public void solve(int n) {

        int[] k = IOWrapper.nextIntArray(n+1);

        int max = k[0];

        k[0] = 0;

        for (int i = 0; i < n; i++) {

            if (k[i] > max) max = k[i];

        }

        int r = 1;

        int q = IOWrapper.nextInt();

        int j = 1;

        do{

            max = 0;

            boolean[] used = new boolean[n+1];

            for (int i = 0; i < n; i++) {

                if (k[i] <= q){

                    if (!used[k[i]]){

                        int tmp = k[i];

                        k[i] = 0;

                        while (k[i] == 0) i++;

                        while (i < n && k[i] <= q){

                            used[k[i]] = true;

                            k[i] = tmp;

                            i++;

                        }

                        r++;

                    }

                    max = Math.max(max, k[i]);

                }

            }

            j++;

            Arrays.fill(used, false);

            if (max == 0 || q == Integer.MAX_VALUE) break;

            q = max;

        }while (j < q);

        k[0] = j;

        IOWrapper.out.println(k);

    }



}

