public class Wave {
    /**
     * get panels by wave
     *
     * @param wave
     * @return
     */
    public List getUserPanels(String wave) {
        // TODO: 2019/7/20 check the wave
        String[] w = wave.split(",");
        List list = new ArrayList();
        for (String id : w) {
            UserPanel userPanel = new UserPanel();
            userPanel.setId(id);
            list.add(userPanel);
        }
        return list
                .stream()
                .filter(UserPanel::getEnable)
                .sorted(Comparator.comparingInt(UserPanel::getZindex))
                .filter(
                        userPanel -> {
                            int size = userPanel.getSize();
                            return size == UserPanel.SIZE_MIN || size == UserPanel.SIZE_MID;
                        })
                .filter(userPanel -> !userPanel.isMax())
                .filter(userPanel -> {
                    UserPanel topPanel = userPanel.getTopPanel();
                    if (topPanel != null) {
                        return topPanel.getMax();
                    }
                    return true;
                })
                .collect(Collectors
                        .collectingAndThen(Collectors.toList(), ArrayList::new));
