var TransformAbstractFunctionsToFunctions = function() {
	/**
	 * Replaces [a SymbolNode that has a symbol of type AbstractFunction,
	 * followed by a node of type ContainerNode] by a FunctionNode.
	 * Expects the $nodes not including any function nodes (yet).
	 *
	 * @param {FrontCalculatorParserNodeAbstract[]} nodes
	 *
	 * @returns {FrontCalculatorParserNodeAbstract[]}
	 */
	_.transform(function(nodes) {
		return nodes.map(function(node) {
			if (node instanceof parser.SymbolNode && node.symbol instanceof AbstractFunction) {
				var containerNode = node.next();
				if (containerNode instanceof parser.ContainerNode) {
					return new FunctionNode([node.symbol, containerNode]);
				}
			}
			return node;
		});
	});
}; module.exports = TransformAbstractFunctionsToFunctions;

