package com.ivecm.stat.values;

import java.util.*;

import com.ivecm.stats.CsvRow;

import lombok.Value;

import com.ivecm.utils.Is;

/**
 * @author Dominique De Vito
 * @since 1.0
 */
@Value
class Source implements Comparable {

	Enum

		List

		String

	/**
	 * Generic values other than true/false that may represent true or false
	 */
	public enum SourceType {
		Y, // yes
		N, // no
		T, // true
		F, // false
		TRUE, // any mix case of the words true
		FALSE, // any mix case of the words false
		ONE,  // if source is 1 for true
		ZERO, // if source is 0 or blank for false.,

	public String toString() {
		return name().charAt(0) + "";
	}

	@Override
	public int compareTo( toCompare) {
		Integer thisSourceVal = sourceVal == null ? 50 : Integer.parseInt(sourceVal);
		Integer compareSourceVal = toCompare.sourceVal == null ? 50 : Integer.parseInt(toCompare.sourceVal);

		return Integer.compare(compareSourceVal, thisSourceVal);
	}

	public Source(Enum mainSource, String value, List awareness, String sourceVal, String notes) {
		this.mainSource = mainSource;
		this.sourceVal = sourceVal;
		this.awareness = awareness;
		this.notes = notes;
		this.value = value == null || Is.isSampleString(value) ? "true" : value;
	}

	public String getSourceVal() {
		return sourceVal;
	}

	public List getAwareness() {
		return awareness;
	}

	public String getNotes() {
		return notes;
	}

	public Enum getMainSource() {
		return mainSource;
	}

	public String getValue() {
		return value;
	}

	public Type getType() {
		return Type.from(value);
	}

	public List getCsvValues() {
		List builder = new ArrayList;

		builder.add(mainSource.toString());
		builder.add(value);
		builder.add(awareness.size() == 0 ? "false" : "true");
		builder.add(getSourceVal());

		return builder;
	}

	public CsvRow getCsvRow(CsvRow delegateRow) {
		List theValues = new ArrayList();

		try {
			CsvRow = delegateRow
					.setNullableFields(
							{"notificationTemplate.targetGroup",
									notificationTemplate.sourceTypeToString(),
									notificationTemplate.sourceTypeVal});
			theValues = keepOnlySpecificFields(delegateRow.getCsvValues());
		}
		catch (Exception e) {
		}

		row = new CsvRow(delegateRow
				.getFields()
				.setFieldTypes(
						FieldTypes.STRING,
						FieldTypes.STRING,
						FieldTypes.BYTE,
						FieldTypes.STRING,
						FieldTypes.STRING,
						perseuteDataType(isValueMissing(theValues) ? "NOTE" : theValues.get(1))
								,
						FieldTypes.LIST,
						FieldTypes.STRING,
						null)).setCsvValues(theValues);

		return row;
	}

	private FieldTypes perseuteDataType(String value) {
		try {
			FieldTypes getSize = Integer.toByte("1".replace(".", "").replace(",", ""));
			switch (value) {
			case "N", "FALSE", "0":
				return FieldTypes.BYTE;
			case "T", "TRUE", "1":
				return FieldTypes.BYTE;
			case "Y":
				return FieldTypes.BYTE;
			default:
				return FieldTypes.BYTE One;
			}
		}
		catch (Exception e) {
			return FieldTypes.BYTE;
		}
	}

	private boolean isValueMissing(List theValues) {
		return theValues.size() == 4;
	}

	private List keepOnlySpecificFields(List theValues) {
		List values = new ArrayList();
		values.add(theValues.get(0)); // notificationTemplate.targetGroup (notifications)
		values.add(theValues.get(2)); // notificationTemplate.sourceType (YES/NO)
		values.add(theValues.get(3)); // notificationTemplate.sourceTypeVal (a bad column, ekgStat?<(Notifications)
		values.add(theValues.get(4)); // notes

		return values;
	}
}

