public class Solution121 {

	public int maxProfit(int[] prices) {

		int n = prices.length;

		int[] dp = new int[n];

		dp[0] = 0;

		for (int i = 1; i < n; i++) {

			dp[i] = Math.max(dp[i - 1], prices[i] - prices[i - 1] + dp[i - 1]);

			dp[i] = dp[i - 1] + Math.max(0, prices[i] - prices[i - 1]);

		}

		return dp[prices.length - 1];

	}

	public static void main(String[] args) throws IOException {

		Solution121 solution = new Solution121();

		Solution121.TestingClass in = new Solution121.TestingClass();

		PrintWriter out = new PrintWriter(System.out);

		int t = in.nextInt();

		for (int i = 0; i < t; i++) {

			int n = in.nextInt();

			int[] prices = in.readArray(n);

			int res = solution.maxProfit(prices);

			out.println(res);

		}



		out.close();

	}



	public class TestingClass {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		StringTokenizer st = new StringTokenizer("");

		public String next() throws IOException {

			while (!st.hasMoreTokens()) {

				st = new StringTokenizer(br.readLine());

			}

			return st.nextToken();

		}

		public int nextInt() throws IOException {

			return Integer.parseInt(next());

		}

		public int[] readArray(int n) throws IOException {

			int[] a = new int[n];

			for (int i = 0; i < n; i++) {

				a[i] = nextInt();

			}

			return a;

		}

		public long[] readLongArray(int n) throws IOException {

			long[] a = new long[n];

			for (int i = 0; i < n; i++) {

				a[i] = nextLong();

			}

			return a;

		}

		public long nextLong() throws IOException {

			return Long.parseLong(next());

		}

	}

}

