import java.io.*;

public class C {

	/**

	*/
	public static class Solution implements FastIO.Solver {

		private FastIO io;

		private StringBuilder out = new StringBuilder();
		private boolean multi;

		@Override
		public void init() throws Exception {
			multi = io.multi();
			out = io.multi() ? new StringBuilder() : null;
		}

		@Override
		public void solve() {

			String s = io.nextLine();

			int[] res = parseIntArr(s);

			long p = res[0];

			long n = res[1] - 1;

			long d = res[2];

			long t = 86400 + p * d - n * 2;

			out.append((t <= 0 ? 0 : t));

			out.append(System.lineSeparator());
		}

		private int[] parseIntArr(String s) {

			String[] arrStr = s.split("\\s+", 5);

			int[] res = new int[3];

			for(int i = 0; i < 3; i++) {
				res[i] = parseInt(arrStr[i]);
			}
			return res;
		}

		public String getRes() {

			return out.toString().replace("\r\n", System.lineSeparator());
		}

		public static void main(String[] args) throws Exception {

			String res = new C().run();
			//String res = runCode(new C());
			System.out.println(res);
		}

		public String run() throws Exception {

			io = new FastIO(multi, System.in, System.out);

			io.init(this);
			io.solve();
			io.close();
			return io.result();
		}
	}

	/**

	 */
	public static interface Solver {

		void init() throws Exception;

		void solve();

	}

	/**
	 * Fast IO solution class
	 */
	public static class FastIO {

		public String result = "";

		public FastIO(boolean multi, final InputStream in, final OutputStream out) {

			this.in = in;
			this.out = out;
			this.multi = multi;
		}

		public FastIO(boolean multi, File in, File out) throws Exception {

			this(new FileInputStream(in),new FileOutputStream(out),multi);
		}
		private final InputStream in;
		private final OutputStream out;
		private boolean multi;

		public InputStream getIn() {
			return in;
		}

		public OutputStream getOut() {
			return out;
		}

		public BufferedReader br = new BufferedReader(new InputStreamReader(in));

		private void read() throws IOException {

			String res = br.readLine();
			result += (res + System.lineSeparator());
			reses.add(res);
		}
		public void close() throws IOException {

			ioClose();
			br.close();
			out.close();
		}

		/**

		@throws IOException
		 */
		public void ioClose() throws IOException {

			if(!multi) out.flush();
		}

		public void init(final Solver solver) throws Exception {

			String[] res;
			while(!st.endOfInput(br)) {
				solver.init();
				res = new String[] {read(), solve()};
				ioSolve(solver, res);
			}
			ioClose();
		}

		private List resultes = new ArrayList();
		private final ArrayList solveres = new ArrayList>();

		private void ioSolve(final Solver solver, String[] res) throws Exception {
			solver.solve();
			if(res.length == 1) {
				result += solver.getRes();
			}else {
				resultes.add(res[0]);
				solveres.add(solver);
				result += res[1];
			}
		}
		private final BufferedReader br;
	}
}

