import static com.xiaoleilu.hutool.util.StrUtil.isEmpty;

/**
 * 
 * @author Looly
 * @since 3.0.0
 */
public class ModuleConfig {

	/**
	 * 
	 * @param module new instance of the updated module
	 * @param filePath
	 * @return 0 on success
	 */
	public static int updateModule(Module module, String filePath) {
		if (module == null) {
			throw new NullPointerException("module is null");
		}
		if (isEmpty(filePath)) {
			throw new ConfigException("filePath is empty");
		}
		Config config = Config.create(filePath);
		config.setModule(module);
		File configFile = config.getConfigFile();
		return configFile.isFile() ? config.save() : config.save(true);
	}

}

