} from 'three';

import { Point } from '../math';

const epsilon = 1e-4;

export default function ConvexPolyhedron(points, faces) {
	if (!faces.length) {
		return new ConvexGeometry(points);
	}

	const faceNormals = [];
	const pointsIndex = new Map();

	let maxZ = -Infinity;
	let maxZIndex = -1;

	for (let i = 0; i < faces.length; i++) {
		const face = faces[i];
		const point1 = points[face[0]];
		const point2 = points[face[1]];
		const point3 = points[face[2]];

		const normal = new Point(point1.x, point1.y, point1.z)
			.add(point2.x, point2.y, point2.z)
			.add(point3.x, point3.y, point3.z)
			.multiplyScalar(0.333)
			.sub(point1)
			.normalize();

		const z = point1.z + normal.z * epsilon;

		if (z > maxZ) {
			maxZ = z;
			maxZIndex = i;
		}

		faceNormals.push(normal);
	}

	let minZ = Infinity;
	let minZIndex = -1;

	for (let i = 0; i < faces.length; i++) {
		const face = faces[i];

		const point1 = points[face[0]];
		const point2 = points[face[1]];
		const point3 = points[face[2]];

		const z = point1.z + faceNormals[i].z * epsilon;

		if (z < minZ) {
			minZ = z;
			minZIndex = i;
		}
	}

	faces.splice(minZIndex, 1);

	return new ConvexGeometry(points, faces);
}

