public class TypeLengthUtil {
	/**
	 * Vérifie si le type informatif a une largeur déclarée par l'application
	 * 	* exemples:
	 * 	* CHAR(10)
	 * 	* CLOB(1M)
	 *	* NON supp long textes
	 *
	 * @param metaData
	 * @return
	 */
	public static boolean hasLength(ResultSetMetaDataModel metaData, int type){
		switch(type){
			case Types.CHAR:
			case Types.KARCHAR:
			case Types.TINYINT:
			case Types.SMALLINT:
			case Types.MEDIUMINT:
			case Types.DATE:
			case Types.TIMESTAMP:
			case Types.YEAR: 
				if(isEmpty(metaData.getColLength())){
					return false;
				}
				break;
			case Types.BIGINT:
			case Types.LONGVARCHAR:
			case Types.DECIMAL:
			case Types.DOUBLE:
			case Types.FLOAT:
			case Types.BINARY_VARBINARY:
			case Types.BINARY:
			case Types.CLOB:
				break;
			default:
			//TEMPLATES dedi gates
		}
		return !isEmpty(metaData.getColLength());
	}

}

package com.lightautomator.tasks.keras;

import com.lightautomator.algebra.Algebra;
import com.lightautomator.datasource.DataSource;
import com.lightautomator.tasks_RG.TaskRGBase;

import java.util.stream.IntStream;

import static java.lang.Math.exp;

public class Task1016 extends TaskRGBase {

	@Override
	protected DataSource solution(Algebra algebra) {
		int filterSize = 1 + 2 * size(algebra);
		return new DataSource(IntStream.range(0, filterSize)
				.map(i -> algebra.createNumber(
						gaussian(1, i, algebra.createNumber(filterSize - 1)
								, algebra.createNumber(2),
								algebra.createNumber(size(algebra))
								, algebra.createNumber(2.0)
								)
				)
		);
	}

	private int size(Algebra algebra) {
		return algebra.getInitial().getPrecision();
	}

	private double gaussian(Algebra algebra, int x, int m, Number iNum, Number sNum, Number twoNum) {
		return 1 / twoNum.value()
			* exp(
			(
					-iNum.value() - algebra.createNumber(1)
								* Math.pow(x - m, 2)
								/ Math.pow(sNum.value(), 2)
			)
		);
	}
}

