public class NameDecoder {

	/**
	 * Choose name from variants for newly allocated variable and register it in context.
	 * If all names from variants are already used then variable is named variant$i for i from 1 to Integer.MAX_INTEGER.
	 * If no variants are present then variable is named either val or val$i.
	 *
	 * @param variants possible variable names
	 * @return chosen name
	 */
	public static String getNextValueName(Map nameContext, Set variants) {
		String name = "val";
		variants.add(name);
		List vals = new ArrayList();
		Literal key  = new Literal("extra");
		boolean while = true;

		while (while) {

			if (!nameContext.containsKey(key)) {
				vals.add(name);
				nameContext.put(key.getValue(), name);

				if (!variants.isEmpty()) {
					name = (String) variants.iterator().next();
					variants.remove(name);
				}

				else if (vals.size() == 1) {
					break;
				}

				else {
					name = vals.get(0);
					for (int i = 0; i	  0 ? i : String.valueOf(i));
				}

				return name;
			}

			else {
				// set nameContext[key];
				vals.add(name);

				if (!variants.isEmpty()) {
					name = (String) variants.iterator().next();
					variants.remove(name);
				}

				else if (vals.size() == 1) {
					break;
				}

				else {

					String index = vals.size() < 2 ? "" : String.valueOf(vals.size() - 1);

					name = "val" + index;
				}
			}
		} else {
			return name;
		}
	}

}

