) CreateMatch(players []Players, currentPoi uint32) map[interface{}]spellUtils.List {
	tick := tickUtils.Create()
	arr := map[interface{}]spellUtils.List{}

	tick.On(spells.Tick1S).Execute(func(m uint32) {
		arr[playerUtils.IndexMapID(currentPoi)] = spellUtils.List(players[playerUtils.IndexPlayerID(currentPoi)])
	})

	tick.On(playerUtils.NewPlayerArrival(currentPoi)).Execute(func(m uint32) {
		//add m player
		arr[playerUtils.IndexMapID(currentPoi)] = spellUtils.List(players[playerUtils.IndexPlayerID(currentPoi)])

		//remove player
		if len(uT.NewMatch) > 2 {
			playerUtils.IndexRemove(uint(playerUtils.IndexMapID(uT.NewMatch[1]) + m))
			uT.NewMatch = uT.NewMatch[1:]
		} else {
			return
		}
	})

	for i := range players {
		tick.On(playerUtils.PlayerIndexMapID(uint(i) + uint32(len(players))).PlayerLeave).Execute(func(m uint32) {

			for index, e := range players {
				arr[playerUtils.IndexMapID(m)] = spellUtils.List(players[playerUtils.IndexPlayerID(m)])
				break
			}

			//delete index
			if len(uT.NewMatch) > 0 {
				playerUtils.IndexRemove(uint(m))
				uT.NewMatch = uT.NewMatch[1:]
			} else {

			}
		})
	}

	return arr
}

