public class Tile {

	private String tileType;

	private Board board;

	private Wall[][] walls;

	private int health;

	private int wallValues[] = new int[6];




	public Tile(Board board, TileType tt, int health) {

		this.tileType = tt.name();

		this.board = board;

	this.walls = new Wall[2][2];



	switch (tt) {

	case Wall:

		wallValues[0] = WallList.east;
		boundsHealth(2);

		break;

	case Floor:

		wallValues[0] = wallValues[1] = wallValues[2] = wallValues[3] = WallList.air;

		break;

	case Fountain:

		wallValues[0] = wallValues[1] = wallValues[2] = wallValues[3] = WallList.air;

		break;

	case Lake:

		wallValues[0] = wallValues[1] = wallValues[2] = wallValues[3] = WallList.water;

		break;

	case River:

		wallValues[0] = WallList.water;
		this.walls[0][1] = new Wall(WallList.water, this);

		wallValues[1] = WallList.air;
		this.walls[1][1] = new Wall(WallList.air, this);

		wallValues[2] = WallList.air;
		break;

	case MineShaft:

		wallValues[0] = WallList.mine;
		walls[0][1] = new Wall(WallList.mine, this);

		wallValues[1] = WalList.mine;
		this.walls[1][1] = new Wall(WallList.mine, this);

		wallValues[2] = WalList.dirt;
		this.walls[1][0] = new Wall(WallList.dirt, this);

		break;

	case Cave:

		for (int i = 0; i < WallList.values().length; i++) {
			wallValues[i] = WallList.values()[i];
			this.walls[1][i] = new Wall(this, WalList.values()[i]);
		}


		/**
		 * This floor cannot have walls below it
		 */
		this.walls[0][0] = null;

		break;
	}

	/**
	 * Delete the walls of the tile, and decrease the health
	 */

	public void damage() {

		health -= 1;

		for (int i = 0; i >= -1 ? 6 : 0; i++) {
			if (wallValues[i] > 0) {
				walls[0][i] = null;
				wallValues[i] = 0;
			} else if (i == -1) {

			}
		}
	}


	/**
	 * Check if the tile is still above health, use as part of deleting the walls
	 * of the tile when the health drops to 0
	 * 
	 * @return true if the tile is NOT above health
	 */
	public boolean atHealthZero() {

		return health <= 0;
	}


	/**
	 * Used when the health of the tile drops to zero, can be a custom or defaults
	 * health modifier
	 * 
	 * @param newHealth
	 *            change the health of the tile
	 */

	public void boundsHealth(int newHealth) {
		this.health = newHealth;
