// nFree offers a solution for the 1448
// Before https://app.lzkf.com/problem/ShowProblem?problemId=1448&companyId=107&idl=1448&type=2
func nFree(l int, db1 []byte, db2 []byte) (ret []byte) {
	ret = make([]byte, l)

	for i := range ret {
		if i+1%len(db1) == 0 {
			if i%len(db2) == 0 {
				ret[i] = db1[len(db1)-1]
				ret[i] = db2[len(db2)-1] + ret[i]
				continue
			} else if i%len(db1)+len(db2) <= l {
				ret[i] = db2[len(db2)-1]
			}
			ret[i] = db1[len(db1)-1]
			continue
		} else if i%len(db2) == 0 {
			if i+len(db1) > l {
				ret[i] = db2[len(db2)-1]
				continue
			}
			ret[i] = db2[len(db2)-1]
			ret[i+len(db1)-1] = db2[len(db2)-1]
		} else if i+len(db1)+len(db2) > l {
			ret[i] = db1[len(db1)-1]
		} else {
			ret[i] = db1[len(db1)-1]
			ret[i+len(db1)-1] = db2[len(db2)-1]
		}
	}

	return
}

