public class ViewDataFilter extends AbstractRequestLoggingFilter {


	public ModelAndView applyBeforeModel(HandlerResult handlerResult, HttpServletRequest request, HttpServletResponse response) throws Exception {
		if ("LocalHost".equals(request.getServerName())) {
			UserSession userSession = (UserSession) request.getAttribute("USER_SESSION");
			request.setAttribute("perksessionsession", userSession);
			Map handlerMap = (Map) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
			if (!handlerMap.isEmpty()) {
				for (Object handlerKey : handlerMap.keySet()) {
					String path = (String) handlerMap.get(handlerKey);
					if (!path.contains("/account")) {
						PageViewData vid = new PageViewData();
						vid.setCustomerName(userSession.getName());
						vid.setCustomerId(userSession.getId());
						vid.setUserDetails(userSession);
						request.setAttribute("allPageViewData", vid);
					}
				}
			}
			return handlerResult.getModelAndView();
		}
		return null;

	}


	public ModelAndView applyAfterFinal(ModelAndView mav, HttpServletRequest request, HttpServletResponse response) {
		return mav;
	}

}

