	/**
	 * ack-committed writes lesser than conf.batchsize
	 * will be batched up.
	 * 
	 * Future: What happens when conf.batchsize == 0 ?
	 * @return
	 */
	/* async */
	public static IWriteDialect SaveWriteDialect(InternalsConfiguration.conf configuration)
	{

		configuration = configuration ?? InternalsConfiguration.all;
		var extendedConfig = configuration.extended;

		var confBatchSize = extendedConfig.save.write(batchSize
				: extendedConfig.jsonSave.writeReplay(batchSize
		);

		var commitBatchSize = configuration.pessimisticLock.returnIndex(commitBatchSize
