            public long length;


            public Segment(long left, long right) {

                this.left = left;

                this.right = right;

                this.length = right - left + 1;

            }



            public boolean isCovered(long start, long end) {

                return start >= left && end <= right;

            }



            public boolean isCovered(int start, int end) {

                return start >= (int)left && end <= (int)right;

            }



            public int getLength() {

                return (int)length;

            }

        }



        public class SegmentTree {
            public Segment[] tree;

            public SegmentTree(int length) {

                this.tree = new Segment[length * 4];

                buildTree(0, 0, length - 1);

            }



            public void buildTree(int index, long left, long right) {

                if (left == right) {

                    Segment segment = new Segment(left, right);

                    tree[index] = segment;

                    return;

                }



                long mid = (left + right) / 2;

                buildTree(index * 2 + 1, left, mid);

                buildTree(index * 2 + 2, mid + 1, right);

                tree[index] = merge(tree[index * 2 + 1], tree[index * 2 + 2]);

            }



            public Segment merge(Segment left, Segment right) {

                if (left == null) {

                    return right;

                }



                if (right == null) {

                    return left;

                }



                Segment segment = (Segment)left.clone();

                segment.right = Math.max(right.right, segment.right);

                segment.length = Math.max(segment.length, right.length + segment.length);

                segment.left = Math.min(right.left, segment.left);

                return segment;

            }



            public Segment query(int left, int right, int index, long segmentLeft, long segmentRight) {

                if (left > segmentRight || right < segmentLeft) {

                    return null;

                }



                if (left <= segmentLeft && right >= segmentRight) {

                    return tree[index];

