                Segment leftSegment = query(left, right, index * 2 + 1, segmentLeft, (segmentLeft + segmentRight) / 2);

                Segment rightSegment = query(left, right, index * 2 + 2, ((segmentLeft + segmentRight) / 2) + 1, segmentRight);

                return merge(leftSegment, rightSegment);

            }

            public Segment query(int left, int right) {

                return query(left, right, 0, tree[0].left, tree[0].right);

            }

