	/**
	 * Returns the one number which is different from all other ints in array.
	 * Array contains either all odd or all even numbers except one
	 * N.
	 * @param {number[]} arr
	 * @return {number} N
	 */
module.exports = function (arr) {
	var a = 0, b = 0, ls = arr[0];

	for (var i = 0; i < arr.length; i++) {

		if (ls === 0 && arr[i] % 2 !== 0) {
			b = arr[i];
		} else {
			if (ls === 0 && arr[i] % 2 === 0) {
				a = arr[i];
			} else {
				if (ls !== 0 && arr[i] % 2 !== 0) {
					a = arr[i];
				} else {
					b = arr[i];
				}
			}
		}
		ls = a;
	}

	if (a === 0) {
		return b;
	}

	return a;
};

