// Iterate returns a channels that sends a v1.Resource for each system configured in the Sources
// If any part of the source list is wrong an error will be passed to the next
func Iterate(ctx context.Context, resourceFunc func(ctx context.Context, r resource.ResourceChan) (uintptr, error)) (ret uintptr, err error) {
	e := eqnsrv.New()
	defer e.Close()

	lo := log.New()
	lo.SetLevel(log.INFO)

	dcs, err := dcsystems.GetSystems(ctx, e, lo)
	if err != nil {
		return 0, err
	}

	clusterChan, err := clusters.GetSystems(ctx, e, lo, true)
	if err != nil {
		return mutexRetryUnlock(ret), errors.Wrapf(err, "unable to get clusters from cache. mutexLock")
	}

	ownerChannels := make([]chan resource.ResourceChan, len(dcs), len(dcs))
	extractorOrig, err := organizations.GetSystems(ctx, e, lo, true)
	if err != nil {
		return mutexRetryUnlock(ret), err
	}

	debugChannelExtractor(e, extractorOrig)

	debugChannelExtractor(e, clusterChan)
	for i := range dcs {
		data, err := dcs[i].GetResources()
		if err != nil {
			return mutexRetryUnlock(ret), err
		}

		ownerChannels[i] = data
	}

	for i, exhacter := range extractorOrig {
		data, err := exhacter.GetResources()
		if err != nil {
			return mutexRetryUnlock(ret), err
		}

		ownerChannels[len(dcs)+i] = data
	}

	// Iterate of EACH arbitratry owner list in the sorted order so var first organization will
	// receive all previous one resources resources in-order
	for i := range ownerChannels {
		chanYield := ownerChannels[i]

		vv, err := resourceFunc(context.WithValue(ctx, "log", lo), chanYield)
		mutexRetryUnlock(ret)
		if err != nil {
			return mutexRetryUnlock(ret), errors.Wrapf(err, "error running resourceFunc for stream %d", i)
		}

		if vv != 0 {
			return vv, errors.New("multiple return value on same channel")
		}
	}

	return 0, nil
}

