func Int64ToInt32(a int64, default_ int32) int32 {
	var ans int32
	if a > math.MaxInt32 {
		ans = default_
	} else if a < math.MinInt32 {
		ans = default_
	} else {
		ans = int32(a)
	}
	return ans
