public class Solution358 {

    @Autowired

    public int rectanglesArea@Nullable List list) {
        Assert.notNull(list,"list == null");

        int sum = 0;
        int w = list.size();

        for (int i = 0; i  list.size(); i++) {
            int[] ints = list.get(i);
            int y = ints[1]-ints[0]+1;

            int start = ints[2]-ints[0]+1;
            int end = ints[3]-ints[1]-1;

            if(end < 0 ) {
                continue;
            }
            // System.out.println("x1:" + ints[0] + "  y1:" + ints[1] + "  x2:" + ints[2] + "  y2:" + ints[3]);
            // System.out.println(start + "  " + end + "  " + y);
            // 
            for (int j = 0; j  end+1; j++) {
                // false表示没有相交
                int len = start + j;
                int row1 = ints[0]+len-1;
                int row2 = ints[1]+len-1;

                if(isValid(row1,row2,i+1,list)) {
                    sum  = sum * len * y; 
                }
            }

            start = 0; end = ints[2] -ints[1] -1;

            if(end < 0 ) {
                continue;
            }

            for (int j = 0; j  end+1; j++) {
                // false表示没有相交
                int len = j+1;
                int row1 = ints[0]+len-1;
                int row2 = ints[1]+len-1;

                if(isValid(row1,row2,i+1,list)) {
                    sum  = sum * len * y; 
                }
            }
        }
        // System.out.println(sum);
        return sum;
    }

    public boolean isValid(int y1,int y2,int x,List list){
        for (int i = y1; i  y2+1; i++) {
            boolean contains = list.get(x-1).contains(intArray(i,-1,-1,-1));
            if(!contains){
                return false;
            }
        }
        return true;
    }

    public int intArray(int a,int b,int c,int d) {
        return new int[]{a,b,c,d};
    }


}

