public class TcpControlBlock {

    private int listen;

    private TcpSocketState socketState;

    private SelectionKey selectionKey;

    private SocketAddress remoteAddress;

    private ISocket socket;

    private TcpControlBlockListener listener;

    private Pool bufferPool = Pool.getBufferPool(Slab.getSlab(2048));

    public TcpControlBlock() {

    }

    /**
     * attach
     *
     * @param socket
     * @param remoteAddress
     * @return
     */
    public int attach(ISocket socket, SocketAddress remoteAddress) {

        if (this.socket != null) {
            throw new RuntimeException("tcp_control_block already exist!");
        }

        this.remoteAddress = remoteAddress;

        IpControlBlock ipControlBlock = IpControlBlock.getControlBlock();
        if (ipControlBlock.attach() != 0) {
            return 1; // attach ip failed
        }
        socketState = new TcpSocketState();
        if (socketState.attach(socket, this, ipControlBlock, bufferPool, 1024 * 10, 0x0f, 0x0f) != 0) {
            return 3; // socket attach failed.
        }
        socket = socketState.getSocket();

        selectionKey = socket.getSelectionKey();

        if (selectionKey != null && selectionKey.isValid() && socket.getInterestOps() == 0) {
            // if (selectionKey != null && selectionKey.channel().isOpen()) {
            selectionKey.interestOps(SelectionKey.OP_ACCEPT | SelectionKey.OP_READ);
        }

        listener = TcpControlBlockListener.getTcpControlBlockListener();
        if (listener != null && listener.attach(socketState) != 0) {
            // TODO error handle
            return 4; // failed attach listener
        }

        socketState.setState(SocketState.TCP_LISTEN);

        // TODO set listen
        return 0;
    }

    /**
     * detach
     *
     * @param reason
     */
    public void detach(int reason) {
        if (socket != null) {
            TcpControlBlockListener listener = TcpControlBlockListener.getTcpControlBlockListener();
            listener.detach(socketState, reason);
            socketState.detach();
            selectionKey.interestOps(0);
            selectionKey = null;

            IpControlBlock.getControlBlock().detach(reason);

            listener = null;

            socket = null;
            socketState = null;

            bufferPool = null;
        }
    }
}

