// doesn
// t use array copy
// do by change positions of rotated elements in-place (like http://www.clipartmax.com/mclip2/20071104/12303023_clip-art-of-rotating-a-box
// (swap, swap, swap)
// rows into columns and columns into rows
// to reduce time space complexity, by first do row reversal
// 
// i.e i, n-i -1, n-1-i, i
// then make rows transpose,
// then do columns reversal
// overall, ith row get into n-i-1th column of original array;
// final column of ith row get into ith position;
class Solution {
    public void rotate(int[][] a) {
        int n = a.length;
        // TODO: when i get strong, can optimize it ! 
        for(int col=0; col <n/2; col++){
            for(int row=0; row <n-row-1; row++){
                int temp = a[row][col];
                a[row][col] = a[n-1-col][n-1-row];
                a[n-1-col][n-1-row] = a[n-1-row][col];
                a[n-1-row][col] = temp;
            }
        }
    }
}
